window.__SUM[23]={"LR000009":{"pair":"ADAM15 -> ITGAV","headline":"ADAM15 disintegrin domain specifically binds integrin alphavbeta3 in two papers, one of which tested ten integrins.","interaction_type":"direct binding","direction_and_effect":"Recombinant D-15 (disintegrin-like domain) specifically interacts with alphavbeta3 and not with nine other tested integrins; mutating RGD to SGA blocked binding [PMID:9516430]. Metargidin is an alphavbeta3 ligand on U937 cells and the disintegrin domain mediates adhesion [PMID:9914169].","molecular_requirements":"Binding needs the RGD tripeptide; changing RPTRGD to NWKRGD makes D-15 also recognised by alphaIIbbeta3. alphavbeta1 was not bound, so beta3 pairing matters [PMID:9516430].","affinity_potency":[],"species_and_systems":"GST-D-15 produced in bacteria and tested on mammalian cells expressing recombinant integrins [PMID:9516430]; ADAM15-Fc on human U937 cells [PMID:9914169].","localisation_and_range":"ADAM15 is a membrane-anchored protein; cell-cell interaction proposed [PMID:9516430].","caveats":"Both papers abstract only. IntAct lists an ELISA record [DB:IntAct]. One further row was abstract-insufficient.","key_references":[{"PMID":"9516430","why":"D-15 binds alphavbeta3 specifically; RGD dependent"},{"PMID":"9914169","why":"alphavbeta3 as ADAM15 ligand on U937 cells"}],"covers":["LR000009","LR003559"]},"LR002070":{"pair":"ADAM17 -> TNFRSF1A","headline":"No curated paper confirms this pair; support rests on one BioGRID record.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"TNFRSF1A is flagged transmembrane receptor [flag]; ADAM17 non-secreted [flag].","caveats":"No papers were verified: judged rows were different_entity (4) and abstract_insufficient (5), none confirming. The only support is a BioGRID Biochemical Activity record (PMID 17010968) [DB:BioGRID], which is enzymatic activity, not ligand binding.","key_references":[],"covers":["LR002070","LR005396"]},"LR000018":{"pair":"ADAM2 -> ITGA9","headline":"ADAM2 binds ITGA9 integrins in adhesion assays, including a novel ITGA9-ITGB7 pairing in RPMI 8866 cells.","interaction_type":"direct binding","direction_and_effect":"Adhesion of Tera-2 cells (ITGA9-ITGB1) to ADAM2 was inhibited by an anti-ITGA9 antibody; RPMI 8866 adhesion was inhibited 60% by anti-ITGA9 [PMID:21060781]. Curator label: agonist.","molecular_requirements":"ITGA9 pairs with ITGB1 or, in RPMI 8866 cells lacking detectable ITGB1, with ITGB7 [PMID:21060781].","affinity_potency":[],"species_and_systems":"Human cell lines with recombinant ADAM2 at 50 \u00b5g/ml; anti-ITGB1 antibody inhibited ADAM2 binding to mouse eggs [PMID:21060781].","localisation_and_range":"ADAM2 flagged non-secreted [flag]; adhesion to immobilised ADAM2.","caveats":"Antibody and siRNA adhesion assays rather than purified binding. Percentage inhibition from the excerpts (60%) is for partial inhibition.","key_references":[{"PMID":"21060781","why":"ITGA9-ITGB7 identified as ADAM2 binding partner"}],"covers":["LR000018","LR003568"]},"LR005400":{"pair":"ADAM9 -> ITGA1","headline":"ADAM9 disintegrin adhesion of HEK-293 cells is blocked by anti-alpha1 antibody; alpha1 was not captured in pull-down.","interaction_type":"functional only","direction_and_effect":"Antibodies to alpha1, alpha3, alpha6, alphav and beta1 blocked adhesion of HEK-293 cells to GST-disintegrin protein [PMID:15361064].","molecular_requirements":"Alpha1 acts with beta1; the curator note says alpha1 chain was not recovered in the GST-disintegrin pulldown, unlike alpha3, alpha6 and alphav [PMID:15361064].","affinity_potency":[],"species_and_systems":"Human HEK-293 cells; renal cortical lysates; recombinant GST-disintegrin [PMID:15361064]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM9 is flagged secreted [flag]; the paper describes ADAM9 as expressed in a punctate basolateral distribution on renal tubular cells [PMID:15361064].","caveats":"Abstract read only; support is blocking antibody only, not direct capture.","key_references":[{"PMID":"15361064","why":"ADAM9 disintegrin is a ligand for multiple beta1 integrins"}],"covers":["LR002074","LR005400"]},"LR000027":{"pair":"ADCYAP1 -> SCTR","headline":"PACAP shows only weak, low-affinity activity at a secretin-preferring site in guinea pig chief cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"PACAP-38 and secretin both increased pepsinogen release from isolated guinea pig chief cells, with biphasic (PACAP) versus monophasic (secretin) curves; secretin had a >500-fold lower affinity than PACAP-38 for displacing 125I-PACAP-27 and 125I-VIP, so PACAP's main site is distinct from the secretin receptor [PMID:1335692].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"secretin 197-fold more potent than PACAP-38","assay":"displacement of 125I-secretin","system":"isolated guinea pig chief cells","cite":"PMID:1335692"}],"species_and_systems":"Guinea pig gastric chief cells (native receptors), not human or mouse recombinant SCTR [PMID:1335692]; the human and mouse pairs are ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; BioGRID lists a protein-peptide record from the same paper [DB:BioGRID].","caveats":"Weak off-target cross-reactivity, not PACAP's primary receptor pairing; SCTR identity is inferred from a secretin-preferring site; abstract read only; database support derives from the same paper.","key_references":[{"PMID":"1335692","why":"PACAP and VIP share a high-affinity site distinct from the secretin receptor"}],"covers":["LR000027","LR003577"]},"LR005022":{"pair":"ADGRB1 -> RTN4RL2","headline":"Direct ectodomain binding of ADGRB1 to RTN4RL2 shown in one full-text paper (CRISPRa screen, flow cytometry, AVEXIS).","interaction_type":"direct binding","direction_and_effect":"ADGRB1 probe stained cells expressing full-length RTN4RL2 but not mock cells [PMID:30477585]. ADGRB1 ectodomain bound all three RTN4R family members directly in both bait-prey orientations [PMID:30477585]. Effect on signalling not reported in our evidence.","molecular_requirements":"ADGRB1 thrombospondin type 1 repeats 1-3 were sufficient for binding [PMID:30477585]. RTN4RL2 is described as GPI-linked [PMID:30477585].","affinity_potency":[],"species_and_systems":"Human proteins in HEK293 cells and recombinant ectodomains; mouse pair is ortholog-inferred, not tested in our evidence [PMID:30477585].","localisation_and_range":"Both partners carry secreted and receptor flags [flag]; the paper describes RTN4RL2 as GPI-linked membrane protein [PMID:30477585], so likely contact-dependent.","caveats":"Single paper; one screen per bait. The paper notes that one RTN4R member was not enriched in the screen, attributed to surface presentation [PMID:30477585]. No affinity reported.","key_references":[{"PMID":"30477585","why":"CRISPRa screen with ADGRB1 probe plus direct ectodomain binding"}],"covers":["LR001634","LR005022"]},"LR000036":{"pair":"ADM -> MRGPRX2","headline":"Papers show MRGPRX2 activated by PAMP, a proadrenomedullin peptide, not by mature adrenomedullin; support is for a processed fragment.","interaction_type":"functional only","direction_and_effect":"MrgX2 was specifically activated by PAMP, with potency PAMP-12 >= cortistatin > PAMP-20, in cAMP inhibition, Ca2+ mobilisation and [35S]GTPgammaS binding assays [PMID:15823563]. MrgX2 couples to Galphaq and Galphai [PMID:15823563]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The acting form is the PAMP fragment (PAMP-12 most potent) [PMID:15823563]. A shared structural motif with cortistatin was identified [PMID:16111673]. Co-receptors not reported.","affinity_potency":[],"species_and_systems":"Human receptor; expressed in adrenal chromaffin cells and dorsal root ganglia per immunostaining [PMID:15823563]. PDB 7VV0 and UniProt also listed [DB:PDB 7VV0][DB:UniProt].","localisation_and_range":"ADM-derived peptide, ADM flagged secreted [flag].","caveats":"Abstract only. Evidence is about PAMP, a peptide from the ADM precursor, not demonstrated for adrenomedullin itself. No affinity values.","key_references":[{"PMID":"15823563","why":"MrgX2 activation by PAMP"},{"PMID":"16111673","why":"PAMP structure-activity for MrgX2"}],"covers":["LR000036"]},"LR000045":{"pair":"AGT -> AGTR1","headline":"Angiotensin peptides (mainly Ang II) are well established AT1 agonists by binding and functional papers; the evidence is for processed peptides, not full-length AGT.","interaction_type":"direct binding","direction_and_effect":"Angiotensin II caused concentration-dependent inositol phosphate accumulation in CHO-K1 cells expressing human AT1, with an EC50 of 3.4 nM [PMID:10193788]. Ang II exerts its major physiological effects by activating AT(1) receptors [PMID:12006574]. Ang A is a full agonist for AT(1) receptors in vitro and its pressor effects were almost abolished in AT(1a)-deleted mice [PMID:21464395]. GtoPdb lists full and partial agonist records [DB:GtoPdb]. In mouse AgRP neurons, losartan abolished an Ang-II-induced decrease in firing rate, supporting AT1R involvement [PMID:37540598].","molecular_requirements":"The active ligand is a processed peptide: Ang II, and the related Ang III, Ang IV and Ang A, not full-length angiotensinogen. Reactome lists AGT(25-32) binding AGTR1 [DB:Reactome]. Ang II Arg(2)-Asp(281) contact is required for potency; Ang IV is only potent at a constitutively active N111G mutant [PMID:12006574].","affinity_potency":[{"value":"EC50 3.4 nM","assay":"inositol phosphate accumulation","system":"CHO-K1 cells, human AT1","cite":"PMID:10193788"},{"value":"pEC50 5.9","assay":"inositol phosphate generation (Ang IV, N111G mutant)","system":"CHO-K1 cells, human AT1","cite":"PMID:12006574"},{"value":"pEC50 8.17","assay":"AT1 agonist activity of Ang A in vitro","system":"AT1 receptors (in vitro)","cite":"PMID:21464395"},{"value":"pIC50 9.0 to 9.3","assay":"GtoPdb binding record","system":"not stated in dossier","cite":"PMID:10193788"}],"species_and_systems":"Human AT1 in CHO-K1 cells [PMID:10193788] [PMID:12006574]; rat and mouse in vivo for Ang A [PMID:21464395]; mouse AgRP neurons [PMID:37540598]. Human pair is not ortholog-inferred.","localisation_and_range":"Angiotensin peptides are secreted hormones and AGTR1 is a transmembrane receptor [flag]; the paper describes Ang II as a circulating vasopressor [PMID:10993080].","caveats":"Several papers are weak for this pair: PMID:10993080 concerns AT1-B2 heterodimerisation and PMID:2775266 classifies receptor subtypes. In AgRP neurons, AT1A signalling switches between Gai inhibition and Gaq stimulation, and an AT2R-mediated excitation also occurs [PMID:37540598]. Mostly abstract-read. One paper was judged different_entity and one review_only.","key_references":[{"PMID":"10193788","why":"Ang II binding and IP signalling at human AT1 in CHO-K1 cells; EC50 3.4 nM"},{"PMID":"12006574","why":"Roles of Ang II N- and C-terminal residues at human AT1"},{"PMID":"21464395","why":"Ang A pressor effects depend on AT1a (knockout mice)"}],"covers":["LR000045"]},"LR003600":{"pair":"ALB -> LRP2","headline":"Megalin binds albumin in purified-receptor column binding and mediates its renal tubular uptake in rat; one paper, abstract only.","interaction_type":"direct binding","direction_and_effect":"Megalin acts as an uptake receptor: in rat proximal tubules in vivo, 125I-RSA uptake was inhibited by RAP (>50%) and by cold RSA; BSA-gold uptake was reduced by RAP to 17%, by EDTA to 19%, by BSA to 16% and by megalin to 35% [PMID:8898021].","molecular_requirements":"Megalin-Sepharose columns bound 125I-BSA and 125I-RSA, inhibited by RAP and EDTA [PMID:8898021].","affinity_potency":[],"species_and_systems":"Rat tubule microinfusion with rat and bovine albumin and purified megalin; the abstract does not give the megalin species. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"Endocytic receptor on proximal tubule; ligand flagged secreted [flag].","caveats":"Single paper, abstract only. No affinity. No database records.","key_references":[{"PMID":"8898021","why":"In vivo tubular uptake and megalin-column binding of albumin"}],"covers":["LR000050","LR003600"]},"LR005031":{"pair":"ALCAM -> NRP1","headline":"Antibody blocking suggests Nrp1 is needed for ALCAM-promoted axon growth of mouse midbrain dopamine neurons; no direct binding shown in our evidence.","interaction_type":"functional only","direction_and_effect":"ALCAM promoted axon growth of mouse midbrain dopamine neurons, and neutralizing antibodies for Nrp1 abolished the effect; the authors propose a trans-heterophilic interaction [PMID:31300520]. ALCAM also abolished Sema3A's growth effect and induced branching with Sema3C [PMID:31300520].","molecular_requirements":"Nrp1 is described as one of three components of a Semaphorin receptor complex (Nrp1, Chl1, L1cam) [PMID:31300520]; which is needed alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine primary midbrain cultures [PMID:31300520]; curator records human for both partners.","localisation_and_range":"ALCAM acts as an extracellular substrate presented to cell-bound partners (juxtacrine/matrix-like) [PMID:31300520]. ","caveats":"Single paper, abstract only; inhibition by antibodies is indirect and shows no binding. No affinity.","key_references":[{"PMID":"31300520","why":"Antibody blocking of Nrp1/Chl1/L1cam abolishes ALCAM growth effect"}],"covers":["LR001643","LR005031"]},"LR000054":{"pair":"ANGPT1 -> ITGB1","headline":"Integrin-mediated cell adhesion to angiopoietin and alpha5beta1 binding by an Ang1 fragment; chain-level evidence, abstract only.","interaction_type":"direct binding","direction_and_effect":"Monomeric DeltaAng1 bound alpha(5)beta(1) integrin with similar affinity compared with Tie2 and stimulated endothelial adhesion and MAPK activation [PMID:15781448]. HUVECs adhered and spread on Ang-1, and the adhesion was independent of Tie2 per the abstract [PMID:11346644].","molecular_requirements":"Binding was shown for the alpha5beta1 heterodimer, not ITGB1 alone [PMID:15781448]. The title of PMID:11346644 states the adhesion is integrin-mediated, but the dossier abstract is truncated and names no specific integrin chain.","affinity_potency":[],"species_and_systems":"Recombinant human DeltaAng1 and endothelial cells, chick CAM [PMID:15781448]; HUVECs and fibroblasts with or without Tie2 [PMID:11346644].","localisation_and_range":"ANGPT1 is flagged as secreted [flag]; the cell-adhesion result implies the ligand can act as an immobilised substrate [PMID:11346644].","caveats":"Both confirming papers are abstract only; no numeric affinity. Conflicting or negative row: a mouse neuronal study judged pair_absent only noted beta1 integrin on neurons and that it was previously found to act as an Ang receptor [PMID:15690488]; it is not a direct test. Three further rows were abstract_insufficient.","key_references":[{"PMID":"15781448","why":"Monomeric Ang1 fragment binds alpha5beta1 with affinity similar to Tie2"},{"PMID":"11346644","why":"Integrin-mediated, Tie2-independent cell adhesion to Ang-1"}],"covers":["LR000054","LR003604"]},"LR005040":{"pair":"Angptl2 -> Itgb1","headline":"Mouse Angptl2 acts through integrin alpha5beta1 in chondrocytes; functional evidence only, via the heterodimer rather than ITGB1 alone.","interaction_type":"functional only","direction_and_effect":"Changing ANGPTL2 expression altered p38 MAPK activity mediated by integrin alpha5beta1 in ATDC5 cells and in Angptl2 knockout mice [PMID:29074299].","molecular_requirements":"The evidence is for alpha5beta1; ITGB1 alone (the beta1 chain) is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Mouse chondrogenic ATDC5 cells (Angptl2 knockdown) and Angptl2 knockout mice [PMID:29074299].","localisation_and_range":"Ligand flagged secreted [flag]; ANGPTL2 accumulates in extracellular matrix around chondrocytes [PMID:29074299].","caveats":"One paper only, and it shows downstream signalling, not binding. Direct binding to ITGB1 is not reported in our evidence.","key_references":[{"PMID":"29074299","why":"ANGPTL2 and integrin alpha5beta1-dependent p38 signalling in chondrocytes"}],"covers":["LR005040"]},"LR002115":{"pair":"ANGPTL4 -> ITGB5","headline":"ANGPTL4 is reported to bind integrin \u03b25 directly; abstract-level paper plus IntAct SPR and co-IP records.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4 binds integrins \u03b21 and \u03b25, but not \u03b23, as novel binding partners [PMID:20952587]. The downstream FAK-Src-PAK1 signalling in the paper is attributed to \u03b21-bound ANGPTL4, so an effect through \u03b25 is not reported in our evidence [PMID:20952587].","molecular_requirements":"Integrin \u03b25 alone is named; \u03b1 partner not reported in our evidence.","affinity_potency":[],"species_and_systems":"Keratinocyte/mouse wound model; species of binding assays not recorded [PMID:20952587]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 flagged secreted; ITGB5 flagged receptor [flag].","caveats":"Abstract only. IntAct lists surface plasmon resonance and anti-bait co-immunoprecipitation from PMID 21397862 [DB:IntAct].","key_references":[{"PMID":"20952587","why":"ANGPTL4 binds integrins \u03b21 and \u03b25 but not \u03b23"}],"covers":["LR002115","LR005437"]},"LR002124":{"pair":"ANGPTL5 -> LILRB5","headline":"ANGPTL5 binds LILRB5-overexpressing cells with lower affinity than LILRB2; flow cytometry only.","interaction_type":"functional only","direction_and_effect":"GST-Angptl5 bound LILRB5-overexpressing cells, with lower affinity than to LILRB2-expressing cells [PMID:22660330]. Signalling effect is not reported in our evidence.","molecular_requirements":"not reported in our evidence; the evidence is cell binding, not a purified-protein assay.","affinity_potency":[],"species_and_systems":"Human LILRB5 overexpressed in cells; human ligand [PMID:22660330].","localisation_and_range":"ANGPTL5 flagged secreted; LILRB5 flagged receptor [flag].","caveats":"No affinity value in our evidence; paralog of the primary receptor LILRB2.","key_references":[{"PMID":"22660330","why":"GST-Angptl5 binds LILRB5 cells at lower affinity than LILRB2"}],"covers":["LR002124"]},"LR000063":{"pair":"ANXA1 -> FPR1","headline":"Annexin A1 N-terminal peptides activate FPR on human neutrophils; intact-protein activity is not shown.","interaction_type":"functional only","direction_and_effect":"Peptides from the N-terminal domain of annexin I act as FPR ligands on human neutrophils, triggering dose-dependent Ca2+ transients, inhibiting transendothelial migration and desensitising chemoattractant responses [PMID:10882119]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Peptides Ac1-26 and Ac9-25 but not Ac1-18 interfered with transendothelial passage at 20 \u00b5M, so the N-terminal region matters [PMID:10882119].","affinity_potency":[{"value":"pEC50 5.800000190734863 to 6.099999904632568","assay":"GtoPdb agonist record","system":"not stated","cite":"PMID:10882119"}],"species_and_systems":"Human neutrophils in vitro [PMID:10882119]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANXA1 flagged secreted but not transmembrane; FPR1 transmembrane [flag].","caveats":"Evidence is for peptides, not the intact protein; abstract plus excerpts. BioGRID has an affinity capture-western record [DB:BioGRID]. Three further rows are pending.","key_references":[{"PMID":"10882119","why":"Annexin I N-terminal peptides act as FPR ligands on human neutrophils"}],"covers":["LR000063","LR003613"]},"LR012132":{"pair":"APCDD1 -> FZD10:LRP5","headline":"APCDD1 interacts in vitro with LRP5 and inhibits Wnt signalling; no evidence for this specific FZD10 subunit.","interaction_type":"direct binding","direction_and_effect":"APCDD1 is described as a Wnt inhibitor: it inhibits Wnt signalling cell-autonomously and upstream of beta-catenin, and represses Wnt reporters and target genes [PMID:20393562]. The paper reports an in vitro interaction with WNT3A and LRP5 [PMID:20393562]; IntAct and UniProt record the LRP5 interaction [DB:IntAct, DB:UniProt].","molecular_requirements":"Only LRP5 is shown to interact with APCDD1; FZD10 is not mentioned in the evidence sentence or abstract, so the complex-level pair rests on the LRP5 chain alone. A CCC tool scoring by the least-expressed subunit would add a requirement for FZD10 that our evidence does not support.","affinity_potency":[],"species_and_systems":"Human genetics and human cells for the interaction in vitro; Wnt inhibition also in chick neural development and Xenopus embryos [PMID:20393562].","localisation_and_range":"APCDD1 is described as a membrane-bound glycoprotein [PMID:20393562]; it is not flagged as secreted in the dossier, so juxtacrine or cell-autonomous action is more likely than long-range signalling.","caveats":"Single paper, abstract plus excerpts. Chain-only evidence (LRP5); no data for FZD10. The interaction is 'in vitro' with no affinity. APCDD1 may act as a Wnt-pathway inhibitor rather than a classical ligand.","key_references":[{"PMID":"20393562","why":"APCDD1 interacts with LRP5 and WNT3A and inhibits Wnt signalling."}],"covers":["LR012132"]},"LR002133":{"pair":"APLP2 -> CNTN5","headline":"APLP2 binds CNTN5 in one paper by binding assays and biolayer interferometry; affinity is weak.","interaction_type":"direct binding","direction_and_effect":"APLP2 association with CNTN5 was detected in extracellular binding assays and confirmed by biolayer interferometry; APLP2 binds CNTN4 and CNTN5 but not CNTN3 [PMID:34958801]. Signalling effect is not reported in our evidence.","molecular_requirements":"The conserved interface involves the second fibronectin type III repeat of CNTNs and the copper-binding domain of amyloid proteins, shown for five CNTN-amyloid pairs; a CNTN5-APLP2 structure is not listed [PMID:34958801].","affinity_potency":[{"value":"38 \u03bcM","assay":"biolayer interferometry (approximate, as written)","system":"CNTN5 with APLP2","cite":"PMID:34958801"}],"species_and_systems":"Human and mouse proteins and zebrafish proteins were used; the species of the CNTN5-APLP2 measurement is not stated in the excerpt [PMID:34958801]. Mouse pair is ortholog-inferred.","localisation_and_range":"APLP2 carries transmembrane and secreted flags [flag]; CNTNs are GPI-anchored [PMID:34958801], suggesting contact signalling.","caveats":"Affinity is weaker than for CNTN5-APP [PMID:34958801]. Single paper.","key_references":[{"PMID":"34958801","why":"Binding, BLI affinity and conserved interface"}],"covers":["LR002133","LR005450"]},"LR007101":{"pair":"APOA2 -> TREM2:TYROBP","headline":"Database records only; the single paper judged was review-only.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a TREM2-APOA2 reconstituted complex and UniProt names APOA2 among TREM2 ligands [DB:BioGRID][DB:UniProt]. Effect not reported in our evidence.","molecular_requirements":"Complex members TREM2 and TYROBP [flag]; subunit requirement not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"TYROBP is flagged transmembrane and TREM2 flagged secreted [flag].","caveats":"Only a review-only row was judged; no primary paper confirmation. The records concern TREM2, not the complex.","key_references":[],"covers":["LR007101"]},"LR002142":{"pair":"APOC1 -> VLDLR","headline":"No evidence that APOC1 binds VLDLR as a ligand; the one paper judged shows APOC1 inhibits lipoprotein clearance via VLDLR.","interaction_type":"database-asserted only","direction_and_effect":"The paper indicates apoC1 inhibits clearance of lipoprotein particles via the VLDLR, not via the LDLR, and VLDLR gene transfer did not reduce hyperlipidaemia in APOC1 transgenic mice [PMID:10024503]. That is an inhibitor-of-VLDL-binding effect, not APOC1 acting as a VLDLR ligand.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"APOC1 transgenic, LDLR-deficient and wild-type mice with adenoviral gene transfer; CHO cells expressing VLDLR [PMID:10024503].","localisation_and_range":"APOC1 flagged secreted; VLDLR carries transmembrane and receptor flags [flag].","caveats":"Curators judged this paper pair_absent (two such rows), with one review-only and four abstract_insufficient. Reactome records cover VLDLR binding VLDL, not APOC1 [DB:Reactome].","key_references":[],"covers":["LR002142","LR005459"]},"LR000072":{"pair":"APOE -> LDLR","headline":"Structural NMR/SPR work shows ApoE peptides bind LDLR repeat LR5; also database-supported; abstract read only.","interaction_type":"direct binding","direction_and_effect":"NMR and SPR showed a peptide encompassing the putative ApoE binding region binds the hydrophilic convex face of LDLR repeat LR5; complexes weakened at low Ca2+ and low pH, favouring endosomal dissociation [PMID:24447298]. Reactome and IntAct (NMR, pull down) records also list the pair [DB:Reactome] [DB:IntAct].","molecular_requirements":"Binding used the LR5 repeat alone with ApoE peptides, not intact receptor with lipoprotein; the authors suggest LDLR may use more than one repeat to bind multivalent ApoE particles [PMID:24447298].","affinity_potency":[],"species_and_systems":"In vitro with peptides and a receptor fragment; species not stated in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted [flag]; lipoprotein-associated ApoE is taken up by the receptor in the Reactome records [DB:Reactome].","caveats":"Six other papers were abstract-insufficient and one unresolvable. Evidence is peptide-level only.","key_references":[{"PMID":"24447298","why":"NMR/SPR of ApoE peptide with LDLR LR5"}],"covers":["LR000072","LR003621"]},"LR002151":{"pair":"APOM -> LRP2","headline":"Surface plasmon resonance and megalin-dependent uptake support apoM-megalin binding; abstract level.","interaction_type":"direct binding","direction_and_effect":"Recombinant apoM bound immobilised megalin (Kd approximately 0.3-1 microm) and was endocytosed by cultured rat yolk sac cells in a megalin-dependent manner [PMID:16099815]. Kidney-specific megalin-deficient mice excreted apoM in urine, suggesting megalin-mediated endocytosis prevents loss [PMID:16099815]. Acts as clearance receptor, not signalling.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd approximately 0.3-1 microm","assay":"surface plasmon resonance","system":"recombinant E. coli apoM on immobilised megalin","cite":"PMID:16099815"}],"species_and_systems":"Human apoM, rat yolk sac cells and mouse knockouts [PMID:16099815]. Human pair is ortholog-inferred.","localisation_and_range":"ApoM flagged secreted [flag]; megalin acts in kidney proximal tubule cells [PMID:16099815].","caveats":"Abstract only; one confirmed paper shown of two.","key_references":[{"PMID":"16099815","why":"SPR Kd and megalin-deficient mice"}],"covers":["LR002151","LR005466"]},"LR000081":{"pair":"APP -> FPR2","headline":"Amyloid-beta (derived from APP) activates FPR2 in chemotaxis and calcium assays; functional agonist evidence from two papers and GtoPdb.","interaction_type":"functional only","direction_and_effect":"Abeta(42) is a chemotactic agonist at FPRL1 (FPR2) [PMID:11160457]. FPR2 transfection reconstituted amyloid-beta-dependent chemotaxis and calcium flux in HEK 293 cells, while related receptors including FPR did not [PMID:11316806]. Activity was desensitised by a specific FPR2 agonist and by pertussis toxin, indicating Gi coupling [PMID:11316806]. GtoPdb lists full agonist action [DB:GtoPdb].","molecular_requirements":"Single seven-transmembrane GPCR; no co-receptor reported in our evidence. The active ligand is the Abeta peptide, not full-length APP [PMID:11160457].","affinity_potency":[],"species_and_systems":"Human mononuclear phagocytes and FPRL1-expressing cells [PMID:11160457]; HEK 293 cells and mouse neutrophils and N9 microglia, with FPR2 mRNA detected in mouse brain [PMID:11316806].","localisation_and_range":"Abeta is a secreted peptide acting on a cell-surface receptor; APP is flagged secreted, FPR2 transmembrane [flag]. Range inferred from flags only.","caveats":"Both papers read from abstracts. GtoPdb records pEC50 as the affinity unit, but no values are in our dossier [DB:GtoPdb]. One further paper was judged abstract-insufficient. For single-cell use, note the ligand activity belongs to cleaved Abeta, not APP expression itself.","key_references":[{"PMID":"11160457","why":"Abeta(42) chemotaxis through FPRL1"},{"PMID":"11316806","why":"FPR2 reconstitutes Abeta chemotaxis and calcium flux"}],"covers":["LR000081","LR003630"]},"LR002160":{"pair":"APP -> LRP10","headline":"LRP10 interacts with the APP ectodomain and retains APP at the trans-Golgi network; one paper, mainly a trafficking effect.","interaction_type":"direct binding","direction_and_effect":"LRP10 interacts directly with the APP ectodomain and colocalizes with it at the TGN [PMID:22734645]. LRP10 overexpression in SH-SY5Y cells increased mature APP in the Golgi, lowered cell-surface APP and reduced Abeta production, while LRP10 knockdown increased Abeta [PMID:22734645]. LRP10 mutants lacking TGN-recycling motifs sent APP to early endosomes and raised beta-cleavage [PMID:22734645].","molecular_requirements":"LRP10 shuttles between the TGN, plasma membrane and endosomes; recycling motifs are needed for the effect [PMID:22734645]. No co-receptor reported.","affinity_potency":[],"species_and_systems":"Human SH-SY5Y neuroblastoma cells; LRP10 expression is lower in post-mortem AD brain [PMID:22734645]. Mouse pair is ortholog-inferred.","localisation_and_range":"Largely intracellular trafficking between TGN, surface and endosomes [PMID:22734645]; not a secreted paracrine signal. Flags only mark LRP10 as a receptor [flag].","caveats":"Single paper, abstract plus excerpts. The abstract calls LRP10 a functional APP receptor, but the readout is APP trafficking and processing, not signalling. IntAct lists a solid-phase assay record [DB:IntAct]. Affinity not reported in our evidence.","key_references":[{"PMID":"22734645","why":"LRP10 binds APP and regulates its trafficking"}],"covers":["LR002160","LR005475"]},"LR010710":{"pair":"AREG -> EGFR:ERBB2","headline":"Evidence concerns the EGFR chain only; ERBB2 is not tested.","interaction_type":"direct binding","direction_and_effect":"AR binding to EGFR was unaffected by C-terminal truncation but downstream signalling was impaired [PMID:10085134].","molecular_requirements":"Only the EGFR chain is evidenced; ERBB2 is not addressed for AR binding in the abstract, though ErbB2 overexpression affected Elk-1 transactivation [PMID:10085134]. EGFR alone is therefore the supported unit.","affinity_potency":[],"species_and_systems":"NR6 fibroblasts with human EGFR [PMID:10085134].","localisation_and_range":"AREG flagged secreted [flag].","caveats":"Abstract only; complex-level evidence is absent. GtoPdb and BioGRID records are for AREG-EGFR [DB:GtoPdb] [DB:BioGRID].","key_references":[{"PMID":"10085134","why":"AR-EGFR binding and signalling"}],"covers":["LR010710"]},"LR000090":{"pair":"ASIP -> MC2R","headline":"ASIP inhibits agonist-stimulated cAMP at human MC2R in one 1997 paper (abstract only); a potent antagonist here, no affinity number in our evidence.","interaction_type":"functional only","direction_and_effect":"ASIP is an antagonist: purified recombinant ASIP inhibited agonist-stimulated cAMP generation (alpha-MSH, or ACTH for hMC2R) and also inhibited radiolabeled-melanocortin binding to hMCR1-5. At MC2R it is a potent inhibitor (non-surmountable antagonism (the abstract-level curator note classes hMC2R as non-surmountable)) [PMID:9058374].","molecular_requirements":"Single receptor chain; no co-receptor requirement reported in our evidence. Degree and mechanism of inhibition vary significantly among the five melanocortin receptor subtypes [PMID:9058374].","affinity_potency":[],"species_and_systems":"Human ASIP and human MC2R stably expressed in the adrenocortical OS3 cell line, with ACTH as agonist [PMID:9058374]. Recombinant cell assays, not in vivo.","localisation_and_range":"ASIP is flagged secreted and the receptor as a transmembrane receptor [flag]; the paper calls agouti protein a paracrine signalling molecule (stated for mouse agouti) [PMID:9058374]. ","caveats":"Single paper, read as abstract only. No Kd, Ki or IC50 in our evidence, so potency is qualitative. Schild-analysis details are not available beyond the abstract-level curator note. The same paper covers all five melanocortin receptors, so this is one study counted in five pairs.","key_references":[{"PMID":"9058374","why":"Pharmacology of human ASIP at hMC1R-hMC5R: cAMP and binding inhibition"}],"covers":["LR000090"]},"LR000108":{"pair":"BMP10 -> BMPR1B","headline":"Functional evidence only: ALK6 (BMPR1B) overexpression confers BMP10 signalling in COS7 cells; no binding data in our evidence.","interaction_type":"functional only","direction_and_effect":"Overexpressing ALK3 or ALK6 in COS7 cells conferred BMP10 signalling, measured with a Smad1/5/8 reporter [PMID:16049014]. GtoPdb lists BMP10 as an agonist at BMPR1B [DB:GtoPdb].","molecular_requirements":"ALK6 was one of two type I receptors sufficient in this overexpression assay; a type II partner requirement is not reported for this pair in our evidence.","affinity_potency":[],"species_and_systems":"COS7 cell line, reporter assay, abstract read only; curators annotate human ligand and receptor. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"Signalling readout only. The loss-of-function (shRNA) result in the abstract concerns ALK3, not ALK6.","key_references":[{"PMID":"16049014","why":"ALK6 overexpression confers BMP10 signalling"}],"covers":["LR000108","LR003657"]},"LR000117":{"pair":"BMP2 -> ACVR2A","headline":"Direct binding by SPR and affinity labelling, but BMP2 binds ACVR2A weaker than its type I receptors.","interaction_type":"direct binding","direction_and_effect":"BMP2 bound ACVR2A, ACVR2B and BMPR2 with comparable affinity and activated SMAD1/5/8 in C3H10T1/2 cells [PMID:21702718]. In P19 cells, BMP2 formed heteromeric complexes with ActRII and ActRIIB [PMID:9748228]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Type II binding is at least 10-fold weaker than type I (ALK3 1.1 nM, ALK6 1.6 nM) [PMID:21702718]; BMP2 also bound ALK3 and ALK6 tightly, while ALK2 binding was orders of magnitude weaker [PMID:21702718]. Whether a type I partner is required is not reported in our evidence.","affinity_potency":[{"value":"KD 60.0 nM (SD 40.5)","assay":"SPR, rhBMP2 on ACVR2A","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant human proteins, SPR [PMID:21702718]; mouse P19 cells, [125I]BMP2 affinity labelling [PMID:9748228]. Both human and mouse pairs are experimental.","localisation_and_range":"BMP2 is annotated as secreted and ACVR2A as transmembrane [flag].","caveats":"Abstract-level reads for both; the 1998 paper focuses on BMP7/ALK2 and BMP2 is a side result. The KD has a large SD. One review-only row not shown.","key_references":[{"PMID":"21702718","why":"SPR affinities of BMP2 for type I and type II receptors"},{"PMID":"9748228","why":"BMP2 forms complexes with ActRII/ActRIIB in P19 cells"}],"covers":["LR000117","LR003666"]},"LR007110":{"pair":"BMP2 -> ACVR2A:BMPR1A","headline":"Functional knockdown support only, from one abstract-read hMSC paper; chain-level database records but no complex-specific binding in our evidence.","interaction_type":"functional only","direction_and_effect":"siRNA knockdown in primary human mesenchymal stem cells showed osteoinductive BMP activity is elicited through type I receptors ACVR1A and BMPR1A and type II receptors ACVR2A and BMPR2; effect recorded as agonist [PMID:18436533]. GtoPdb lists BMP2 as agonist at ACVR2A and at BMPR1A separately [DB:GtoPdb].","molecular_requirements":"The paper names both ACVR2A and BMPR1A as required, but ACVR2A was reported as less critical for BMP-2/4 than BMPR2, and BMP-2/4 used BMPR1A predominantly [PMID:18436533]. A requirement for ACVR2A and BMPR1A together as one complex is not shown; the abstract reports concurrent BMPR1A and ACVR1A requirement for part of BMP-2/4 signalling [PMID:18436533].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; primary human mesenchymal stem cells, read on osteoblastic differentiation [PMID:18436533]. Pair is human.","localisation_and_range":"BMP2 is flagged secreted and not transmembrane, and the receptor complex is flagged transmembrane (annotation flags), so signalling is paracrine/juxtacrine from a secreted ligand to a cell-surface receptor [flag].","caveats":"Single paper, read as abstract only. No direct binding of BMP2 to this exact heteromer in our evidence. BioGRID lists BMP2-ACVR2A reconstituted-complex records [DB:BioGRID]. Two further papers were judged review-only.","key_references":[{"PMID":"18436533","why":"siRNA screen in primary human MSCs naming ACVR2A and BMPR1A for BMP-2/4"}],"covers":["LR007110"]},"LR000126":{"pair":"BMP4 -> ACVR1","headline":"BMP4 acts in an ALK2 (ACVR1)-dependent manner in endothelial cells; evidence is one functional paper, with no direct binding shown.","interaction_type":"functional only","direction_and_effect":"BMP4 treatment of untransfected endothelial cells induced ALK2-dependent endothelial-to-mesenchymal transition and a stem-like phenotype; the paper calls BMP4 an ALK2-activating ligand [PMID:21102460]. ALK2 siRNA blocked the effect, and BMP4 induced ALK2 receptor phosphorylation within 15 min in immunoprecipitation assays [PMID:21102460]. Effect is agonist.","molecular_requirements":"ALK2 co-precipitated with ALK5 in BMP4-treated cells, suggesting an ALK2/ALK5 interaction; a type II partner is not reported in our evidence [PMID:21102460].","affinity_potency":[],"species_and_systems":"Human endothelial cells (HUVECs, HCMECs); heterotopic ossification experiments in mice were also reported [PMID:21102460].","localisation_and_range":"BMP4 is flagged secreted [flag]; acts on cell-surface receptor ALK2 in treated cells.","caveats":"No binding measurement in our evidence. Dependence on ALK2 is shown by knockdown and inhibitor, which does not rule out indirect action. Another review-only row exists but is not shown. Abstract plus excerpts only for one paper.","key_references":[{"PMID":"21102460","why":"BMP4 drives ALK2-dependent endothelial-to-mesenchymal transition"}],"covers":["LR000126","LR003675"]},"LR000135":{"pair":"BMP6 -> ACVR2B","headline":"BMP6 binds ActR-IIB (ACVR2B) per a 1999 study and a cryo-EM structure; some data are 'not shown'.","interaction_type":"direct binding","direction_and_effect":"Curators label the effect agonist. BMP-6 bound ActR-II and ActR-IIB in singly transfected cells [PMID:10504300]. A cryo-EM structure shows ALK2-ActRIIB bound to BMP6 [DB:PDB 9N4K][PMID:40854140]. UniProt says ACVR2B interacts with BMP6 [DB:UniProt][PMID:18070108].","molecular_requirements":"ACVR2B bound BMP6 without a type I receptor in the paper [PMID:10504300]; the structure contains ALK2 as well [DB:PDB 9N4K].","affinity_potency":[],"species_and_systems":"Recombinant human BMP-6 with COS-7 transfectants; endogenous binding in mouse MC3T3-E1 and C2C12 lines [PMID:10504300]. The structure is by electron microscopy [DB:PDB 9N4K]. Both species pairs are projected from this evidence.","localisation_and_range":"BMP6 is flagged secreted and ACVR2B transmembrane [flag].","caveats":"The quoted binding result is marked 'data not shown'. Affinity not reported. One further judged row was abstract_insufficient.","key_references":[{"PMID":"10504300","why":"cross-linking of BMP-6 to ActR-IIB"}],"covers":["LR000135","LR003684"]},"LR000144":{"pair":"BMP7 -> BMPR2","headline":"BMP7 binds BMPR2 directly, but with a very fast dissociation rate; ligand binding is enhanced by type I receptors.","interaction_type":"direct binding","direction_and_effect":"BMPR-II binds BMP-7 on its own, and binding is enhanced by coexpression of type I BMP receptors [PMID:7791754]. In SPR, BMP7 bound BMPR2 but dissociated at a very fast rate [PMID:35643319]. GtoPdb lists agonist action [DB:GtoPdb].","molecular_requirements":"BMP-2 and BMP-7 induced a transcriptional response only in cells coexpressing ActR-I and BMPR-II, not either receptor alone; kinase activity of both receptors was needed [PMID:7791754]. UniProt notes BMPR2 as type II receptor for some BMP7 functions [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human, SPR with immobilised BMPR2-Fc [PMID:35643319]; human BMPR-II in mammalian cells [PMID:7791754].","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"No affinity value for BMP7-BMPR2 is given in the dossier excerpts. PMID 7791754 was read as abstract only. In PMID 35643319, BMP7 was one of eight growth factors tested; high-affinity BMPR2 ligands were other factors (BMP15, BMP10, Nodal).","key_references":[{"PMID":"35643319","why":"SPR of BMPR2 with BMP7 and other ligands"},{"PMID":"7791754","why":"BMPR-II binds BMP-7; needs type I partner for signalling"}],"covers":["LR000144","LR003693"]},"LR002205":{"pair":"C1QB -> LAIR1","headline":"C1q (via its collagen-like region) binds and activates LAIR-1 on human monocytes; one paper, chain-level row.","interaction_type":"direct binding","direction_and_effect":"The abstract states that C1q CLR engaging and activating LAIR-1 is a non-complement route to immune quiescence, and that C1q crosslinks LAIR-1 and CD33 [PMID:28325905]. The CLR-LAIR-1 activation is stated in the abstract's first sentence; in this paper's excerpts, C1q bound LAIR-1 in a dose-dependent manner on HEK293T lysates, described as previously reported by the authors.","molecular_requirements":"Domain-resolved: the collagen-like region (CLR) of C1q engages LAIR-1, whereas the globular head binds CD33 [PMID:28325905]. This row encodes the C1QB chain of the hexameric C1q; chain-alone activity is not shown.","affinity_potency":[],"species_and_systems":"Human: HEK293T cells transfected with LAIR-1 (slot blot), human monocytes (proximity ligation assay) [PMID:28325905].","localisation_and_range":"C1q secreted (ligand flag), LAIR1 transmembrane (receptor flag) [flag]; C1q bridges LAIR-1 and CD33 on one monocyte [PMID:28325905].","caveats":"The LAIR-1 arm is largely background in this paper (the new claim is CD33); the visible abstract does not give the LAIR-1 measurement. Single paper; chain-level attribution inherited from the complex.","key_references":[{"PMID":"28325905","why":"C1q CLR engages LAIR-1 and bridges it with CD33 on human monocytes"}],"covers":["LR002205","LR005519"]},"LR002214":{"pair":"C1QL1 -> ADGRB3","headline":"C1QL1 binds the thrombospondin-repeat domain of ADGRB3 (BAI3) with high affinity; one abstract-level paper plus UniProt.","interaction_type":"direct binding","direction_and_effect":"Biochemical binding of C1ql proteins to BAI3; submicromolar C1ql proteins decrease synapse density in cultured neurons, prevented by the BAI3 thrombospondin-repeat fragment, which binds C1ql proteins and acts as a decoy [PMID:21262840].","molecular_requirements":"Binding is to the extracellular thrombospondin-repeat domain of BAI3 and is mediated by the globular C1q domain of the ligand [PMID:21262840]. Further subunits are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Paper tested all four C1ql proteins together; the abstract does not name the species or cell type (curator labels human/human; both listed interactions are ortholog-inferred, none experiment-derived here). UniProt records the interaction [DB:UniProt].","localisation_and_range":"C1QL1 is flagged secreted, ADGRB3 transmembrane [flag]; paracrine or trans-synaptic action is suggested by the paper [PMID:21262840].","caveats":"Abstract only; affinity described as 'high' without a number. Effect shown only for the C1ql protein set in cultured neurons, not C1QL1 alone. Curator label 'antagonist' is unclear.","key_references":[{"PMID":"21262840","why":"All four C1ql proteins bind the BAI3 thrombospondin-repeat domain with high affinity via the gC1q domain"}],"covers":["LR002214","LR005527"]},"LR002223":{"pair":"C4A -> F2R","headline":"C4a acts as an untethered agonist at PAR1 (F2R) with nanomolar activity; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"C4a acted as an agonist for PAR1 and PAR4 with nanomolar activity; calcium mobilization via PAR1/Galphaq/PLCbeta and increased endothelial permeability reduced by PAR1 antagonists [PMID:28973891].","molecular_requirements":"C4a showed no activity toward known anaphylatoxin receptors [PMID:28973891]. Single receptor chain.","affinity_potency":[],"species_and_systems":"Cell-based reporter screen and human endothelial cells [PMID:28973891].","localisation_and_range":"C4a is flagged secreted and F2R transmembrane [flag].","caveats":"Abstract only; no numeric potency given ('nanomolar'). The active ligand is C4a, the cleavage fragment of C4, not full C4A.","key_references":[{"PMID":"28973891","why":"C4a as PAR1/PAR4 agonist"}],"covers":["LR002223"]},"LR002232":{"pair":"CADM3 -> CADM2","headline":"Direct CADM3-CADM2 binding detected by SPRi in one paper; no pair-specific affinity.","interaction_type":"direct binding","direction_and_effect":"SPRi detected heterophilic interactions of CADM3 with all CADM family proteins, including CADM2 [PMID:30131958].","molecular_requirements":"Whole ectodomain Fc fusions [PMID:30131958].","affinity_potency":[],"species_and_systems":"Human-labelled recombinant ectodomains in SPRi [PMID:30131958]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged non-secreted [flag].","caveats":"One paper. The curated sentence describes CADM1-Fc binding CADM2, not CADM3. A CADM1-CADM2 Kd exists in the paper but is not for this pair.","key_references":[{"PMID":"30131958","why":"SPRi of CADM family"}],"covers":["LR002232","LR005542"]},"LR000171":{"pair":"CALCA -> CALCRL","headline":"Alpha-CGRP activates CALCRL as part of the CRLR/RAMP1 receptor; well supported functionally, but abstract-only evidence.","interaction_type":"direct binding","direction_and_effect":"Alpha-CGRP is an agonist: RAMP1 makes CRLR a CGRP receptor [PMID:9620797][PMID:10347248]. A cloned human CGRP1 receptor gave a 60-fold increase in cAMP on CGRP exposure, competitively inhibited by the antagonist CGRP-(8-37) [PMID:8626685]. Radioligand [125I]halphaCGRP binding was used in RAMP1/CRLR cells [PMID:11693189].","molecular_requirements":"RAMP1 is required: it presents CRLR at the cell surface as a mature glycoprotein and a CGRP receptor [PMID:9620797]. Progressive shortening of the RAMP1 transmembrane domain impaired CRLR association and abolished CGRP receptor function [PMID:12234182]. The cloning paper does not state RAMP1 explicitly [PMID:8626685]. Score as a complex.","affinity_potency":[{"value":"pKd 6.0","assay":"CGRP binding, RAMP1/CRLR (value from curated row)","system":"human","cite":"PMID:9620797"}],"species_and_systems":"Human ligand and receptor in HEK293 cells [PMID:8626685][PMID:11693189]; rat mesenteric artery binding with human ligand [PMID:14668209]. Mouse pair is ortholog-inferred. GtoPdb gives pKi 6.5-6.8 [DB:GtoPdb].","localisation_and_range":"CALCA flagged secreted [flag]; CALCRL is flagged receptor (transmembrane not flagged) [flag]. Range is paracrine/endocrine by annotation.","caveats":"All shown papers are abstract-only. The rat artery paper is about hormonal regulation of receptor expression, and mentions an uncharacterised CGRP-B receptor [PMID:14668209]. CRLR alone is not shown to bind CGRP in our evidence.","key_references":[{"PMID":"9620797","why":"RAMP1 makes CRLR a CGRP receptor"},{"PMID":"8626685","why":"Cloned human CGRP1 receptor, 60-fold cAMP increase"},{"PMID":"12234182","why":"RAMP1 transmembrane domain needed for CGRP receptor function"}],"covers":["LR000171","LR003716"]},"LR002241":{"pair":"CBLIF -> CUBN","headline":"Intrinsic factor-cobalamin binds cubilin with high affinity; SPR plus structural and Reactome records.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance of ligand-affinity-purified human cubilin showed high-affinity, calcium- and cobalamin-dependent binding of IF-cobalamin [PMID:9572993]. Reactome lists CUBN:AMN binding CBLIF:RCbl [DB:Reactome].","molecular_requirements":"Binding depends on calcium and on cobalamin being bound to intrinsic factor [PMID:9572993]. Reactome describes a CUBN:AMN complex as the binder, so a second chain (AMN) may be required [DB:Reactome]; the abstract does not test this.","affinity_potency":[],"species_and_systems":"Purified human cubilin by SPR; cDNA cloning of human cubilin, a 3597 amino acid peripheral membrane protein [PMID:9572993]. The mouse pair is ortholog-inferred.","localisation_and_range":"CBLIF is flagged secreted [flag]; cubilin is described as a peripheral membrane protein in intestinal and kidney epithelium [PMID:9572993].","caveats":"The abstract gives no numerical affinity. A second confirmed paper was not shown. Other records are a PDB structure [DB:PDB 3KQ4], an IntAct molecular sieving record and BioGRID reconstituted complex [DB:BioGRID]. Uptake of vitamin B12 is the context, so the ligand is the cobalamin-loaded form.","key_references":[{"PMID":"9572993","why":"SPR binding of IF-cobalamin to human cubilin; cubilin cloning"}],"covers":["LR002241","LR005551"]},"LR002250":{"pair":"CBLN4 -> NEO1","headline":"Genetic evidence in mouse that postsynaptic neogenin-1 matches presynaptic Cbln4 for LTP; direct binding data are not shown in our evidence.","interaction_type":"functional only","direction_and_effect":"Cbln4 bound to cell-surface neurexins forms transcellular complexes by interacting with postsynaptic DCC or neogenin-1; neogenin-1 deletion in dentate granule cells blocked EC-to-DG LTP without affecting basal transmission, mirroring presynaptic Cbln4 deletion [PMID:35544694]. Curators label it agonist.","molecular_requirements":"Cbln4 acts bound to neurexins [PMID:35544694]. Neogenin-1, not DCC, is abundant in dentate granule cells [PMID:35544694].","affinity_potency":[],"species_and_systems":"Mouse dentate gyrus, entorhinal cortex to dentate gyrus synapses, with conditional deletions [PMID:35544694]. Curated species fields say human, but the work is mouse; the human pair is projected.","localisation_and_range":"Transsynaptic, presynaptic Cbln4 to postsynaptic neogenin-1 [PMID:35544694]. CBLN4 is flagged secreted [flag].","caveats":"Read as abstract only; binding affinity and specificity are not reported in our evidence [PMID:35544694].","key_references":[{"PMID":"35544694","why":"Postsynaptic neogenin-1 deletion blocks EC-DG LTP like presynaptic Cbln4 deletion"}],"covers":["LR002250","LR005560"]},"LR000180":{"pair":"CCK -> CCKAR","headline":"Well supported agonist-receptor pair: human CCK1 receptor binding sites mapped by mutagenesis and NMR, plus GtoPdb, PDB structures and Reactome.","interaction_type":"direct binding","direction_and_effect":"CCK acts as an agonist: receptor mutants lose affinity and potency to induce inositol phosphates [PMID:9006937], and GtoPdb lists an agonist interaction [DB:GtoPdb]. Sulfated tyrosine of CCK is crucial for binding [PMID:9603948].","molecular_requirements":"Residues involved include Trp-39/Gln-40 [PMID:9006937], Met-195 [PMID:9603948], Arg197 [PMID:10595537], Arg-336/Asn-333 [PMID:10400673]. Complex structures with both chains are in PDB (e.g. [DB:PDB 7EZH]). Reactome lists a CCKAR,CCKBR:CCK complex [DB:Reactome].","affinity_potency":[{"value":"12.9- and 20.9-fold decrease in affinity and potency (W39F, Q40N mutants)","assay":"mutagenesis, binding and inositol phosphate accumulation","system":"human CCK-A receptor","cite":"PMID:9006937"}],"species_and_systems":"Human receptor mutants; peptides used are CCK-8/CCK-9 analogues rather than full CCK-33; COS-7 cells in [PMID:10595537]. NMR used a receptor fragment (residues 329-357) in micelles [PMID:11300760]. Mouse pair is projected.","localisation_and_range":"CCK is flagged secreted and CCKAR transmembrane [flag].","caveats":"All five papers shown were read as abstracts; most evidence is mutational mapping, not primary affinity measurement. Nonsulfated CCK shows 800-fold lower affinity than sulfated CCK [PMID:10595537].","key_references":[{"PMID":"10595537","why":"Arg197 mutant loses agonist radioligand binding"},{"PMID":"9006937","why":"Trp-39/Gln-40 role in CCK binding and potency"},{"PMID":"10400673","why":"Arg-336 and Asn-333 interact with CCK C-terminus"}],"covers":["LR000180","LR003725"]},"LR000207":{"pair":"CCL17 -> ACKR1","headline":"CCL17 binds human ACKR1 (Duffy) with Ki 58.0 nM and competes moderately for CXCL1 binding; binding only.","interaction_type":"direct binding","direction_and_effect":"Binding only; no signalling reported in our evidence. CCL17 showed strong binding (Ki < 100 nM class) to Duffy on red blood cells [PMID:15358176] and moderately inhibited 125I-CXCL1 binding to DARC [PMID:13679391].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 58.0 nM","assay":"radioligand displacement","system":"human red blood cells","cite":"PMID:15358176"}],"species_and_systems":"Human chemokine and human Duffy antigen (erythrocytes; DARC F-2 cells) [PMID:15358176][PMID:13679391]. The mouse pair is projected from human evidence.","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Quote for PMID 13679391 is a browser-read sentence not yet spot-checked. Evidence from only two papers.","key_references":[{"PMID":"15358176","why":"Ki for CCL17 at Duffy antigen"},{"PMID":"13679391","why":"Competition for CXCL1 binding to DARC"}],"covers":["LR000207","LR003735"]},"LR000234":{"pair":"CCL2 -> CCR1","headline":"Weak evidence: one 1993 abstract-read paper shows MCP-1 binding CCR1 with varying affinity but poor signalling.","interaction_type":"direct binding","direction_and_effect":"MCP-1 bound C-C CKR-1; binding affinity did not predict signal strength, and MCP-1 induced calcium mobilization only at high concentrations [PMID:7679328].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; the abstract does not specify the expression system [PMID:7679328]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"No affinity value reported for MCP-1 in our evidence. Abstract only. One paper was abstract_insufficient, one pending, one review-only. No database records.","key_references":[{"PMID":"7679328","why":"CCR1 cloning; MCP-1 binds with varying affinity, weak calcium response"}],"covers":["LR000234","LR003755"]},"LR000216":{"pair":"CCL21 -> CCR7","headline":"Well supported direct CCL21-CCR7 binding and agonism, with sub-nanomolar competition and an NMR-mapped binding interface.","interaction_type":"direct binding","direction_and_effect":"CCL21 (SLC/6Ckine) is an agonist at CCR7: it induced calcium mobilisation and chemotaxis in CCR7-expressing L1.2 cells [PMID:9507024], and chemotaxis of CCR7 transfectants that was lost in non-transfected cells [PMID:9585422]. It also drove migration, proliferation and survival of cultured human mesangial cells [PMID:11970971]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"CCR7 alone was sufficient in transfected cells. NMR chemical-shift mapping places the CCR7 N-terminus on the N-loop and third beta-strand of CCL21's chemokine domain; CCL21 is monomeric with an extended unstructured C-terminus [PMID:22221265].","affinity_potency":[{"value":"IC50 0.5 nM","assay":"SLC-SEAP binding competed by SLC","system":"murine L1.2 cells expressing human CCR7","cite":"PMID:9507024"},{"value":"maximal migration at 10 nM","assay":"chemotaxis","system":"CCR7-expressing L1.2 cells","cite":"PMID:9507024"}],"species_and_systems":"Binding and chemotaxis used human CCR7 in mouse L1.2 cells [PMID:9507024]. PMID:9585422 used mouse CCR7 transfectants with mouse 6CK/SLC and also transient human or mouse CCR7 in the full-text excerpts; human lymphocytes were also tested [PMID:9585422]. Structural work used human proteins [PMID:22221265]. Kidney work used human mesangial cells [PMID:11970971].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor.","caveats":"Most papers were abstract-only reads. PMID:11970971 reports CCL21-dependent responses without receptor-blockade or binding controls, so it is supportive only. CCL21 was less efficient than CCL19 (ELC) in cross-desensitisation on cultured T cells [PMID:9507024].","key_references":[{"PMID":"9507024","why":"IC50 0.5 nM binding and calcium/chemotaxis in CCR7 cells"},{"PMID":"9585422","why":"CCL21 shown as CCR7 agonist, mouse and human CCR7"},{"PMID":"22221265","why":"NMR mapping of binding site"}],"covers":["LR000216"]},"LR000225":{"pair":"CCL26 -> CCR1","headline":"CCL26 binds CCR1 but acts as an antagonist, per one human study.","interaction_type":"direct binding","direction_and_effect":"Antagonist: eotaxin-3 bound CCR1-transfected cells and monocytes, and inhibited chemotaxis, calcium release and actin polymerisation triggered by known CCR1 and CCR5 agonists [PMID:15039444].","molecular_requirements":"Individual CCR1 transfectants showed binding; the receptors involved were CCR1 and CCR5 together in monocytes [PMID:15039444].","affinity_potency":[],"species_and_systems":"Species is recorded as human for ligand and receptor; transfected cells and monocytes [PMID:15039444].","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag].","caveats":"One paper, abstract only; no affinity value reported in our evidence. Not an activating pair.","key_references":[{"PMID":"15039444","why":"Eotaxin-3 binds and antagonises CCR1/CCR5"}],"covers":["LR000225"]},"LR000243":{"pair":"CCL3L1 -> CCR5","headline":"LD78beta (mapped to CCL3L1) binds CCR5, with CD26-processed LD78beta(3-70) tenfold more effective; one abstract-read paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"LD78beta(3-70) competed tenfold more efficiently than LD78beta(1-70) with [125I]RANTES for binding to CCR5 and CCR1, and was the most potent chemokine blocking HIV-1 [PMID:11449371]. Curators label it an agonist.","molecular_requirements":"Cleavage of the N-terminal Ala-Pro dipeptide by CD26 gives the more active form at CCR5 [PMID:11449371].","affinity_potency":[],"species_and_systems":"Human ligand and receptor [PMID:11449371]. BioGRID lists reconstituted complexes, from this paper and from PMID 11734558 (not in our papers) [DB:BioGRID].","localisation_and_range":"CCL3L1 is flagged as secreted and CCR5 as transmembrane [flag].","caveats":"One paper, abstract only, no absolute affinity values. Gene mapping of LD78beta to CCL3L1 comes from curators.","key_references":[{"PMID":"11449371","why":"Processed LD78beta binds CCR5 tenfold better"}],"covers":["LR000243"]},"LR000252":{"pair":"CCL4 -> CCR3","headline":"Functional evidence only: CCL4 (MIP-1 beta) was an agonist for CCR3 in calcium assays in one 1995 abstract-level paper.","interaction_type":"functional only","direction_and_effect":"MIP-1 beta was an agonist for CC CKR3 (CCR3) in [Ca2+]i assays, but not for CC CKR1 [PMID:7622448].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Stably transfected human embryonic kidney 293 cells; human receptor [PMID:7622448].","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"Single paper, read as abstract only; no binding or affinity data, and no database record supports the pair.","key_references":[{"PMID":"7622448","why":"CCR3 cloning; MIP-1 beta agonist activity in HEK293 cells"}],"covers":["LR000252"]},"LR000261":{"pair":"CCL5 -> GPR75","headline":"Two papers support CCL5 activating GPR75 (Gq signalling), one at subnanomolar potency in transfected cells; no direct binding measurement in the dossier.","interaction_type":"functional only","direction_and_effect":"RANTES at subnanomolar concentrations stimulated luciferase reporter activity, IP3 and Ca2+ in GPR75-transfected cells, blocked by the PLC inhibitor U73122, indicating Gq signalling [PMID:17001303]. In SH-SY5Y cells, CCL5 induced AKT/GSK3b/ERK phosphorylation despite CCR1/CCR3/CCR5 antagonists, was pertussis-toxin-insensitive, caused GPR75 internalisation, and CRISPR knockdown (about 70% GPR75 reduction) reduced CCL5-induced pERK [PMID:29772059]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"GPR75 acts alone in these assays; pathway is Gq (PLC/PI3K) [PMID:17001303][PMID:29772059].","affinity_potency":[{"value":"pEC50 9.59","assay":"reporter/IP3/Ca2+ response to RANTES","system":"GPR75-transfected cells (human ligand and receptor)","cite":"PMID:17001303"}],"species_and_systems":"Human ligand and receptor: transfected cells, HT22 line expressing GPR75 endogenously [PMID:17001303]; human SH-SY5Y neuroblastoma cells and rat primary cortical neurons [PMID:29772059]. Mouse pair is ortholog-inferred.","localisation_and_range":"CCL5 flagged secreted; GPR75 flagged transmembrane receptor [flag].","caveats":"First paper read as abstract only. 'Binds' is asserted by the authors but only signalling and internalisation data are shown. UniProt notes GPR75 activation may affect insulin secretion [DB:UniProt]. The 2018 paper notes CCL4 and CCL7 gave no effect in the earlier study, citing prior work [PMID:29772059].","key_references":[{"PMID":"17001303","why":"Deorphanisation: RANTES activates GPR75, pEC50 9.59"},{"PMID":"29772059","why":"Independent SH-SY5Y signalling, internalisation and CRISPR knockdown"}],"covers":["LR000261","LR003771"]},"LR000270":{"pair":"CCL7 -> CCR5","headline":"MCP-3 (CCL7) binds human CCR5 with IC50 2.14 nM but without a functional response and blocks MIP-1beta activation, so it is a natural antagonist.","interaction_type":"direct binding","direction_and_effect":"MCP-3 competed for [125I]-MIP-1beta binding to CCR5 (IC50 2.14 nmol/L) yet elicited no functional response, inhibited CCR5 activation by MIP-1beta, and did not induce significant receptor endocytosis, so it may be a natural antagonist [PMID:10477718]. GtoPdb: antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 2.14 nmol/L","assay":"competition vs [125I]-MIP-1beta","system":"stable CCR5-expressing cell line (human)","cite":"PMID:10477718"}],"species_and_systems":"Human ligand and receptor in a recombinant cell line [PMID:10477718]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; CCR5 flagged transmembrane receptor [flag].","caveats":"Single paper, abstract only; antagonism is not agonism, relevant for scoring signalling. The abstract's IC50 list is ordered by ligand and the 2.14 value was assigned to MCP-3 by the curators.","key_references":[{"PMID":"10477718","why":"MCP-3 binds CCR5 without activation and antagonises it"}],"covers":["LR000270","LR003780"]},"LR000423":{"pair":"CCN1 -> ITGB3","headline":"CCN1 binds integrin alphavbeta3 and enhances mitogenesis through it; adhesion and binding shown in endothelial cells.","interaction_type":"direct binding","direction_and_effect":"HUVEC adhesion to Cyr61 was inhibited by RGDS and LM609, and purified alphavbeta3 bound Cyr61 directly [PMID:9446626]. In skin fibroblasts, Cyr61 enhancement of growth-factor-induced mitogenesis was through alphavbeta3, whereas migration was through alphavbeta5 and not alphavbeta3 [PMID:11287419].","molecular_requirements":"beta3 functions as part of alphavbeta3, an RGD-sensitive integrin; the effect depends on context (mitogenesis, not migration) [PMID:11287419].","affinity_potency":[{"value":"approximately 5 nM half-saturation","assay":"solid-phase binding of soluble Cyr61 to immobilized alphavbeta3","system":"purified integrin","cite":"PMID:9446626"}],"species_and_systems":"Human CCN1, human umbilical vein endothelial cells and human skin fibroblasts. Mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Both papers abstract only. The fibroblast paper is functional and states migration is not alphavbeta3-mediated [PMID:11287419]. The half-saturation value is not a formal Kd.","key_references":[{"PMID":"9446626","why":"Direct alphavbeta3 binding and adhesion in HUVEC"},{"PMID":"11287419","why":"alphavbeta3 role in mitogenesis, alphavbeta5 in migration"}],"covers":["LR000423","LR003920"]},"LR001701":{"pair":"CCN4 -> ITGB1","headline":"Functional evidence only: CCN4-driven fibroblast migration depends on alpha5beta1 integrin; direct ITGB1 binding not shown.","interaction_type":"functional only","direction_and_effect":"CCN4-induced migration of dermal fibroblasts appears to work via alpha5beta1 integrin receptors, further stimulating ERK/JNK signalling; the dossier labels CCN4 an agonist [PMID:29330021].","molecular_requirements":"The paper implicates the alpha5beta1 integrin heterodimer; whether one chain alone suffices is not reported in our evidence. Both ITGA5 and ITGB1 pairs rest on the same single paper [PMID:29330021].","affinity_potency":[],"species_and_systems":"Human adult dermal fibroblasts (siRNA knockdown or adenoviral CCN4) and Ccn4-knockout mouse dermal fibroblasts and wounds [PMID:29330021].","localisation_and_range":"CCN4 is flagged secreted and the integrin as a receptor [flag]; matrix-associated paracrine action is plausible but not stated in our evidence.","caveats":"No binding assay is reported; the link to the integrin is inferred from migration experiments, and the paper was read mainly as abstract plus excerpts. No database record supports this pair. The integrin subunit is a chain of a heterodimer.","key_references":[{"PMID":"29330021","why":"CCN4 wound healing via alpha5beta1 in dermal fibroblasts"}],"covers":["LR001701","LR005070"]},"LR001710":{"pair":"CD22 -> PTPRC","headline":"CD22 binds sialylated glycans on CD45; low affinity and glycan-mediated, so not a clean protein-specific pair.","interaction_type":"direct binding","direction_and_effect":"Soluble CD22-Ig engagement of CD45 modulated early T-cell signals in antigen receptor/CD3-mediated stimulation; added alpha2-6 sialic acid on CD22 abrogated CD22-ligand interactions [PMID:7537381].","molecular_requirements":"CD22 binds alpha2-6-linked sialic acid on N-glycans; CD45 is one such carrier [PMID:7537381][PMID:12115612]. Affinity for CD45, sialylated CD4 and a synthetic alpha2-6-sialoglycoconjugate did not differ substantially, so CD45 preference is suggested to reflect multiple glycan copies [PMID:12115612].","affinity_potency":[{"value":"Kd 130 microM","assay":"surface plasmon resonance, native CD45, 25 degrees C","system":"human proteins","cite":"PMID:12115612"},{"value":"koff >=18 s-1","assay":"surface plasmon resonance","system":"human proteins","cite":"PMID:12115612"}],"species_and_systems":"Human proteins; soluble CD22-Ig and T cells expressing wild-type and chimeric CD45 [PMID:7537381]; human and mouse pairs listed.","localisation_and_range":"Both partners flagged transmembrane [flag]; transient cell-surface contact.","caveats":"Very low affinity with fast kinetics [PMID:12115612]; binding is glycan-dependent rather than protein-specific. Both papers abstract only. BioGRID and IntAct also list the pair [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"12115612","why":"SPR affinity of CD22 for native CD45"},{"PMID":"7537381","why":"CD22-CD45 engagement modulates T-cell signalling"}],"covers":["LR001710","LR005077"]},"LR002313":{"pair":"CDH3 -> CDH3","headline":"P-cadherin homophilic adhesion in human, studied via blocking antibodies; evidence is structural and functional.","interaction_type":"direct binding","direction_and_effect":"P-cadherin forms homophilic adhesion; antibody TSP7 abolished adhesion by disabling the X-dimer intermediate as well as the strand-swap dimer [PMID:28045038]. Curators label the antibody effect as antagonist.","molecular_requirements":"The EC1 domain carries the epitopes for TSP5, TSP7 and TSP11, and all three bind with high affinity, but only TSP7 blocks adhesion [PMID:28045038].","affinity_potency":[],"species_and_systems":"Human P-cadherin, abstract only; the mouse pair is ortholog-inferred [PMID:28045038]. BioGRID also lists CDH3-CDH3 co-purification and Affinity Capture-Western [DB:BioGRID] [PMID:10910767].","localisation_and_range":"Membrane-bound homophilic adhesion, contact-dependent [flag].","caveats":"The confirming paper concerns antibody blockade, so homophilic binding is inferred rather than directly quantified; no affinity for the cadherin pair reported.","key_references":[{"PMID":"28045038","why":"X-dimer and strand-swap dimer in P-cadherin adhesion"}],"covers":["LR002313","LR005611"]},"LR002322":{"pair":"CDH9 -> CDH6","headline":"Type II cadherin heterophilic pair: cadherin-9 and cadherin-6 interact in SPR on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"On surfaces of cadherin-6, -9 or -10, cadherin-6 analyte was strongest, followed by cadherin-9 and cadherin-10 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 form one specificity group [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"SPR matrix of type II cadherin binding"}],"covers":["LR002322","LR005620"]},"LR002331":{"pair":"CEACAM6 -> CEACAM6","headline":"Homophilic CEACAM6 adhesion via N-domain, one abstract-level paper plus IntAct records.","interaction_type":"functional only","direction_and_effect":"The N-domain of CEACAM6 on a CHO cell was suggested to bind the N-domain of CEACAM6 on an opposing cell [PMID:11590190]. IntAct records protein array, cosedimentation and solid phase assays [DB:IntAct].","molecular_requirements":"Overlapping critical sequences in the N-terminal domain [PMID:11590190].","affinity_potency":[],"species_and_systems":"Human CEACAM6 in CHO transfectants with mutants and chimeras [PMID:11590190].","localisation_and_range":"Trans cell-cell adhesion between opposing cells [PMID:11590190].","caveats":"Abstract only; wording is 'suggested'. Homophilic pair so direction is not meaningful.","key_references":[{"PMID":"11590190","why":"Homophilic CEACAM6 N-domain adhesion"}],"covers":["LR002331"]},"LR005103":{"pair":"CFP -> NCR1","headline":"Properdin (CFP) binds the NK receptor NKp46 and NKp46 was needed for CFP benefit in mouse Neisseria infection.","interaction_type":"direct binding","direction_and_effect":"Serum-purified human CFP bound human NKp46-Fc but not control NKp30-Fc; classed as agonist [PMID:28480349]. CFP treatment benefit in mouse Neisseria meningitidis infection depended on NKp46 and group-1 NKp46+ ILCs [PMID:28480349].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant and serum proteins for binding; mouse in vivo infection model [PMID:28480349]. The mouse pair is listed separately.","localisation_and_range":"CFP is a soluble plasma glycoprotein (secreted flag [flag]) acting on NK and ILC membrane NKp46 [PMID:28480349].","caveats":"Full text read; no affinity in excerpts. IntAct lists a fluorescence-activated cell sorting record [DB:IntAct]. One further confirmed row not shown.","key_references":[{"PMID":"28480349","why":"CFP identified as an NKp46 ligand with in vivo validation"}],"covers":["LR001743","LR005103"]},"LR002340":{"pair":"CGB2 -> LHCGR","headline":"CGB2 as half of hCG on LHCGR: one paper on LH/hCG, not specific to this beta gene.","interaction_type":"direct binding","direction_and_effect":"LH and hCG bound wild-type and exon-10-deleted LHR with similar affinity; exon 10 deletion impaired LH but not hCG action [PMID:12727981]. Effect labelled agonist.","molecular_requirements":"LH and hCG are heterodimers of CGA with LHB or CGB, so a single beta-subunit entity is half of the hormone [PMID:12727981].","affinity_potency":[],"species_and_systems":"Human LHR in stable COS-7 cells [PMID:12727981].","localisation_and_range":"Secreted ligand [flag].","caveats":"Abstract only; paper does not name CGB2 specifically; no affinity value; no database records.","key_references":[{"PMID":"12727981","why":"LH and hCG bind LHR with similar affinity; exon 10 affects activation"}],"covers":["LR002340"]},"LR000306":{"pair":"CNTF -> IL6R","headline":"Human CNTF can use IL-6R as a substitute alpha-receptor in signalling assays; one abstract-only paper, no binding data.","interaction_type":"functional only","direction_and_effect":"Human CNTF can use both the membrane-bound and the soluble human IL-6R as a substitute for its cognate alpha-receptor [PMID:12643274]. Agonist-like (induces signalling).","molecular_requirements":"Needs gp130/LIFR as signalling beta-chains in the CNTF complex [PMID:12643274]; human CNTF cannot directly induce a gp130/LIFR heterodimer without an alpha-receptor.","affinity_potency":[],"species_and_systems":"Human CNTF with human IL-6R, in cells; rat CNTF was unable to interact with human IL-6R [PMID:12643274].","localisation_and_range":"CNTF is flagged secreted [flag]; the IL-6R can be soluble or membrane-bound [PMID:12643274].","caveats":"Abstract only; signalling readout, no direct binding or affinity. The IntAct, PDB and Reactome records shown concern CNTF-CNTFR, not IL6R. One other row was different_entity.","key_references":[{"PMID":"12643274","why":"Human CNTF uses IL-6R as an alpha-receptor substitute"}],"covers":["LR000306"]},"LR005112":{"pair":"CNTN1 -> PTPRZ1","headline":"Well-supported direct binding with a cocrystal structure; PTPRZ binds CNTN1 specifically and the complex affects oligodendrocyte maturation.","interaction_type":"direct binding","direction_and_effect":"PTPRZ carbonic-anhydrase-like domain binds CNTN1 Ig repeats, and PTPRZ-CNTN1 binding inhibits OPC proliferation and promotes maturation into oligodendrocytes (effect recorded as antagonist) [PMID:21969550].","molecular_requirements":"The carbonic anhydrase-like domain of PTPRZ binds the second and third Ig repeats of CNTN1 [PMID:20133774][PMID:21969550]. PTPRZ binds only CNTN1 among contactins [PMID:20133774]. Tenascin-C and PTPzeta/RPTPbeta both bind F3, possibly exclusively [PMID:10103110].","affinity_potency":[],"species_and_systems":"Human proteins in crystal structures [PMID:20133774][PMID:21969550]; mouse brain affinity isolation [PMID:10103110]; PTPRZ-deficient mice for OPC analysis [PMID:21969550]. PDB 3S97 and IntAct X-ray record the complex [DB:PDB 3S97][DB:IntAct].","localisation_and_range":"CNTN1 is surface-expressed on OPCs (contact-mediated) [PMID:21969550]; PTPRZ1 carries secreted and transmembrane flags [flag].","caveats":"All papers are abstract-only. Affinity is described as highest for F3-PTPzeta/RPTPbeta in one paper but no number is reported [PMID:10103110].","key_references":[{"PMID":"21969550","why":"Cocrystal structure and OPC function"},{"PMID":"20133774","why":"Structures and CNTN specificity"},{"PMID":"10103110","why":"F3 binds PTPzeta/RPTPbeta directly"}],"covers":["LR001754","LR005112"]},"LR000315":{"pair":"COL11A1 -> ITGB1","headline":"Only a cell-based report that integrin a2b1/DDR2 bind collagen XI; abstract-level and not chain-specific for COL11A1.","interaction_type":"functional only","direction_and_effect":"Integrin a2b1 and DDR2, but not a11b1, mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024].","molecular_requirements":"ITGB1 is named only as part of a2b1; a different alpha partner is not tested [PMID:36233024].","affinity_potency":[],"species_and_systems":"CAFs; species not reported in our evidence [PMID:36233024]. The human pair is ortholog-inferred.","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; the paper says collagen type XI without naming a chain, and does not isolate individual integrin subunits [PMID:36233024].","key_references":[{"PMID":"36233024","why":"Integrin a2b1 and DDR2 binding to collagen XI in CAFs"}],"covers":["LR000315","LR003821"]},"LR000324":{"pair":"COL1A1 -> DDR2","headline":"DDR2 is a collagen-activated receptor tyrosine kinase; type I collagen binds and activates it in three papers.","interaction_type":"direct binding","direction_and_effect":"Both DDRs bound collagen I with high affinity in solid-phase assays, and the isolated DDR2 discoidin domain bound collagen I with high affinity [PMID:12611880]. Collagen I and III activated DDR2 phosphorylation in 293 cells [PMID:9659899]. Collagen type I binding to DDR2 was detectable at 1 mg loading by slot blot [PMID:9659900].","molecular_requirements":"The isolated discoidin domain of DDR2 is sufficient for binding and transmembrane signalling, using three adjacent surface loops [PMID:12611880]. Activation needs native triple-helical collagen [PMID:9659899]. Type I collagen is a COL1A1/COL1A2 heterotrimer, not chain-specific.","affinity_potency":[],"species_and_systems":"Recombinant human DDR extracellular domains [PMID:12611880]; bovine and human or mouse collagen with human DDR2 in 293 cells [PMID:9659900] [PMID:9659899].","localisation_and_range":"Receptor is a membrane tyrosine kinase; collagen is matrix, so contact signalling.","caveats":"The affinity is called high but no value is given in the dossier. One paper was read as an abstract only [PMID:12611880]. BioGRID also lists a reconstituted complex [DB:BioGRID, PMID:16884738].","key_references":[{"PMID":"12611880","why":"Solid-phase binding and discoidin domain mapping"},{"PMID":"9659900","why":"Slot-blot binding of DDR2 to collagen I"},{"PMID":"9659899","why":"Collagen activates DDR2 phosphorylation"}],"covers":["LR000324","LR003830"]},"LR011061":{"pair":"COL1A1 -> ITGA9:ITGB1","headline":"Weak: one abstract-only paper that names ITGB1, not ITGA9.","interaction_type":"functional only","direction_and_effect":"COL1A1 activated AKT phosphorylation by binding integrin beta1 (ITGB1) in ovarian cancer cells [PMID:32589888].","molecular_requirements":"Paper names ITGB1 only; ITGA9 is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Ovarian cancer cells; species not reported in our evidence [PMID:32589888].","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Abstract-only, functional_in_vitro. BioGRID record is COL1A1-ITGB1 co-purification from PMID 2156854, not ITGA9 [DB:BioGRID]. Two other papers abstract_insufficient.","key_references":[{"PMID":"32589888","why":"COL1A1 binds ITGB1 and activates AKT"}],"covers":["LR011061"]},"LR000333":{"pair":"COL1A2 -> ITGA2","headline":"Type I collagen engages integrin alpha2 (alpha2beta1) by SPR and in functional assays; evidence is for the whole collagen.","interaction_type":"direct binding","direction_and_effect":"Both alpha1(I) and alpha2(I) chains supported Mg2+-dependent platelet adhesion via alpha2beta1 [PMID:2156854]; ITGA2-collagen interaction drives ovarian cancer peritoneal metastasis [PMID:33026975].","molecular_requirements":"Recombinant alpha2 I-domain bound collagen I [PMID:16043429]. Functional binding entity is alpha2beta1; ITGA2 stored alone.","affinity_potency":[{"value":"Kd 0.3 uM (range 0.15-1.75 uM)","assay":"SPR (BIAcore), two affinity classes","system":"recombinant human alpha2 I-domain, fibrillar collagen I","cite":"PMID:16043429"}],"species_and_systems":"Human I-domains [PMID:16043429]; human platelets [PMID:2156854]; human ovarian cancer cells [PMID:33026975]. IntAct biochemical record P08123-P17301 [DB:IntAct].","localisation_and_range":"COL1A2 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Collagen I tested as the (COL1A1)2COL1A2 heterotrimer, not COL1A2 alone. PMID:2156854 and PMID:33026975 were read as abstracts; the latter refers to 'collagens' as a class.","key_references":[{"PMID":"16043429","why":"SPR binding of alpha2 I-domain to collagen I"},{"PMID":"2156854","why":"Platelet adhesion via alpha2beta1"},{"PMID":"33026975","why":"ITGA2-collagen in ovarian cancer metastasis"}],"covers":["LR000333","LR003839"]},"LR000342":{"pair":"COL3A1 -> ITGA2","headline":"Alpha2 I domain binds collagen III in SPR; patient-fibroblast and ovarian-cancer studies support alpha2beta1 as a collagen III receptor.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha2 I domain bound collagens I-III [PMID:16043429]. EDS fibroblasts with COL3A1 mutations show strongly reduced alpha2beta1, the functional receptor, and purified COLLIII restored the control phenotype [PMID:14970208]. ITGA2 mediated cancer-cell adhesion to collagens and peritoneal metastasis [PMID:33026975].","molecular_requirements":"Cell studies concern alpha2beta1; ITGA2 is stored alone though the binding entity is ITGA2:ITGB1 [PMID:33026975].","affinity_potency":[],"species_and_systems":"Human recombinant I domains, human patient fibroblasts and ovarian cancer cells and mouse in vivo model not stated [PMID:16043429; PMID:14970208; PMID:33026975].","localisation_and_range":"Matrix ligand, cell-surface receptor [flag].","caveats":"Six confirmed papers, three shown. Fibroblast evidence is disease genetics, and the ovarian paper refers to 'collagens' as a class. Alpha2 affinities are not given as numbers in our excerpt.","key_references":[{"PMID":"16043429","why":"SPR of alpha2 I domain and collagen III"},{"PMID":"14970208","why":"COL3A1-mutant fibroblasts lose alpha2beta1"},{"PMID":"33026975","why":"ITGA2-collagen adhesion in ovarian cancer"}],"covers":["LR000342","LR003848"]},"LR000360":{"pair":"COL5A2 -> DDR1","headline":"Collagen V/XI hybrid containing alpha2(V) binds DDR1; commercial type V also activates DDR1.","interaction_type":"direct binding","direction_and_effect":"Commercial human type V collagen induced DDR1 phosphorylation comparable to the A204-derived ligand [PMID:9659900].","molecular_requirements":"Commercial type V is mostly COL5A1/COL5A2 and single chains were not resolved; the native A204 ligand was a hybrid of COL11A1 and COL5A2 [PMID:9659900].","affinity_potency":[],"species_and_systems":"Human-labelled ligand and receptor; mouse pair is projected [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Chain-level binding not shown; no affinity reported.","key_references":[{"PMID":"9659900","why":"Type V and V/XI collagens activate DDR1"}],"covers":["LR000360","LR003866"]},"LR002421":{"pair":"COL5A2 -> DDR2","headline":"A hybrid V/XI collagen containing alpha2(V) binds DDR2; chain-level resolution absent.","interaction_type":"direct binding","direction_and_effect":"Purified A204 V/XI hybrid collagen showed marked binding to both DDR1 and DDR2 receptor bodies [PMID:9659900].","molecular_requirements":"The alpha1 and alpha2 chains were in an apparent 2:1 ratio; COL5A2 is one chain of the hybrid [PMID:9659900].","affinity_potency":[],"species_and_systems":"Solid-phase binding to DDR receptor bodies; species labelled human [PMID:9659900].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Binding is for the hybrid heterotrimer, not COL5A2 alone; some commercial collagens lost DDR activity [PMID:9659900]. No affinity reported.","key_references":[{"PMID":"9659900","why":"Hybrid V/XI collagen binds DDR1 and DDR2"}],"covers":["LR002421"]},"LR011070":{"pair":"COL6A1 -> ITGA9:ITGB1","headline":"Single abstract-level claim that COL6A1 binds ITGB1 on endothelial cells in glioblastoma; thinly supported.","interaction_type":"direct binding","direction_and_effect":"COL6A1 is reported to bind ITGB1 on endothelial cells, leading to disruption of tight junctions via UBD-mediated degradation of claudin-5 [PMID:41297453].","molecular_requirements":"Only ITGB1 is named in the evidence; ITGA9 is not mentioned, so the alpha-chain requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human glioblastoma context (patient-derived GBM organoid model, endothelial cells); paper read as abstract only [PMID:41297453].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; collagen deposited in matrix is not addressed in our evidence beyond that.","caveats":"One paper, abstract only; two further papers were judged abstract-insufficient. No databases support this pair. Assay labelled direct binding, but the sentence is a statement in an abstract.","key_references":[{"PMID":"41297453","why":"Reports COL6A1 bound to ITGB1 on endothelial cells in GBM"}],"covers":["LR011070"]},"LR002430":{"pair":"COLQ -> LRP4","headline":"ColQ binds LRP4 directly by multiple binding assays, including SPR, and competes with agrin; well supported.","interaction_type":"direct binding","direction_and_effect":"ColQ binds directly to LRP4 but not MuSK, and interacts indirectly with MuSK through LRP4 (coimmunoprecipitation, pull-down, plate-binding, SPR) [PMID:37356721]. ColQ constitutively reduces MuSK phosphorylation in agrin-stimulated myotubes while increasing MuSK surface accumulation [PMID:37356721].","molecular_requirements":"The LRP4 N-terminal region, which contains the agrin-binding sites, is crucial for ColQ binding; ColQ-LRP4 interaction was reduced in the presence of agrin, suggesting competition [PMID:37356721]. LRP6 coprecipitated only very little with ColQ, so binding is specific to LRP4 among those tested [PMID:37356721].","affinity_potency":[],"species_and_systems":"HEK 293T cells and myotubes; excerpts also note COS cells gave identical results [PMID:37356721]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; ColQ is a nonfibrillar collagen anchoring acetylcholinesterase at the neuromuscular junction [PMID:37356721].","caveats":"No affinity value is reported in our evidence. Two opposing effects on agrin-induced signaling mean the net direction depends on context.","key_references":[{"PMID":"37356721","why":"Direct ColQ-LRP4 binding, agrin competition, MuSK modulation"}],"covers":["LR002430","LR005709"]},"LR005121":{"pair":"CTHRC1 -> ROR2","headline":"CTHRC1 binds Ror2 and enhances Wnt-Fzd/Ror2 interaction; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Cell-surface-anchored Cthrc1 bound to Wnt proteins, Fzd proteins, and Ror2 and enhanced Wnt-Fzd/Ror2 interaction by forming a Cthrc1-Wnt-Fzd/Ror2 complex; in HEK293T cells Cthrc1 activated the PCP pathway but suppressed the canonical pathway [PMID:18606138].","molecular_requirements":"Ror2 acts as a co-receptor in a Cthrc1-Wnt-Fzd/Ror2 complex [PMID:18606138].","affinity_potency":[],"species_and_systems":"HEK293T cells, with mouse knockout genetics for Cthrc1 phenotypes; both pairs are not ortholog-inferred [PMID:18606138].","localisation_and_range":"CTHRC1 flagged secreted; ROR2 flagged transmembrane [flag]; paper describes cell-surface-anchored Cthrc1 [PMID:18606138].","caveats":"Single paper; overexpression system; no affinity.","key_references":[{"PMID":"18606138","why":"Cthrc1 binds Ror2 and Fzd to form a Wnt complex"}],"covers":["LR001763","LR005121"]},"LR000405":{"pair":"CXCL16 -> CXCR6","headline":"Well-established pair: CXCL16 binds CXCR6 with high affinity and drives chemotaxis and signalling, across several papers.","interaction_type":"direct binding","direction_and_effect":"Expression cloning identified Bonzo (CXCR6) as a CXCL16 receptor [PMID:11017100]. Recombinant CXCL16 gave chemotaxis, high-affinity binding and calcium mobilisation only in Bonzo transfectants, negative on all other chemokine receptor transfectants tested [PMID:11290797]. In human aortic smooth muscle cells CXCL16 activated NF-kappa B through Gi, PI3K and Akt [PMID:14625285]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"CXCR6 alone suffices in transfectants [PMID:11290797]. CXCL16 binds CXCR6 and scavenger-receptor ligands through overlapping motifs in the chemokine domain [PMID:15128749].","affinity_potency":[{"value":"pKd 9.0","assay":"binding to Bonzo (CXCR6) transfectants","system":"transfected cells","cite":"PMID:11290797"}],"species_and_systems":"Human cells in the cited work; mouse pair is projected from human. T cells and tonsil CD4+ lymphocytes migrated to CXCL16 [PMID:11290797]; smooth muscle cells in [PMID:14625285].","localisation_and_range":"CXCL16 is a transmembrane chemokine with membrane-bound and soluble shed forms [PMID:11017100]; flagged secreted and transmembrane [flag]. Juxtacrine and paracrine action are both possible.","caveats":"All papers read as abstracts only. Five of eight confirmed papers shown. The scavenger-receptor overlap [PMID:15128749] is a different activity. Reactome records binding [DB:Reactome].","key_references":[{"PMID":"11017100","why":"Identifies CXCR6 as CXCL16 receptor by expression cloning"},{"PMID":"11290797","why":"High-affinity binding, chemotaxis and calcium flux with panel specificity"},{"PMID":"14625285","why":"CXCL16-CXCR6 signalling to NF-kappa B in smooth muscle cells"}],"covers":["LR000405","LR003910"]},"LR000414":{"pair":"CXCL5 -> CXCR2","headline":"Well supported agonist: high-affinity binding and potent signalling at CXCR2, with GtoPdb record and structures.","interaction_type":"direct binding","direction_and_effect":"Agonist at IL8RB (CXCR2) in calcium flux, EC50 11 nM [PMID:8702798]; radiolabelled IL-8 was displaced from CXCR2 by ENA-78 [PMID:9692902]. Neutrophil data say all three CXC chemokines bind CXCR-2 with high affinity [PMID:10593335]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor requirement reported. PDB 8XWS and 8XX7 contain a CXCL5 chain and a CXCR2 chain [DB:PDB 8XWS].","affinity_potency":[{"value":"EC50 11 nM","assay":"calcium flux at IL8RB","system":"HEK293 transfectants","cite":"PMID:8702798"},{"value":"pIC50 6.9 to 9.0","assay":"GtoPdb affinity range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human HEK293 transfectants [PMID:8702798]; the human row of PMID:9692902 was propagated from a mouse-row curation; species of 10593335 is unspecified in the curation.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"All papers abstract-only. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"8702798","why":"EC50 at IL8RB"},{"PMID":"9692902","why":"Displacement and migration at CXCR2"},{"PMID":"10593335","why":"High-affinity CXCR-2 binding on neutrophils"}],"covers":["LR000414","LR003914"]},"LR005130":{"pair":"CYTL1 -> CCR2","headline":"CYTL1 is reported as a functional CCR2 (CCR2B) agonist, with binding, chemotaxis and knockout evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: CYTL1 chemoattracts monocytes and macrophages through CCR2B and the ERK pathway; pertussis toxin sensitivity indicates Gi-coupled signalling [PMID:27084102].","molecular_requirements":"CCR2B is the receptor isoform tested; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CYTL1 and CCR2B in HEK293 cells (chemotaxis, internalization, radioactive binding); human monocytes responded but PBLs did not. Human and mouse recombinant CYTL1 attracted wild-type but not Ccr2-/- mouse macrophages [PMID:27084102].","localisation_and_range":"CYTL1 is flagged as secreted [flag]; CCR2 is flagged as a transmembrane receptor [flag]. Signalling is therefore paracrine/endocrine by annotation.","caveats":"Single paper, read as abstract only; no affinity value reported in our evidence.","key_references":[{"PMID":"27084102","why":"Binding, chemotaxis and Ccr2-/- macrophage evidence for CYTL1-CCR2B"}],"covers":["LR001773","LR005130"]},"LR000432":{"pair":"DEFB4A -> CCR6","headline":"Well supported: human beta-defensin 2 binds and signals through CCR6 in human and mouse systems, with database agreement.","interaction_type":"direct binding","direction_and_effect":"Human beta-defensin was selectively chemotactic for CCR6-transfected cells, sensitive to pertussis toxin and to anti-CCR6 antibodies, and displaced iodinated LARC (CCL20) from CCR6-transfected cells [PMID:10521347]. hBD2:Ig fusion binding to CCR6-expressing cells and chemotaxis are reported for the human ligand [PMID:20068036]. GtoPdb lists a full agonist [DB:GtoPdb]. Murine defensins 2 and 3 also bind murine CCR6 [PMID:11714836].","molecular_requirements":"Not reported in our evidence beyond CCR6 alone being sufficient in transfected cells [PMID:10521347].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in CCR6-transfected cells [PMID:10521347][PMID:20068036]; mouse defensins and mouse CCR6 with dendritic cells [PMID:11714836]. The CCR2 paper reports hBD2:Ig binding human and mouse CCR6 as earlier work [PMID:20483750].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"All three key papers were read as abstract only. The 1999 abstract says 'human beta-defensins' without naming DEFB4A specifically [PMID:10521347]. GtoPdb gives no affinity units [DB:GtoPdb]. Two further papers were review-only and one is pending.","key_references":[{"PMID":"10521347","why":"Chemotaxis of CCR6 cells, antibody block, LARC displacement"},{"PMID":"20068036","why":"hBD2:Ig binding to CCR6-expressing cells"},{"PMID":"11714836","why":"Murine beta-defensin 2/3 binding to mouse CCR6"}],"covers":["LR000432"]},"LR000441":{"pair":"DKK1 -> KREMEN2","headline":"Direct high-affinity binding reported for Kremen2, with a ternary complex with LRP6; mainly one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Kremen2 is a high-affinity Dkk1 receptor that cooperates with Dkk1 to block Wnt/beta-catenin signalling [PMID:12050670].","molecular_requirements":"Kremen2 forms a ternary complex with Dkk1 and LRP6 and induces rapid endocytosis and removal of LRP6 from the plasma membrane [PMID:12050670]. Reactome lists a KRM:DKK:LRP5/6 complex at the plasma membrane [DB:Reactome R-HSA-3769399].","affinity_potency":[],"species_and_systems":"Species not stated in the abstract; the human pair is ortholog-inferred and the mouse pair is not [PMID:12050670].","localisation_and_range":"KREMEN2 is flagged as a receptor [flag].","caveats":"Abstract only; no affinity value in our evidence. One further row is pending.","key_references":[{"PMID":"12050670","why":"Kremen1/2 are high-affinity Dkk1 receptors; Kremen2-Dkk1-LRP6 ternary complex"}],"covers":["LR000441","LR003933"]},"LR000450":{"pair":"DLL1 -> NOTCH3","headline":"DLL1 directly binds soluble Notch3 and signals through mouse Notch3; two verified papers.","interaction_type":"direct binding","direction_and_effect":"Delta1 directly bound soluble Notch3 extracellular fusion protein in solid-phase assays with different affinities, in a Ca2+-dependent manner [PMID:11006133]. Murine Notch3 signals in response to Delta 1 and Jagged 1 [PMID:12482954]; the paper's evidence is about the R142C CADASIL mutant signalling as well as wild-type.","molecular_requirements":"Notch3 extracellular domain suffices for binding in the fusion assay [PMID:11006133]. Further subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human fusion proteins [PMID:11006133]; stable cell lines expressing murine Notch 3 [PMID:12482954]. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"Membrane-bound ligand; DLL1 flagged secreted and transmembrane [flag].","caveats":"Both abstract-only. Species not recorded for PMID:12482954. Three abstract-insufficient, one review-only and one pending paper not shown. No affinity numbers in our evidence.","key_references":[{"PMID":"11006133","why":"Direct binding of Delta1 to soluble Notch3"},{"PMID":"12482954","why":"Murine Notch3 signals in response to Delta 1"}],"covers":["LR000450","LR003942"]},"LR002502":{"pair":"DSG2 -> DSG2","headline":"Homophilic DSG2 trans self-binding shown by cross-linking in human keratinocytes; abstract-level evidence only.","interaction_type":"direct binding","direction_and_effect":"DSG2 binds itself: extracellular cross-linking gave homophilic, isoform-specific adducts in HaCaT keratinocytes, consistent with trans (cell-cell) interaction [PMID:21098030]. No directional effect beyond a curator agonist-style label is reported.","molecular_requirements":"Trp-2 and Ala-80 mutation abolished Dsc2 binding specifically, not tested for DSG2 [PMID:21098030]. Other subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HaCaT keratinocytes (cross-linking, electron microscopy) [PMID:21098030]. Pair is recorded for human (ortholog-projected) and mouse; no mouse experiment is in our evidence.","localisation_and_range":"Membrane-bound desmosomal cadherin; trans cell-cell contact, adducts in the detergent-insoluble fraction and probably in desmosomes [PMID:21098030]. Entity flags mark it as a transmembrane receptor [flag].","caveats":"Only the abstract was read. The authors found no evidence for heterophilic or cis interaction (not fully excluded) [PMID:21098030]. No affinity reported, and no database record.","key_references":[{"PMID":"21098030","why":"Cross-linking evidence for homophilic, isoform-specific desmosomal cadherin binding"}],"covers":["LR002502","LR005770"]},"LR001800":{"pair":"EDIL3 -> ITGB3","headline":"Del1 drives alphaVbeta3-dependent endothelial adhesion and HSC regulation via beta3; functional only.","interaction_type":"functional only","direction_and_effect":"Del1 promoted alphavbeta3-dependent endothelial attachment, clustering and FAK/MAPK/Shc phosphorylation, blocked by an anti-alphavbeta3 antibody; an RAD mutant was inactive [PMID:10196194]. Del-1 effects on HSCs were mediated by beta3 integrin [PMID:28846069].","molecular_requirements":"alphaVbeta3 heterodimer; RGD motif needed [PMID:10196194].","affinity_potency":[],"species_and_systems":"Chick CAM and endothelial cells [PMID:10196194]; mouse HSC niche [PMID:28846069].","localisation_and_range":"Secreted extracellular matrix protein [PMID:10196194].","caveats":"Both abstract only; no direct binding measurement in our evidence.","key_references":[{"PMID":"10196194","why":"Del1 ligates alphavbeta3 in endothelial adhesion"},{"PMID":"28846069","why":"Beta3 integrin mediates Del-1 HSC effects"}],"covers":["LR001800","LR005156"]},"LR009000":{"pair":"EFEMP2 -> AQP1","headline":"Database-only: a two-hybrid pooling physical association; no ligand-receptor evidence.","interaction_type":"database-asserted only","direction_and_effect":"No curated paper evidence. The only record is an IntAct physical association by two hybrid pooling (EBI-755773) [DB:IntAct]. Direction and effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human yeast two-hybrid pooling record [PMID:16189514] via [DB:IntAct]; no other system reported.","localisation_and_range":"Not reported in our evidence; no localisation flags for the ligand.","caveats":"Rests on one high-throughput two-hybrid record, which does not establish that AQP1 is a receptor for EFEMP2. No papers were judged for this pair.","key_references":[],"covers":["LR009000"]},"LR000504":{"pair":"EFNA5 -> EPHA6","headline":"Only an IntAct coimmunoprecipitation record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists an association by anti-tag coimmunoprecipitation [DB:IntAct]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"EFNA5 flagged membrane-bound; EPHA6 flagged membrane-bound [flag].","caveats":"All four judged papers were review-only; a single database record supports it.","key_references":[],"covers":["LR000504","LR003995"]},"LR000513":{"pair":"EFNB1 -> EPHB6","headline":"Ligand-induced EphB6 phosphorylation shown, but indirect: it needs a kinase-active partner such as EphB1.","interaction_type":"functional only","direction_and_effect":"Ephrin-B1 stimulation induced tyrosine phosphorylation of EphB6 despite its lack of kinase activity [PMID:11713248]. Annotated stimulatory.","molecular_requirements":"EphB6 is catalytically inactive; EphB1 transphosphorylated it in a ligand-dependent way requiring EphB1 catalytic activity, and the two formed a stable hetero-complex [PMID:11713248]. A complex-level (EphB1+EphB6) readout, so a single-subunit expression score may mislead.","affinity_potency":[],"species_and_systems":"Recombinant overexpression; curator annotation lists human [PMID:11713248].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine). The receptor is flagged as secreted too [flag], which is unexplained.","caveats":"Abstract only. Direct ephrin-B1 binding to EphB6 was not shown; phosphorylation was mediated through EphB1 [PMID:11713248].","key_references":[{"PMID":"11713248","why":"Ephrin-B1 induces EphB6 phosphorylation via EphB1 cross-talk"}],"covers":["LR000513","LR004004"]},"LR004005":{"pair":"EFNB1 -> ERBB2","headline":"Co-immunoprecipitation shows EphrinB1 and ErbB2 in a complex in breast cancer cells; this is not ligand-receptor binding evidence.","interaction_type":"functional only","direction_and_effect":"EphrinB1 interacts with ErbB2 by co-immunoprecipitation and colocalisation; the oncogenic V660E ErbB2 mutation enhances this, and Src mediates EphrinB1 phosphorylation [PMID:22279592]. No activating or inhibiting effect on ErbB2 was reported.","molecular_requirements":"Part of an ErbB2-Src-EphrinB1 complex regulated by PTPN13 [PMID:22279592].","affinity_potency":[],"species_and_systems":"Breast cancer cells; species not reported in our evidence [PMID:22279592]. IntAct has anti-bait co-IP records [DB:IntAct].","localisation_and_range":"EphrinB1 is annotated non-secreted, transmembrane [flag]; ErbB2 is a transmembrane receptor [flag].","caveats":"Co-IP does not show direct binding or ligand function. Abstract only; the full-text excerpts concern a gene-expression dataset and do not bear on this pair [PMID:22279592].","key_references":[{"PMID":"22279592","why":"EphrinB1-ErbB2 co-IP in breast cancer cells"}],"covers":["LR000514","LR004005"]},"LR000522":{"pair":"EFNB2 -> EPHB6","headline":"Direct, saturable EphB6-Fc binding to ephrin-B2 (not ephrin-B1) in one paper, plus an ELISA.","interaction_type":"direct binding","direction_and_effect":"EphB6-Fc showed high-affinity saturable binding to ephrin-B2-transfected COS cells but not ephrin-B1 [PMID:10648835]. Ephrin-B2 Fc binds best to all EphB receptors in ELISA [PMID:22568954].","molecular_requirements":"not reported in our evidence. EphB6 is catalytically inactive in other work in this batch, so signalling likely needs partners (not shown here).","affinity_potency":[],"species_and_systems":"Human EphB6-Fc, COS cells, Reh pro-B leukemic line; EphB6 and ephrin-B2 expressed in human thymus [PMID:10648835]. Interaction class is Ligand-Receptor with no effect annotation.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine). The receptor is also flagged secreted [flag].","caveats":"Abstract hedges: the ligand is called a 'candidate' and 'may be a physiological ligand' [PMID:10648835]. No numeric affinity. ELISA quote is unverified.","key_references":[{"PMID":"10648835","why":"EphB6-Fc binds ephrin-B2, not ephrin-B1"},{"PMID":"22568954","why":"ELISA across ephrin-Bs and EphB receptors"}],"covers":["LR000522","LR004013"]},"LR004014":{"pair":"Efnb2 -> Grm1","headline":"Co-IP and a functional link in mouse brain, but the paper excluded a physical interaction in HEK293 cells.","interaction_type":"conflicting","direction_and_effect":"Co-immunoprecipitation of ephrinB2 with mGlu1a (all brain regions tested) and with mGlu5 (corpus striatum) in brain tissue [PMID:15745950]. Clustered EphB1 acting on ephrinB2 amplified mGlu-receptor-stimulated PI hydrolysis in striatal slices [PMID:15745950]. Effect was abolished by mGlu1 or NMDA receptor antagonists [PMID:15745950]. EphrinB2 here acts as signalling partner, not as an mGlu1 ligand.","molecular_requirements":"NMDA receptor NR1 coimmunoprecipitated with mGlu1a and ephrinB2 in striatal lysates [PMID:15745950].","affinity_potency":[],"species_and_systems":"Mouse brain regions, cultured neurons, striatal slices; HEK293 for FRET [PMID:15745950]. Pair is ortholog-inferred in mouse.","localisation_and_range":"Ephrin-B2 is annotated non-secreted (receptor flag set) [flag]; mGlu1 membrane protein; range is cell-local.","caveats":"FRET and coclustering in HEK293 cells excluded a physical interaction between ephrinB2 and mGlu1a; the authors propose adaptors or scaffolds [PMID:15745950]. Abstract only.","key_references":[{"PMID":"15745950","why":"Ephrin-B2/mGlu1 functional crosstalk; no direct interaction"}],"covers":["LR004014"]},"LR000531":{"pair":"EGF -> EGFR","headline":"EGF is the canonical, well-characterised agonist of EGFR, with structural, binding and functional evidence.","interaction_type":"direct binding","direction_and_effect":"EGF binds EGFR and induces receptor dimerisation and kinase activation [PMID:8639530]. A 2:2 crystal structure of human EGF with the EGFR extracellular region shows EGF docked between domains I and III, with receptor-mediated dimerisation [PMID:12297050]. In the unliganded autoinhibited structure, EGF binding must promote a large domain rearrangement to activate the receptor [PMID:12620237]. Downstream effects include EGFR polyubiquitination [PMID:10788520] and PLD1 activation (2.8-fold) [PMID:9837959].","molecular_requirements":"EGFR alone is sufficient; the extracellular region (domains I-IV) binds EGF and dimerises [PMID:12297050]. Native EGF does not gain high affinity for ErbB-2/ErbB-3 heterodimers unless its N-terminal region is replaced [PMID:12093292].","affinity_potency":[],"species_and_systems":"Human proteins and cells (A431, HEK293, 32D lines) [PMID:6289330][PMID:36505413]. Co-crystal structures, NanoBRET binding in HEK293 cells, sedimentation, cross-linking [PMID:36505413][PMID:8639530]. Also in BioGRID, IntAct, PDB, Reactome, GtoPdb [DB:GtoPdb].","localisation_and_range":"EGF is secreted and EGFR is transmembrane [flag]; paracrine or autocrine ligand to a membrane receptor.","caveats":"Many curated papers use EGF only as a trigger for EGFR activation rather than studying binding [PMID:11228164][PMID:15620700]. GtoPdb lists affinity in pKi but no value is given in our evidence [DB:GtoPdb]. Only 10 of 22 judged rows are shown here.","key_references":[{"PMID":"12297050","why":"Crystal structure of the EGF-EGFR extracellular complex"},{"PMID":"36505413","why":"NanoBRET EGF binding to full-length EGFR; nanobody competition"},{"PMID":"8639530","why":"EGF binding, dimerisation and kinase activation measured together"}],"covers":["LR000531","LR004022"]},"LR004023":{"pair":"EGF -> ERBB2","headline":"No direct EGF-ERBB2 interaction is supported by curated papers; the only paper examined argues against it for native EGF.","interaction_type":"conflicting","direction_and_effect":"Wild-type EGF gains affinity for ErbB-2/ErbB-3 heterodimers only after its N-terminal linear region is replaced by NRG-1 or TGF-alpha sequences [PMID:12093292].","molecular_requirements":"Not reported in our evidence beyond engineered variants.","affinity_potency":[],"species_and_systems":"Human cells and phage-display variants [PMID:12093292]. PDB 8HGO (EM) shows an EGF-bound EGFR/HER2 ectodomain complex [DB:PDB 8HGO]. Reactome lists EGF:EGFR:ERBB2 complexes [DB:Reactome].","localisation_and_range":"EGF is secreted and ERBB2 is transmembrane [flag].","caveats":"Both judged rows are pair_absent. Database support (BioGRID reconstituted complex, PDB, Reactome) concerns receptor heterodimers with EGFR and does not show EGF binding ERBB2 itself in our evidence [DB:BioGRID].","key_references":[{"PMID":"12093292","why":"Evidence against native EGF binding ErbB-2/ErbB-3"}],"covers":["LR000532","LR004023"]},"LR000540":{"pair":"F10 -> ITGB2","headline":"Factor X binds Mac-1 on stimulated human monocytes; ITGB2 is supported only through the Mac-1 heterodimer.","interaction_type":"direct binding","direction_and_effect":"125I-factor X bound saturably to stimulated human monocytes and was cross-linked to Mac-1, immunoprecipitated with the anti-alpha subunit antibody OKM10 [PMID:2835359].","molecular_requirements":"Evidence is for the Mac-1 receptor; the antibody targets the alpha subunit, so a role for ITGB2 specifically is not shown in our evidence. Requires Ca2+ [PMID:2835359].","affinity_potency":[{"value":"Kd 21.8-44.9 nM","assay":"saturable 125I-factor X binding","system":"ADP- or ionomycin-stimulated human monocytes","cite":"PMID:2835359"}],"species_and_systems":"Human factor X and monocytes [PMID:2835359]; mouse pair ortholog-inferred [flag].","localisation_and_range":"F10 flagged secreted [flag].","caveats":"Abstract-only single paper; beta-chain-only evidence absent. ITGB2 pairs with ITGAM here by inheritance.","key_references":[{"PMID":"2835359","why":"Factor X binds Mac-1 on monocytes"}],"covers":["LR000540","LR004031"]},"LR004032":{"pair":"F13A1 -> ITGA4","headline":"Factor XIII supports alpha4beta1-mediated MOLT-3 cell adhesion; functional evidence only.","interaction_type":"functional only","direction_and_effect":"MOLT-3 cell adhesion to FXIII was mediated by alpha4beta1 and blocked by anti-alpha4 antibody [PMID:10816592].","molecular_requirements":"Evidence is for alpha4beta1 (ITGA4 with ITGB1); alpha4 alone not tested separately in our evidence.","affinity_potency":[],"species_and_systems":"Human cells; MOLT-3 lymphocyte-like leukemia [PMID:10816592].","localisation_and_range":"FXIII flagged secreted; adhesion to substrate-bound protein [flag].","caveats":"Cell-adhesion plus blocking antibody, not purified binding. No affinity.","key_references":[{"PMID":"10816592","why":"FXIII is an alpha4beta1 and alpha9beta1 ligand in adhesion assays"}],"covers":["LR000541","LR004032"]},"LR004041":{"pair":"F8 -> ASGR2","headline":"Factor VIII binds ASGPR (Kd about 2 nM); ASGR2 specifically is supported by a heterodimer-level SPR paper and a genetics abstract.","interaction_type":"direct binding","direction_and_effect":"FVIII bound ASGPR dose-dependently with high affinity [PMID:15946216]. A second paper states ASGPR binds FVIII with high affinity and links ASGR2 5'UTR haplotypes to FVIII distribution in haemophilia A patients; its abstract is truncated [PMID:34407556].","molecular_requirements":"Only the FVIII heavy chain bound, via B-domain elements, with calcium dependence and glycan dependence [PMID:15946216]. ASGR2 is described as the minor subunit of ASGPR in curator notes, so ASGR1 may also be needed.","affinity_potency":[{"value":"Kd approximately 2 nM","assay":"surface plasmon resonance","system":"FVIII with ASGPR","cite":"PMID:15946216"}],"species_and_systems":"SPR and mouse clearance [PMID:15946216]; patient pharmacokinetic study [PMID:34407556].","localisation_and_range":"Localisation: not reported in our evidence.","caveats":"Both papers are abstract-only; the 2022 abstract is truncated and gives no binding data of its own. Neither isolates ASGR2 from the heterodimer.","key_references":[{"PMID":"15946216","why":"SPR binding of FVIII to ASGPR, Kd about 2 nM"},{"PMID":"34407556","why":"ASGR2 genetic variation and FVIII pharmacokinetics"}],"covers":["LR000550","LR004041"]},"LR002610":{"pair":"FAM3B -> FGFR2","headline":"FAM3B is reported as an FGFR ligand in one Xenopus paper; FGFR2-specific evidence is thin.","interaction_type":"functional only","direction_and_effect":"The paper shows FAM3B as an FGFR ligand in Xenopus, with ERK activation via FGFR1 [PMID:33975953]. Purified human FAM3B was incubated with Fc-tagged human FGFR1-4 ectodomains, with FGFR2-Ecto-Fc one of the panels; the excerpts do not show the FGFR2 result itself [PMID:33975953].","molecular_requirements":"FGFR1 kinase-inactive mutant with intact ectodomain still bound FAM3B; no co-receptor requirement reported [PMID:33975953]. Whether FGFR2 acts alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Xenopus embryos, HEK293T cells and recombinant human FAM3B; curation row labels species human [PMID:33975953].","localisation_and_range":"FAM3B is secreted [flag] and detected in HEK293T medium [PMID:33975953].","caveats":"Single paper. The abstract does not say which of FGFR1-4 binds; all four rows rest on a family-level claim, and the main system is Xenopus [PMID:33975953]. No affinity reported. FGF family paralog overlap is possible.","key_references":[{"PMID":"33975953","why":"FAM3B binds FGFR ectodomain and activates ERK in Xenopus/HEK293T"}],"covers":["LR002610","LR005877"]},"LR011232":{"pair":"FASLG -> TNFRSF1A","headline":"No curator-verified paper supports this pair; only BioGRID records assert it.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. The interaction record is labelled Stimulatory [flag], but no paper confirms it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; BioGRID records are Co-purification and Affinity Capture-Western [DB:BioGRID].","localisation_and_range":"FASLG is flagged secreted and transmembrane; TNFRSF1A is flagged transmembrane receptor [flag].","caveats":"Three papers were judged abstract_insufficient and three were judged different_entity, so none supports the pair. Two BioGRID records (PMID 15659383, 12753742) are the only support [DB:BioGRID]. Whether the association is direct is not reported in our evidence.","key_references":[],"covers":["LR011232"]},"LR004050":{"pair":"FBN1 -> ITGAV","headline":"Fibrillin-1 binds alphaV integrins; direct binding measured for alphaVbeta6 (K(d) approximately 0.45 mum) and functional support for alphaVbeta3.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaVbeta6 is identified as a novel receptor for fibrillin-1 with a K(d) of approximately 0.45 mum, by surface plasmon resonance [PMID:17158881]. Fibroblast adhesion to fibrillin-1 was mediated by alpha 5 beta 1 with alpha v beta 3 contributing [PMID:12807887], and PF14 signaling in HUVECs used alpha v beta 3 [PMID:20686071].","molecular_requirements":"AlphaV needs a beta partner (beta3 or beta6 shown). Module requirements for alphaVbeta6 activation differ from those of alphaVbeta3 [PMID:17158881]. The RGD loop in TB4 mediates adhesion via alphaVbeta3 [PMID:17158881].","affinity_potency":[{"value":"K(d) approximately 0.45 mum","assay":"surface plasmon resonance with recombinant fibrillin fragments (alphaVbeta6)","system":"human fibrillin-1","cite":"PMID:17158881"}],"species_and_systems":"Human proteins and cells in all three papers [PMID:17158881] [PMID:12807887] [PMID:20686071]; the mouse pair is ortholog-inferred. Reactome and UniProt records cover alphaVbeta3 [DB:Reactome] [DB:UniProt].","localisation_and_range":"FBN1 is flagged secreted, not transmembrane [flag]; assembled microfibrils are matrix [PMID:12807887].","caveats":"The affinity applies to alphaVbeta6, not ITGAV with the beta3 partner. All papers abstract only. Entity ITGAV is annotated as integrin alphaV beta3.","key_references":[{"PMID":"17158881","why":"Binding of fibrillin-1 to alphaVbeta6, with Kd."},{"PMID":"12807887","why":"Cell adhesion via alpha5beta1 and alphaVbeta3."},{"PMID":"20686071","why":"Endothelial signaling by fibrillin-1 fragment."}],"covers":["LR000559","LR004050"]},"LR000612":{"pair":"FGF2 -> FGFRL1","headline":"FGF2 binds FGFR5/FGFRL1 extracellular domains in one abstract-only study; likely a decoy receptor.","interaction_type":"direct binding","direction_and_effect":"Recombinant FGFR5 beta-Fc and gamma-Fc bound FGF-2 specifically, but not FGF-7 or EGF [PMID:11418238]. Affinity was lower than for FGFR2C [PMID:11418238].","molecular_requirements":"Only the extracellular domains were tested, both splice variants (three or fewer Ig domains) [PMID:11418238]. FGFRL1 lacks an intracellular tyrosine kinase domain per the curator note, so it cannot signal conventionally [PMID:11418238].","affinity_potency":[],"species_and_systems":"Recombinant Fc fusions; the abstract describes a murine FGFR5, though the dossier labels experiment species as human [PMID:11418238]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Single abstract-only paper; no affinity value and no signalling readout, so effect (decoy or regulator) is inferred, not shown. Species labelling may be wrong.","key_references":[{"PMID":"11418238","why":"Recombinant FGFR5-Fc binds FGF-2 specifically"}],"covers":["LR000612","LR004096"]},"LR007200":{"pair":"FGF2 -> ITGAV:ITGB3","headline":"FGF2 binds the integrin alphavbeta3 complex by SPR, and integrin-binding-defective FGF2 mutants act as antagonists; one paper plus UniProt.","interaction_type":"direct binding","direction_and_effect":"WT FGF2 bound soluble \u03b1v\u03b23 on SPR; K119E/R120E and K125E mutants bound poorly or not at all, were inactive in ERK1/2 and DNA-synthesis assays, and suppressed WT FGF2 signalling in endothelial cells [PMID:28302677]. UniProt: ITGAV:ITGB3 binds FGF2 and this binding is essential for FGF2 signalling [DB:UniProt].","molecular_requirements":"The \u03b1v\u03b23 heterodimer was used; FGF2 may also bind \u03b15\u03b21 per K562 adhesion data [PMID:28302677].","affinity_potency":[{"value":"Kd 7.75 \u00d7 10\u22128 M","assay":"SPR, WT FGF2 on immobilised soluble \u03b1v\u03b23","system":"recombinant, in vitro","cite":"PMID:28302677"},{"value":"Kd 1.1 \u00d7 10\u22126 M","assay":"SPR, K125E mutant","system":"recombinant, in vitro","cite":"PMID:28302677"}],"species_and_systems":"Human recombinant proteins; signalling readouts in NIH3T3 and HUVEC cells [PMID:28302677].","localisation_and_range":"FGF2 is flagged secreted; the integrin complex is flagged transmembrane [flag], consistent with paracrine ligand acting on a cell-surface receptor.","caveats":"Docking energy and interface residues are predicted; the authors do not rule out indirect effects of the mutations. Only one paper; curated sentence read at abstract level.","key_references":[{"PMID":"28302677","why":"SPR and mutant evidence for FGF2-\u03b1v\u03b23"}],"covers":["LR007200"]},"LR000603":{"pair":"FGF23 -> FGFR1","headline":"FGF23 binds and activates FGFR1c; supported by SPR, mitogenesis, pull-downs and structures, with Klotho in the complex.","interaction_type":"direct binding","direction_and_effect":"FGF23 binds and activates the c splice isoforms of FGFR1-3 and FGFR4, but not the b isoforms [PMID:16081635, PMID:16597617]. Curated effect is stimulatory [PMID:16081635].","molecular_requirements":"c isoform only; highly sulfated, longer glycosaminoglycans promoted activity [PMID:16081635]. Reactome and PDB describe a complex of FGF23, Klotho and FGFR1c [DB:Reactome R-HSA-190218, DB:PDB 5W21].","affinity_potency":[],"species_and_systems":"Human reagents per curators (SPR and mitogenesis) with opossum kidney cells for signaling [PMID:16081635]; BaF3 screen with unspecified species [PMID:16597617]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGF23 flagged secreted [flag]; the paper proposes it circulates to the kidney [PMID:16081635].","caveats":"The 2005 paper names FGFR1-3 collectively, not FGFR1 alone, and was read as an abstract only [PMID:16081635]. BioGRID and IntAct records add support [DB:BioGRID, DB:IntAct].","key_references":[{"PMID":"16081635","why":"SPR and mitogenesis of FGF23 on FGFR c isoforms"},{"PMID":"16597617","why":"BaF3 receptor-specificity screen"}],"covers":["LR000603","LR004087"]},"LR004104":{"pair":"FGF3 -> FGFR2","headline":"FGF3 binds FGFR2 IIIb with high affinity and FGFR2 IIIc with lower affinity; direct binding plus mitogenic evidence.","interaction_type":"direct binding","direction_and_effect":"Fgf3 bound the IIIb isoforms of FgfR1 and FgfR2 with high affinity and FgfR2 IIIc with lower affinity [PMID:7592624]. FGF3 activates b splice forms of FGFR1 and 2 [PMID:8663044]. Stimulatory.","molecular_requirements":"IIIb preferred; IIIc weaker [PMID:7592624].","affinity_potency":[{"value":"ID50 = approximately 0.8 nM","assay":"binding competition","system":"IIIb isoforms of FgfR1 and FgfR2","cite":"PMID:7592624"},{"value":"ID50 = approximately 9 nM","assay":"binding competition","system":"FgfR2 IIIc","cite":"PMID:7592624"}],"species_and_systems":"Purified mouse fgf3 [PMID:7592624]; BaF3 screen species unspecified [PMID:8663044].","localisation_and_range":"FGFR2 transmembrane [flag].","caveats":"Abstract-only readings; ID50 values are approximate. Human pair is ortholog-inferred; mouse pair is direct.","key_references":[{"PMID":"7592624","why":"Affinity of Fgf3 for FgfR2 IIIb and IIIc"},{"PMID":"8663044","why":"BaF3 mitogenic screen"}],"covers":["LR000620","LR004104"]},"LR000621":{"pair":"FGF4 -> FGFR1","headline":"FGF4 binds and activates FGFR1 IIIc, not IIIb; evidence includes crystal structure of FGF4 and database records.","interaction_type":"direct binding","direction_and_effect":"FGF4 binds and activates the IIIc splice forms of FGFR1-3 with little activity toward IIIb forms or FGFR4 [PMID:11486033].","molecular_requirements":"IIIc isoform required; heparin contacts are involved in a modelled ternary FGF4-FGFR1-heparin complex [PMID:11486033].","affinity_potency":[],"species_and_systems":"Human FGF4 crystal structure at 1.8 A with mutagenesis [PMID:11486033]. BioGRID lists a reconstituted complex and IntAct an SPR record [DB:BioGRID, DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The ternary complex is modelled, not solved. Abstract-only reading. Several other rows not shown.","key_references":[{"PMID":"11486033","why":"FGF4 structure and FGFR IIIc specificity"}],"covers":["LR000621","LR004105"]},"LR000630":{"pair":"FGF6 -> FGFR1","headline":"Supported mainly by BaF3 survey and database records; no direct binding paper in our evidence.","interaction_type":"functional only","direction_and_effect":"The BaF3 survey states FGFs 4, 5, 6 and 8 specifically activate c receptor splice forms [PMID:8663044].","molecular_requirements":"c splice-form selectivity is described [PMID:8663044]. UniProt-listed FGFR1 interactions include FGF6 in vitro [DB:UniProt]; IntAct records a surface plasmon resonance interaction [DB:IntAct]; BioGRID has a protein-peptide record [DB:BioGRID].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic assays on FGFR-expressing cell lines; species of ligand and receptor listed as unspecified [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"Only one paper (abstract only; browser-read quote pending spot-check) and the quoted sentence does not name FGFR1. Database records rest on assays whose details are not in our dossier.","key_references":[{"PMID":"8663044","why":"BaF3 survey, FGF6 activates c splice forms"}],"covers":["LR000630","LR004114"]},"LR004122":{"pair":"FGF8 -> FGFR2","headline":"FGF8 activates FGFR2c in BaF3 assays; a PDB structure and BioGRID record exist.","interaction_type":"functional only","direction_and_effect":"FGF8 subfamily members specifically activated FGFRs 1c, 2c and 3c and FGFR4 (4\u0394) [PMID:16597617]; FGFs 4, 5, 6 and 8 specifically activate c splice forms [PMID:8663044]. The pair is annotated stimulatory.","molecular_requirements":"c splice form of FGFR2 is responsive [PMID:16597617]. A PDB entry 2FDB contains a chain of each partner [DB:PDB 2FDB]; BioGRID has a protein-peptide record [DB:BioGRID].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic assays on FGFR-expressing cell lines; species of ligand and receptor listed as unspecified [PMID:16597617][PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"Both papers are the same BaF3 mitogenic format with browser-read quotes pending spot-check; no direct binding assay or affinity in our evidence. The PDB detail does not state species.","key_references":[{"PMID":"16597617","why":"FGF8 subfamily activates FGFR2c"},{"PMID":"8663044","why":"FGF8 activates c splice forms"}],"covers":["LR000638","LR004122"]},"LR004131":{"pair":"FGG -> ITGB2","headline":"Eosinophil adhesion to fibrinogen depends on alphaMbeta2 (beta2 chain); one functional paper.","interaction_type":"functional only","direction_and_effect":"Airway eosinophil adhesion to fibrinogen was alphaMbeta2-mediated and blocked by anti-alphaMbeta2 [PMID:16601240].","molecular_requirements":"ITGB2 acts as the beta chain with ITGAM (alphaMbeta2); the assay used whole fibrinogen [PMID:16601240].","affinity_potency":[],"species_and_systems":"Eosinophils; organism not stated in the dossier abstract [PMID:16601240]. Mouse pair ortholog-inferred.","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"One paper, abstract only, adhesion not binding; chain attribution follows the resource encoding. No database records.","key_references":[{"PMID":"16601240","why":"Eosinophil adhesion to fibrinogen via alphaMbeta2"}],"covers":["LR000647","LR004131"]},"LR008010":{"pair":"FLRT2:UNC5D -> ADGRL3","headline":"FLRT2 and UNC5D in cis form a ternary complex with latrophilin-3 (ADGRL3); crystal structure and binding data support it.","interaction_type":"direct binding","direction_and_effect":"Unc5D interacts with FLRT2 in cis and controls cell adhesion in response to externally presented Lphn3: FLRT2/Unc5D double-transfected HeLa cells adhered less (about 70% of cells) to Lphn3 than controls, and a FLRT2 mutant unable to bind Unc5 restored >80% adhesion, so Unc5D acts as a switch attenuating Lphn3-driven adhesion [PMID:27091502].","molecular_requirements":"All three ectodomains are needed for the complex: FLRT2 bridges Unc5 and Lphn3, binding is cooperative, and Lphn3 dimerises, giving 1:1:2 (FLRT2:Unc5D:Lphn3), which can dimerise further to 2:2:4 [PMID:27091502]. Unc5D did not bind the Lphn3 Olf domain without FLRT2 [PMID:27091502]. SPR suggested a >5-fold affinity increase for Unc5D binding to FLRT2 in presence of Lphn3 [PMID:27091502].","affinity_potency":[],"species_and_systems":"Purified mouse FLRT2, rat Unc5D and mouse Lphn3 domains (SPR, ITC, crystallography), HeLa/HEK293 cells, murine brain lysate pull-down [PMID:27091502].","localisation_and_range":"Cell-surface proteins acting in cis (FLRT2/Unc5D) and trans (Lphn3 on an opposing cell), so contact-dependent [PMID:27091502].","caveats":"Single paper (read as abstract plus excerpts). No absolute affinity in our evidence. UniProt notes FLRT2 (Q6UXZ4) and ADGRL3 (Q9HAR2) do not interact by themselves [DB:UniProt], which sits oddly with the paper's FLRT2-Lphn3 binding.","key_references":[{"PMID":"27091502","why":"Ternary FLRT2/Unc5D/Lphn3 structure, cooperativity, cis-switch of adhesion"}],"covers":["LR008010"]},"LR011214":{"pair":"GDF1 -> ACVR1C","headline":"Functional evidence in hepatocellular carcinoma cells that GDF1 acts through ALK7 (ACVR1C); indirect, no binding data.","interaction_type":"functional only","direction_and_effect":"In hepatocellular carcinoma cells, GDF1 functions through the ALK7-SMAD2/3 cascade; knocking down ALK7, but not ALK4 or ALK5, abolished the GDF1-enhanced cell migration, and recombinant GDF1 at 50 ng/ml increased SMAD2/3 phosphorylation time-dependently [PMID:34880251]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"Type II receptor or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human hepatocellular carcinoma cell lines and patient tissue; GDF1 overexpression and recombinant protein [PMID:34880251]. Receptor species are not otherwise stated.","localisation_and_range":"GDF1 is flagged secreted and described as a secreted protein [PMID:34880251] [flag].","caveats":"Evidence is from knockdown and pathway readouts, not binding, so direct GDF1-ALK7 engagement is inferred. Read as abstract plus excerpts. One paper was judged different_entity.","key_references":[{"PMID":"34880251","why":"ALK7 knockdown abolishes GDF1 effects in hepatocellular carcinoma"}],"covers":["LR011214"]},"LR010620":{"pair":"GDF1 -> BMPR2","headline":"Database-asserted only: GtoPdb lists an agonist action; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at BMPR2 [DB:GtoPdb]; no paper confirms it in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"No confirmed paper. One paper was abstract-insufficient. Affinity and species are not reported in our evidence.","key_references":[],"covers":["LR010620"]},"LR011223":{"pair":"GDF9 -> ACVR1B","headline":"GDF9 -> ACVR1B rests on a GtoPdb agonist record alone; six papers were abstract-insufficient.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records the interaction as Agonist, action Agonist, with no affinity units [DB:GtoPdb]. No curator-verified paper supports it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Support is a database assertion only. Six papers were judged abstract-insufficient, so none confirmed it.","key_references":[],"covers":["LR011223"]},"LR000711":{"pair":"GDNF -> GFRA2","headline":"Direct binding and Ret activation shown, but GFRA2 is a secondary GDNF receptor, preferring neurturin.","interaction_type":"direct binding","direction_and_effect":"GDNF can bind GFRalpha-2 and activate Ret in its presence [PMID:9407096]. TrnR2 (GFRA2) mediated GDNF signalling through Ret in vitro [PMID:9182803]. Reactome and BioGRID agree [DB:Reactome][DB:BioGRID].","molecular_requirements":"RET is needed as the signalling component [PMID:9407096][PMID:9182803]. GFRA2 is GPI-linked [PMID:9182803].","affinity_potency":[],"species_and_systems":"Transfected cells (NIH3T3-derived fibroblasts in [PMID:9182803]); curators record human ligand and receptor. Mouse pair is ortholog-inferred.","localisation_and_range":"GDNF is flagged secreted [flag]; GFRA2 is attached to the cell surface via GPI [PMID:9182803].","caveats":"Cells expressing GFRalpha-1 bind GDNF more efficiently than neurturin, and GFRalpha-2 prefers neurturin [PMID:9407096]. TrnR2-Ret fibroblasts are approximately 30-fold more sensitive to NTN than to GDNF [PMID:9182803]. No affinity values are in our evidence.","key_references":[{"PMID":"9407096","why":"GDNF binds GFRalpha-2; GFRalpha-1 is primary"},{"PMID":"9182803","why":"TrnR2-Ret mediates GDNF signalling, NTN-preferring"}],"covers":["LR000711","LR004195"]},"LR000720":{"pair":"GNRH1 -> GNRHR","headline":"GnRH I is a confirmed full agonist of the GnRH receptor, shown by binding and functional work in human and mouse systems.","interaction_type":"direct binding","direction_and_effect":"Agonist, stimulatory [flag]. Human GnRH receptor has higher affinity for cognate GnRH I than for GnRH II [PMID:17452338]. In mouse pituitary alpha T3-1 cells GnRH dose-dependently activated the receptor, abolished by a selective Galpha q inhibitor, confirming Galpha q coupling [PMID:26774084]. Murine receptor cloned by expression in Xenopus oocytes, with calcium responses to GnRH inhibited by antagonists [PMID:1328228]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"Receptor alone (single functional receptor) is sufficient in these systems; no co-receptor reported in our evidence.","affinity_potency":[{"value":"pIC50 8.6","assay":"binding (curator field; abstract reports higher affinity for GnRH I)","system":"human GnRH receptor","cite":"PMID:17452338"},{"value":"pEC50 7.8 \u00b1 0.06","assay":"label-free impedance","system":"mouse pituitary alpha T3-1 cells, endogenous receptor","cite":"PMID:26774084"},{"value":"pIC50 8.3","assay":"expression cloning, calcium response (curator field)","system":"murine receptor, Xenopus oocytes","cite":"PMID:1328228"}],"species_and_systems":"Human experiments [PMID:17452338]; mouse cells and oocytes [PMID:26774084][PMID:1328228]. The mouse pair is ortholog-inferred, not independently tested.","localisation_and_range":"GnRH I is annotated as secreted and the receptor as transmembrane [flag], so signalling is paracrine/endocrine.","caveats":"Two of three shown papers were read as abstracts only. GtoPdb lists pKi 7.3-8.4 [DB:GtoPdb]. Five confirmed papers exist; three are shown.","key_references":[{"PMID":"17452338","why":"Human receptor, GnRH I higher affinity than GnRH II"},{"PMID":"26774084","why":"GnRH potency in native mouse alpha T3-1 cells, Galpha q coupling"},{"PMID":"1328228","why":"Murine receptor cloning and GnRH response"}],"covers":["LR000720","LR004203"]},"LR004203":{"pair":"GNRH1 -> GNRHR","headline":"GnRH I is a confirmed full agonist of the GnRH receptor, shown by binding and functional work in human and mouse systems.","interaction_type":"direct binding","direction_and_effect":"Agonist, stimulatory [flag]. Human GnRH receptor has higher affinity for cognate GnRH I than for GnRH II [PMID:17452338]. In mouse pituitary alpha T3-1 cells GnRH dose-dependently activated the receptor, abolished by a selective Galpha q inhibitor, confirming Galpha q coupling [PMID:26774084]. Murine receptor cloned by expression in Xenopus oocytes, with calcium responses to GnRH inhibited by antagonists [PMID:1328228]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"Receptor alone (single functional receptor) is sufficient in these systems; no co-receptor reported in our evidence.","affinity_potency":[{"value":"pIC50 8.6","assay":"binding (curator field; abstract reports higher affinity for GnRH I)","system":"human GnRH receptor","cite":"PMID:17452338"},{"value":"pEC50 7.8 \u00b1 0.06","assay":"label-free impedance","system":"mouse pituitary alpha T3-1 cells, endogenous receptor","cite":"PMID:26774084"},{"value":"pIC50 8.3","assay":"expression cloning, calcium response (curator field)","system":"murine receptor, Xenopus oocytes","cite":"PMID:1328228"}],"species_and_systems":"Human experiments [PMID:17452338]; mouse cells and oocytes [PMID:26774084][PMID:1328228]. The mouse pair is ortholog-inferred, not independently tested.","localisation_and_range":"GnRH I is annotated as secreted and the receptor as transmembrane [flag], so signalling is paracrine/endocrine.","caveats":"Two of three shown papers were read as abstracts only. GtoPdb lists pKi 7.3-8.4 [DB:GtoPdb]. Five confirmed papers exist; three are shown.","key_references":[{"PMID":"17452338","why":"Human receptor, GnRH I higher affinity than GnRH II"},{"PMID":"26774084","why":"GnRH potency in native mouse alpha T3-1 cells, Galpha q coupling"},{"PMID":"1328228","why":"Murine receptor cloning and GnRH response"}],"covers":["LR000720","LR004203"]},"LR002700":{"pair":"GPC4 -> PTPRS","headline":"Database-asserted only: BioGRID lists reconstituted complex, co-localisation and affinity-capture records from one paper; no curated paper confirms it.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID cites one study [PMID:25624497]; species and cells not reported in our evidence. Pair is ortholog-inferred for human and mouse.","localisation_and_range":"Both partners are annotated secreted and transmembrane-capable [flag].","caveats":"No paper in our evidence supports this pair; it rests on database records alone. Two curated judgements were 'abstract_insufficient'. All four BioGRID records come from one paper.","key_references":[{"PMID":"25624497","why":"Source of the BioGRID records; not curated by us"}],"covers":["LR002700","LR005965"]},"LR004212":{"pair":"GUCA2A -> GUCY2C","headline":"Guanylin activates guanylate cyclase C; supported by original purification and bioassay and by human cell work.","interaction_type":"direct binding","direction_and_effect":"Guanylin stimulates cGMP in T84 cells and displaces heat-stable enterotoxin binding, so it is proposed to act through the same receptor-binding region [PMID:1346555]. In human kidney IHKE-1 cells, guanylin (10-100 nM) depolarised membrane voltage and raised cGMP; GC-C is 'probably the receptor' [PMID:11889121].","molecular_requirements":"Guanylin required disulfide bond formation (oxidation) for bioactivity [PMID:1346555]. Reactome describes a GUCY2C trimer complex with GUCA2A/B [DB:Reactome].","affinity_potency":[],"species_and_systems":"Guanylin was purified from rat jejunum and tested on human T84 cells [PMID:1346555]; human IHKE-1 cells [PMID:11889121]. Mouse pair is ortholog-inferred.","localisation_and_range":"GUCA2A is flagged secreted [flag].","caveats":"Receptor identity in IHKE-1 is inferred from cGMP and GC-C expression, with no knockout; the authors hedge. Both papers read as abstract only.","key_references":[{"PMID":"1346555","why":"Guanylin purification and activation of intestinal cyclase"},{"PMID":"11889121","why":"Guanylin effects in human proximal tubule cells"}],"covers":["LR000730","LR004212"]},"LR010800":{"pair":"HBEGF -> ERBB2:ERBB4","headline":"Binding evidence supports ERBB4 only; HER2 alone did not bind HB-EGF.","interaction_type":"direct binding","direction_and_effect":"HB-EGF bound NIH 3T3 cells overexpressing HER4 but not HER2 alone [PMID:9135143].","molecular_requirements":"Binding to HER4 was independent of HER1 [PMID:9135143]. Need for ERBB2 as partner is not reported in our evidence. IntAct records cross-linking with ERBB4 [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human NIH 3T3 transfectants [PMID:9135143].","localisation_and_range":"Secreted/transmembrane flags [flag].","caveats":"Abstract only. No dimer data. Reactome and GtoPdb records are for ERBB4 alone [DB:Reactome R-HSA-1236398][DB:GtoPdb].","key_references":[{"PMID":"9135143","why":"HB-EGF binds HER4 and not HER2 alone"}],"covers":["LR010800"]},"LR004221":{"pair":"HCRT -> HCRTR1","headline":"Orexin-A (HCRT) is a well-supported agonist of OX1 (HCRTR1): binding and many functional assays, mostly human receptor in CHO cells.","interaction_type":"direct binding","direction_and_effect":"Orexin-A activates OX1: it raises [Ca2+]i in CHO cells expressing human OX1 [PMID:10498827][PMID:11250867], and the original de-orphanization paper reports that the orexin peptides bind and activate the receptors [PMID:9491897]. Orexin-A is about five-fold higher affinity than orexin-B in whole-cell competition [PMID:14691055]. GtoPdb lists it as a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor, no co-receptor reported in our evidence. Intact disulfide bonds of orexin-A are required for OX1 activation, and truncated or alanine-substituted analogues lose potency [PMID:11162621][PMID:12606634]. HCRT encodes both orexin-A and orexin-B; this pair concerns orexin-A. Coupling reported to Ca2+ influx, phospholipase C/D and G-protein classes including pertussis-toxin-insensitive ones [PMID:17115071][PMID:18488139][PMID:12702704].","affinity_potency":[{"value":"Ki 318 nM","assay":"whole-cell radioligand competition vs [3H]-SB-674042","system":"human OX1","cite":"PMID:14691055"},{"value":"EC50 0.068 nM","assay":"calcium mobilisation","system":"CHO-K1 cells expressing OX1R","cite":"PMID:11162621"},{"value":"pEC50 8.38","assay":"Ca2+ mobilisation (Fluo-3AM)","system":"CHO cells expressing human OX1","cite":"PMID:11250867"},{"value":"pEC50 8.03","assay":"FLIPR calcium","system":"CHO-OX1","cite":"PMID:10498827"}],"species_and_systems":"Experiments are almost all with recombinant human OX1 in CHO, Neuro-2a/PC12 or HEK cells [PMID:12208495][PMID:12702704]; the 1998 discovery paper localised orexin in rat brain and tested peptides in rats [PMID:9491897]. The mouse pair is ortholog-inferred, not experimentally shown here.","localisation_and_range":"Ligand flagged secreted and receptor transmembrane [flag], consistent with paracrine or neuronal signalling; not otherwise reported in our evidence.","caveats":"The two affinity readings differ widely (Ki 318 nM in one radioligand format versus sub-nanomolar to low-nanomolar EC50 elsewhere); the curators note this is assay-format dependent [PMID:14691055]. All papers were read as abstracts only.","key_references":[{"PMID":"9491897","why":"Original identification of orexin peptides as ligands of the two receptors"},{"PMID":"11162621","why":"Orexin-A EC50 at OX1R and disulfide requirement"},{"PMID":"14691055","why":"Direct competition binding, Ki for orexin-A"}],"covers":["LR000739","LR004221"]},"LR004230":{"pair":"Hrg -> Fcgr1","headline":"Histidine-rich glycoprotein blocks IgG binding to FcgammaRI on THP1 cells; one abstract-level paper, binding not directly measured.","interaction_type":"functional only","direction_and_effect":"HRG competitively blocks monomeric IgG binding to FcgammaRI on THP1 monocytic cells, with concentration- and Zn2+-dependent modulation of IgG and immune-complex binding [PMID:10421785]. The curator records no activating effect, so HRG acts as an inhibitor of IgG binding rather than a classical agonist.","molecular_requirements":"Zn2+ dependence is reported [PMID:10421785]; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human THP1 cells and human proteins [PMID:10421785]. This mouse entry has no mouse experiments in our evidence.","localisation_and_range":"HRG is flagged as secreted [flag]; plasma protein acting on monocytes [PMID:10421785].","caveats":"Abstract-only reading; no affinity reported, and interaction is inferred from competition with IgG.","key_references":[{"PMID":"10421785","why":"HRG blocks monomeric IgG binding to FcgammaRI on THP1 cells"}],"covers":["LR004230"]},"LR006003":{"pair":"HSPG2 -> DAG1","headline":"Perlecan is a dystroglycan ligand at nodes of Ranvier (full text read), and Reactome records HSPG2 binding alpha-dystroglycan; no affinity.","interaction_type":"functional only","direction_and_effect":"Dystroglycan is required for perlecan to accumulate at peripheral nodes of Ranvier; perlecan then binds gliomedin and enhances clustering of node components [PMID:25646087]. Perlecan was absent from most nodes lacking dystroglycan (4% and 6% of nodes perlecan-positive vs 68% and 87% flanking paranodes in wild type) [PMID:25646087]. Reactome records HSPG2 binding alpha-dystroglycan [DB:Reactome R-HSA-2396395].","molecular_requirements":"Dystroglycan is an extracellular matrix receptor; Reactome lists a Dystroglycan:AGRN:HSPG2 complex [DB:Reactome R-HSA-2426244]. Which dystroglycan chain binds is not reported in our evidence in the paper excerpts.","affinity_potency":[],"species_and_systems":"In vivo mouse nerve (dystroglycan-deficient and perlecan-mutant mice) per excerpts; curators record human for both partners [PMID:25646087]. Mouse and human pairs are ortholog-inferred.","localisation_and_range":"DAG1 is flagged secreted and transmembrane [flag]; perlecan localises to the nodal gap matrix [PMID:25646087]. Matrix-bound, juxtacrine range.","caveats":"The paper shows dependence of perlecan localisation on dystroglycan, not a direct binding measurement; absence of perlecan alone did not impair Na+ channel clustering [PMID:25646087]. Direct binding rests on Reactome [DB:Reactome R-HSA-2396395].","key_references":[{"PMID":"25646087","why":"Dystroglycan needed for perlecan localisation at nodes of Ranvier"}],"covers":["LR002756","LR006003"]},"LR000801":{"pair":"ICAM4 -> ITGB2","headline":"Well supported: three human studies show beta2 integrins (LFA-1, Mac-1, CD11c/CD18) binding ICAM-4.","interaction_type":"direct binding","direction_and_effect":"alphaLbeta2 and alphaMbeta2 bind ICAM-4-Fc specifically and dose dependently [PMID:15355350]; CD11c/CD18 binds ICAM-4, curated as agonist, and antibodies inhibit erythrophagocytosis [PMID:16985175]; antibodies to CD11a, CD11b or CD18 block L-cell adhesion to ICAM-4-Fc [PMID:10846180].","molecular_requirements":"beta2 pairs with different alpha chains (alphaL, alphaM, alphaX), each with partly different ICAM-4 binding sites: LFA-1 uses domain 1, Mac-1 domains 1 and 2, CD11c/CD18 both domains [PMID:10846180, PMID:16985175]. Evidence is for heterodimers, not beta2 alone.","affinity_potency":[],"species_and_systems":"Human proteins and cells [PMID:15355350, PMID:16985175, PMID:10846180]; mouse pair ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"All three papers abstract only; seven rows judged, one abstract-insufficient. Affinity not reported.","key_references":[{"PMID":"15355350","why":"alphaLbeta2 and alphaMbeta2 binding to ICAM-4-Fc"},{"PMID":"16985175","why":"CD11c/CD18 as ICAM-4 receptor"},{"PMID":"10846180","why":"LFA-1 and Mac-1 binding sites"}],"covers":["LR000801","LR004255"]},"LR000810":{"pair":"IFNA16 -> IFNAR2","headline":"IFNA16 binds IFNAR2 on class-wide evidence from one abstract; IFNAR2 is the high-affinity chain.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR2 at 0.4-5 nM, except IFN-alpha1 at 220 nM [PMID:21856167]. GtoPdb lists IFNA16 as an agonist at IFNAR2 [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tighter-binding chain; IFNAR1 binds at 0.5-5 \u03bcM [PMID:21856167]. Chain-only evidence.","affinity_potency":[{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single paper, abstract only, no subtype-specific value for IFNA16. Binding is to the isolated chain.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR000810"]},"LR005202":{"pair":"IFNK -> IFNAR2","headline":"Recombinant human IFN-kappa binds IFNAR2 only weakly; this explains its low cellular potency.","interaction_type":"direct binding","direction_and_effect":"IFN-kappa is an agonist; GtoPdb lists Agonist [DB:GtoPdb]. Cellular potency was about 1000-fold lower than IFNalpha2 and IFNomega, consistent with weak affinity for the IFNAR2 chain [PMID:30171073].","molecular_requirements":"IFN-kappa signals through the IFNAR1/IFNAR2 complex; its IFNAR2 affinity is reduced while its IFNAR1 affinity is similar to other IFNs [PMID:30171073].","affinity_potency":[],"species_and_systems":"Recombinant human IFN-kappa, protein affinity characterisation [PMID:30171073]. Mouse pair is projected from human (ortholog inferred).","localisation_and_range":"IFNK is flagged secreted and non-transmembrane [flag].","caveats":"Abstract-only read; no numeric affinity in our evidence. The weak binding is measurable but low.","key_references":[{"PMID":"30171073","why":"IFN-kappa shows weak IFNAR2 affinity and low potency"}],"covers":["LR001854","LR005202"]},"LR006012":{"pair":"IGF1 -> ITGAV","headline":"Integrin alphavbeta3 directly binds IGF1 in one verified study; ITGAV is the alpha chain.","interaction_type":"direct binding","direction_and_effect":"Integrin alphavbeta3 specifically and directly bound IGF-1 in cell adhesion, ELISA-type binding and surface plasmon resonance assays. IGF-1 mediated co-precipitation of alphavbeta3 and IGF1R, giving a ternary complex [PMID:19578119].","molecular_requirements":"The R36E/R37E IGF-1 mutant (C-domain) had reduced integrin binding and still bound IGF1R, but failed to drive IGF1R phosphorylation, AKT and ERK1/2 activation or proliferation [PMID:19578119]. The heterodimer was tested, not ITGAV alone.","affinity_potency":[],"species_and_systems":"Binding assays were run with alphavbeta3; proliferation was tested in Chinese hamster ovary cells [PMID:19578119]. The mouse pair is ortholog-inferred.","localisation_and_range":"IGF1 is flagged secreted [flag].","caveats":"Abstract-only read. Evidence is for the alphavbeta3 heterodimer; no affinity value is reported in our evidence.","key_references":[{"PMID":"19578119","why":"Direct alphavbeta3-IGF-1 binding and ternary complex"}],"covers":["LR002766","LR006012"]},"LR006021":{"pair":"IGFBP5 -> CAV1","headline":"Abstract and full text show IGFBP-5 co-precipitates with caveolin-1 in human lung fibroblasts; a trafficking interaction rather than classical signalling.","interaction_type":"direct binding","direction_and_effect":"IGFBP-5 localized to lipid rafts and bound Cav-1; Cav-1 was needed for IGFBP-5 internalization and nuclear trafficking, and Cav-1 scaffolding peptide increased IGFBP-5 uptake [PMID:20345844]. UniProt agrees the interaction allows trafficking to the nucleus [DB:UniProt].","molecular_requirements":"Not reported beyond Cav-1 itself.","affinity_potency":[],"species_and_systems":"Human lung fibroblasts (co-precipitation with anti-Cav-1 antibody) and Cav-1-null mouse fibroblasts for the loss-of-function side [PMID:20345844].","localisation_and_range":"IGFBP5 is annotated as secreted [flag]. Cav-1 sits in lipid rafts and the paper reports nuclear Cav-1 [PMID:20345844]; the curator frames Cav-1 as an internalization receptor.","caveats":"Evidence is co-immunoprecipitation from cell lysates, which does not show direct binding. Cav-1 is an intracellular scaffold, so this is unlikely to be a classical extracellular ligand-receptor pair for cell-cell communication scoring. No affinity.","key_references":[{"PMID":"20345844","why":"IGFBP-5 binds Cav-1; Cav-1 needed for uptake and nuclear trafficking"}],"covers":["LR002775","LR006021"]},"LR006030":{"pair":"IL17D -> CD93","headline":"IL-17D reportedly binds CD93 on ILC3s, found by protein purification and supported by mouse knockout data; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Receptor role: IL-17D bound CD93 rather than canonical IL-17 receptors [PMID:33852831]. Mice lacking Cd93 in ILC3s had impaired IL-22 production and aggravated colitis, consistent with an IL-17D-CD93 axis [PMID:33852831].","molecular_requirements":"Not reported in our evidence beyond CD93 being a glycoprotein on mature ILC3s [PMID:33852831].","affinity_potency":[],"species_and_systems":"Mouse knockout and colitis work (Il17d-/-, Cd93 in ILC3s); curators recorded the binding species as unspecified [PMID:33852831]. Human pair is ortholog-inferred.","localisation_and_range":"CD93 is annotated as a transmembrane receptor and not secreted [flag]; IL-17D annotated as secreted [flag]. Cell-surface on ILC3s is described in the paper.","caveats":"Single abstract-only paper; no affinity or binding assay details beyond 'protein purification studies'.","key_references":[{"PMID":"33852831","why":"IL-17D binds CD93 on ILC3s; Cd93 loss in ILC3s phenocopies"}],"covers":["LR002787","LR006030"]},"LR004302":{"pair":"IL17F -> IL17RA","headline":"IL-17F binds IL-17RA with lower affinity than IL-17A, within an IL-17RA/IL-17RC receptor; evidence is one abstract-only SPR paper.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17F bound IL-17RA with a different affinity from IL-17A and from the heterodimer in SPR; IL-17F activity was inhibited by soluble IL-17RC, not IL-17RA [PMID:18684971]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"IL-17RA works in an IL-17RA/IL-17RC complex [PMID:18684971]. UniProt notes IL17RA and IL17RC chains cannot distinguish IL17A and IL17F [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and cells [PMID:18684971]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-17F annotated as secreted and non-transmembrane [flag]; IL-17RA as a receptor [flag].","caveats":"Abstract-only; no affinity values are given. Soluble IL-17RC rather than IL-17RA blocked IL-17F, suggesting IL-17RA is not the main binder [PMID:18684971].","key_references":[{"PMID":"18684971","why":"SPR comparison of IL-17A, F and A/F to IL-17RA and IL-17RC"}],"covers":["LR000872","LR004302"]},"LR004311":{"pair":"IL1B -> IL1R1","headline":"IL-1beta binds IL1R1; structural and genetic evidence (human crystal structure, mouse knockout), IL1RAP raises affinity.","interaction_type":"direct binding","direction_and_effect":"IL-1beta acts as an agonist at type I IL-1R: a 2.5 A crystal structure shows binding with 1:1 stoichiometry [PMID:9062193]; all IL-1 agonists bound AcP-deficient cells through IL1R1 but did not activate NF-kappaB or AP-1 [PMID:9820540].","molecular_requirements":"IL1RAP is needed for signalling, and murine IL-1beta affinity was reduced by 70-fold without AcP [PMID:9820540]. The structure uses the receptor extracellular domain (s-IL1R) alone [PMID:9062193].","affinity_potency":[],"species_and_systems":"Human ligand and receptor ectodomain in the structure [PMID:9062193]; mouse AcP-deficient fibroblasts and mice [PMID:9820540].","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Both papers abstract only. No Kd is reported in our evidence. One further paper is pending.","key_references":[{"PMID":"9062193","why":"Crystal structure of IL-1beta bound to IL1R1 ectodomain"},{"PMID":"9820540","why":"IL1RAP effect on IL-1beta affinity and signalling"}],"covers":["LR000881","LR004311"]},"LR004320":{"pair":"IL21 -> IL21R","headline":"IL-21 binds IL-21R independently of the common gamma chain; human cell evidence from one abstract plus database records.","interaction_type":"direct binding","direction_and_effect":"IL-21 binds IL-21R on gamma(c)-deficient cells but cannot signal there; signalling is restored when gamma(c) is transfected [PMID:11418623]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"IL-21R alone is enough for ligand binding; the common gamma chain is required for signalling (JAK1, JAK3, STAT1, STAT3 activation) [PMID:11418623]. A structure with chains of both partners exists [DB:PDB 8ENT].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in ED40515(-) and gamma(c)-transfected EDgamma-16 cells [PMID:11418623]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-21 is flagged secreted [flag].","caveats":"Single paper, read as abstract only. A CCC tool scoring IL21R alone would miss the gamma(c) requirement.","key_references":[{"PMID":"11418623","why":"IL-21 binds IL-21R without gamma(c); gamma(c) needed for signalling"}],"covers":["LR000890","LR004320"]},"LR000900":{"pair":"IL25 -> IL17RB","headline":"IL-25 is a ligand of IL17RB, supported by database records and one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"IL-17E was identified as a ligand for EVI27/IL-17BR (IL-17Rh1) and induced NF-kappaB activation and IL-8 production [PMID:11058597]. GtoPdb lists IL-25 as an agonist of IL17RB [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence for this single-chain pair beyond the Reactome complex IL25 dimer:IL17RA:IL17RB [DB:Reactome]; the other chain is not tested in this dossier.","affinity_potency":[],"species_and_systems":"Human experiment per the curator record [PMID:11058597]. The mouse interaction is projected from human evidence (ortholog-inferred). BioGRID records a reconstituted complex [DB:BioGRID]; PDB 7UWJ, 7UWK and 7UWL contain both partner chains [DB:PDB 7UWJ].","localisation_and_range":"IL-25 is flagged secreted and non-transmembrane [flag].","caveats":"The only verified paper was read as abstract only, and the abstract asserts ligand status without naming a binding assay or affinity [PMID:11058597]. No affinity is reported in our evidence.","key_references":[{"PMID":"11058597","why":"Identifies IL-17E (IL-25) as ligand for IL-17BR; NF-kappaB and IL-8 readouts."}],"covers":["LR000900","LR004330"]},"LR005211":{"pair":"INHBA -> ACVR1C","headline":"Papers show activin AB and B, not activin A, signal through ACVR1C (ALK7); this pair is weakly supported.","interaction_type":"conflicting","direction_and_effect":"Activin AB and activin B are ligands for ALK7; the combination of ActRIIA and ALK7 is preferred by activin AB and activin B but not by activin A [PMID:15196700]. GtoPdb lists agonist for INHBA-ACVR1C [DB:GtoPdb].","molecular_requirements":"ALK7 works with ActRIIA in reconstitution [PMID:15196700]. UniProt names ACVR1C as a type I partner for INHBA [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse receptor reconstitution and MIN6 beta cell line; human pair is the source and the mouse pair is ortholog-projected [PMID:15196700].","localisation_and_range":"Ligand secreted flag [flag].","caveats":"The paper's abstract says ALK7 is not preferred by activin A, which argues against this pair; read as abstract only. Both confirmed rows come from the same paper.","key_references":[{"PMID":"15196700","why":"Activin AB and B use ALK7; activin A uses ALK4."}],"covers":["LR001866","LR005211"]},"LR004401":{"pair":"LAMA1 -> ITGB1","headline":"Conflicting: LAMA1 fragment binds alpha1/alpha2beta1 integrins, but one full-text paper judged pair absent.","interaction_type":"conflicting","direction_and_effect":"Laminin alpha1 fragment VI/V bound purified alpha1beta1 and alpha2beta1 integrins [PMID:9688542]; alpha7beta1 mediates myoblast migration on laminin-1 [PMID:11278916]. Another paper was judged pair absent [PMID:16413178].","molecular_requirements":"ITGB1 acts within alpha-beta heterodimers (alpha1, alpha2, alpha7 here); the LN module (domain VI) carries the binding site [PMID:9688542].","affinity_potency":[],"species_and_systems":"Recombinant fragments and purified integrins, species unspecified [PMID:9688542]; human transfected myoblasts [PMID:11278916]; human recombinant integrins [PMID:16413178]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and receptor flagged not secreted [flag]; matrix ligand.","caveats":"The curator noted no LAMA1-containing laminin showed detectable binding to ITGB1-containing integrins in Table 1 (ND everywhere) [PMID:16413178]. Two confirmed papers are abstract-only and the pair is a chain of heterodimers and trimers.","key_references":[{"PMID":"9688542","why":"LN module binds alpha1beta1 and alpha2beta1"},{"PMID":"11278916","why":"Alpha7beta1-mediated migration on laminin-1"},{"PMID":"16413178","why":"Table 1 negative verdict"}],"covers":["LR000980","LR004401"]},"LR011151":{"pair":"LAMA3 -> CD44","headline":"Only pending literature and one IntAct co-IP record; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence (labelled Stimulatory [flag]).","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Only an IntAct association by anti-tag coimmunoprecipitation record is available [DB:IntAct EBI-54533805].","localisation_and_range":"Ligand flagged secreted; CD44 flagged transmembrane [flag].","caveats":"Three papers are still pending curation; no verified evidence. Species of the IntAct experiment not given.","key_references":[],"covers":["LR011151"]},"LR004410":{"pair":"LAMA4 -> ITGA6","headline":"Antibody-blocking adhesion data implicate alpha6 integrin in cell adhesion to laminin-8 and LAMA4; functional only.","interaction_type":"functional only","direction_and_effect":"Platelet adhesion to purified platelet laminin-8 (alpha4beta1gamma1) was largely inhibited by antibodies to beta1 and alpha6 integrin chains [PMID:10585296]. Endothelial adhesion to the alpha4 G domain was blocked by combined anti-alpha3 and alpha6 antibodies [PMID:12454288]. Stimulatory per interaction record [flag].","molecular_requirements":"alpha6beta1 is implicated as a pair; alpha3 and alpha6 act together in the endothelial assay [PMID:10585296][PMID:12454288].","affinity_potency":[],"species_and_systems":"Human platelets and endothelial cells [PMID:10585296][PMID:12454288]","localisation_and_range":"LAMA4 flagged secreted [flag]; laminin-8 is released by activated platelets [PMID:10585296].","caveats":"Antibody blocking is indirect; Both papers were read from abstracts only. In the 12454288 abstract, alpha6beta1 is said to function cooperatively, not to bind with measured high affinity. One paper was review-only.","key_references":[{"PMID":"10585296","why":"Platelet adhesion to laminin-8 blocked by anti-alpha6"},{"PMID":"12454288","why":"alpha3/alpha6 antibodies block adhesion to alpha4 G domain"}],"covers":["LR000991","LR004410"]},"LR011043":{"pair":"LAMA5 -> ITGA6:ITGB1","headline":"Complex row for laminin alpha5 and integrin alpha6beta1; supported only by a PDB record.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of O15230 and a chain of P23229 [DB:PDB 7CEC].","molecular_requirements":"Receptor is the ITGA6:ITGB1 heterodimer per the entity record; ligand chain requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGA6:ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"No papers judged for this row (one abstract_insufficient). Evidence is one structure record.","key_references":[],"covers":["LR011043"]},"LR011124":{"pair":"LAMA5 -> ITGA6:ITGB4","headline":"Complex row for laminin alpha5 and integrin alpha6beta4; only a PDB record, no judged paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of O15230 and a chain of P23229 [DB:PDB 7CEC].","molecular_requirements":"Receptor is the ITGA6:ITGB4 heterodimer per the entity record; the PDB chains listed are LAMA5 and ITGA6 only, so ITGB4 is not shown there [DB:PDB 7CEC].","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMA5 is flagged secreted [flag]; the receptor complex is flagged transmembrane but not as a receptor [flag]. Range beyond the flags is not reported in our evidence.","caveats":"No papers judged (three abstract_insufficient). The entity flag is_receptor is 0 for the complex while both members are flagged receptors. Support is one structure record.","key_references":[],"covers":["LR011124"]},"LR006102":{"pair":"LAMB2 -> ITGA7","headline":"LAMB2 (in laminin-211/221) binds integrin alpha7 with sub-nanomolar Kd in recombinant assays; assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-211/221, which contains LAMB2, bound the recombinant integrin alpha7 beta1 ectodomain in solid-phase binding [PMID:16413178]. Direction: laminin ligand to integrin receptor; effect not reported beyond binding.","molecular_requirements":"The tested binder is the alpha7X1beta1 heterodimer and the ligand is the assembled laminin heterotrimer; single chains were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 0.64 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha7X1beta1 vs laminin-211/221","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. Only one paper supports the pair.","key_references":[{"PMID":"16413178","why":"Kd for alpha7X1beta1 vs laminin-211/221, full text"}],"covers":["LR002868","LR006102"]},"LR011007":{"pair":"LAMB3 -> ITGA2:ITGB1","headline":"LAMB3 with ITGA2:ITGB1 rests on a Reactome binding record for laminin-332; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Reactome describes integrin alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626]; effect is not otherwise reported.","molecular_requirements":"The Reactome complex is alpha2beta1, matching this receptor complex; the ligand is laminin-332, so LAMB3 acts with its partner chains.","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Five papers were judged abstract_insufficient.","key_references":[],"covers":["LR011007"]},"LR001008":{"pair":"LAMB3 -> ITGB4","headline":"LAMB3 (in laminin-332) binds integrin alpha6beta4 at Kd 12 nM; assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-332, which contains LAMB3, bound recombinant alpha6beta4 in solid-phase assays [PMID:16413178]. Annotated effect is Stimulatory [flag]. Direction: laminin to integrin.","molecular_requirements":"Binder tested is the alpha6beta4 heterodimer, ligand the assembled heterotrimer; ITGB4 alone and LAMB3 alone were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 12 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha6beta4 vs laminin-332","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. One abstract_insufficient paper is not shown.","key_references":[{"PMID":"16413178","why":"Kd of alpha6beta4 for laminin-332"}],"covers":["LR001008","LR004426"]},"LR001017":{"pair":"LAMC2 -> ITGB4","headline":"Recombinant alpha6beta4 binds laminin-332 (contains LAMC2) with Kd 12 nM; ITGB4 is a chain-level proxy.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha6beta4 showed clear specificity for laminin-332 [PMID:16413178]. Recorded effect: stimulatory [flag].","molecular_requirements":"The assembled laminin-332 heterotrimer and the alpha6beta4 heterodimer were tested; individual chains were not [PMID:16413178].","affinity_potency":[{"value":"Kd 12 nM","assay":"solid-phase saturation binding of recombinant integrin to laminin-332","system":"human recombinant alpha6beta4","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]. Mouse pair is ortholog-projected.","localisation_and_range":"LAMC2 flagged secreted [flag].","caveats":"Chain-level assignment inferred; one paper in the dossier.","key_references":[{"PMID":"16413178","why":"Recombinant alpha6beta4 binding to laminin-332"}],"covers":["LR001017","LR004435"]},"LR006111":{"pair":"LEFTY1 -> ACVR2B","headline":"Lefty is proposed to antagonise Nodal by competing for ActRIIA/ActRIIB; evidence is functional, from one abstract.","interaction_type":"functional only","direction_and_effect":"Lefty-induced inhibition of Nodal signalling was rescued by excess ActRIIA or ActRIIB, suggesting competitive binding as an antagonist [PMID:11952836].","molecular_requirements":"ActRIIA or ActRIIB can serve as the common receptor; the paper does not say which is required [PMID:11952836].","affinity_potency":[],"species_and_systems":"Frog animal caps and mouse genetics (lefty2 with ActRIIB) [PMID:11952836]. Human pair is ortholog-projected.","localisation_and_range":"LEFTY1 flagged secreted [flag].","caveats":"Abstract only; competition inferred, not measured; Lefty1 versus Lefty2 not distinguished.","key_references":[{"PMID":"11952836","why":"Rescue of Lefty inhibition by ActRIIB"}],"covers":["LR002877","LR006111"]},"LR005220":{"pair":"LGALS1 -> ITGB1","headline":"Direct galectin-1 binding to beta1 integrin shown by cross-linking and immunoprecipitation in smooth muscle cells.","interaction_type":"direct binding","direction_and_effect":"125I-galectin-1 cross-linked to cell surface proteins immunoprecipitated with beta1 integrin; galectin-1 modulated SMC attachment, transiently raised active beta1 integrin and tyrosine phosphorylation of two proteins, one coinciding with FAK, suggesting outside-in signalling [PMID:14550305].","molecular_requirements":"Beta1 subunit identified; alpha partner not reported in our evidence. Binding depended on beta-galactoside, as attachment effects were beta-galactoside-dependent [PMID:14550305].","affinity_potency":[],"species_and_systems":"Human vascular smooth muscle cells (curator: human); mouse pair ortholog-inferred [PMID:14550305].","localisation_and_range":"Galectin-1 flagged secreted; ITGB1 flagged receptor, not secreted [flag]. Acts on SMC surface [PMID:14550305].","caveats":"Abstract-only read; FAK link is a coincidence in size, not proven. No affinity data.","key_references":[{"PMID":"14550305","why":"Cross-linking/IP shows direct galectin-1 binding to beta1 integrin"}],"covers":["LR001878","LR005220"]},"LR006120":{"pair":"LGALS3 -> MCAM","headline":"CD146/MCAM is the major galectin-3 binder on endothelial cells and mediates galectin-3-induced cytokine secretion.","interaction_type":"direct binding","direction_and_effect":"Galectin-3 bound N-linked glycans on CD146, induced CD146 dimerisation and AKT signalling; CD146 siRNA completely abolished galectin-3-induced IL-6 and G-CSF secretion [PMID:28364041]. Effect is agonist.","molecular_requirements":"N-glycans on CD146 are required for binding; dimerisation of CD146 follows [PMID:28364041].","affinity_potency":[],"species_and_systems":"Human vascular endothelial cells [PMID:28364041]. BioGRID lists Affinity Capture-Western, Reconstituted Complex and Co-purification [DB:BioGRID]. Mouse pair ortholog-inferred.","localisation_and_range":"Circulating galectin-3 (up to 30-fold higher in cancer patients) acts on endothelial cells [PMID:28364041]; MCAM flagged not transmembrane in the annotation [flag].","caveats":"Abstract-only read. Galectin-3 co-purified three other glycoproteins, so CD146 is not the only partner. The MCAM transmembrane flag looks inconsistent with a cell-surface adhesion molecule.","key_references":[{"PMID":"28364041","why":"CD146 is the functional galectin-3 receptor on endothelium"}],"covers":["LR002886","LR006120"]},"LR001026":{"pair":"LIF -> LIFR","headline":"LIF binds LIFR, with mutagenesis mapping its binding site; four confirming papers and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"LIF binds LIFR; alanine-scanning of the Ig-like domain maps a LIF binding site at its carboxyl terminus, mainly Phe-328 [PMID:12601009]. LIF signalling is unaffected by deleting the LIFR N-terminal cytokine-binding domain [PMID:16051226]. GtoPdb records an agonist [DB:GtoPdb].","molecular_requirements":"LIFR acts with IL6ST/gp130 [DB:UniProt]. Unlike CNTF, LIF and OSM signalling did not need the LIFR N-terminal cytokine-binding domain [PMID:16051226].","affinity_potency":[],"species_and_systems":"Human cells with human LIFR mutants [PMID:12601009][PMID:16051226]; both mouse and human pairs are listed.","localisation_and_range":"LIF is flagged secreted [flag].","caveats":"Both papers read as abstracts only; no numeric affinity reported. Two more confirmed papers are not shown in the dossier.","key_references":[{"PMID":"12601009","why":"LIF binding site on LIFR mapped to Phe-328"},{"PMID":"16051226","why":"LIF signalling does not need LIFR N-terminal CBD"}],"covers":["LR001026","LR004443"]},"LR008889":{"pair":"LIN7C -> KCNJ4","headline":"Database records only (BioGRID affinity capture, IntAct holdup); no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists two affinity-capture-Western records and IntAct a holdup assay [DB:BioGRID][DB:IntAct].","localisation_and_range":"No localisation flags in dossier.","caveats":"Database support only; the one paper judged was review-only.","key_references":[],"covers":["LR008889"]},"LR001035":{"pair":"LRPAP1 -> LDLR","headline":"RAP (LRPAP1) binds LDL receptors with a KD of 250 nM and inhibits LDL receptor-mediated lipoprotein uptake; structure and database records support it.","interaction_type":"direct binding","direction_and_effect":"RAP inhibited LDL receptor-mediated binding and catabolism of LDL and VLDL in human foreskin fibroblasts [PMID:7822276]. It acts as an inhibitor of ligand binding, not a signalling agonist [PMID:7822276].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"KD 250 nM","assay":"solid-phase binding to partially purified LDL receptors","system":"human fibroblast-derived receptor","cite":"PMID:7822276"},{"value":"KI 60 nM","assay":"inhibition of 125I-LDL binding at 4 degrees C","system":"human foreskin fibroblasts","cite":"PMID:7822276"}],"species_and_systems":"Normal human foreskin fibroblasts and partially purified LDL receptors [PMID:7822276]. Databases hold a PDB structure with a chain of each protein [DB:PDB 2FCW], BioGRID [DB:BioGRID] and IntAct NMR and pull-down records [DB:IntAct], and UniProt lists the interaction [DB:UniProt]. The mouse pair is ortholog-inferred.","localisation_and_range":"LRPAP1 is flagged secreted [flag]; the cell-based inhibition used exogenous RAP [PMID:7822276].","caveats":"The authors report affinity for LDLR 14 to 350 times weaker than for LRP, gp330 or VLDL receptors [PMID:7822276]. Paper read as abstract only.","key_references":[{"PMID":"7822276","why":"RAP binds LDL receptors (KD 250 nM) and inhibits lipoprotein binding"}],"covers":["LR001035","LR004449"]},"LR001044":{"pair":"LTB -> LTBR","headline":"LTBR is a receptor specific for LT-beta containing complexes; two early papers, abstract-read, human.","interaction_type":"direct binding","direction_and_effect":"The predominant surface lymphotoxin form, LT-alpha1/beta2, is recognised by the LT-beta receptor [PMID:7995952]. A receptor specific for human LT-beta was identified [PMID:8171323]. Curator labels agonist; UniProt calls LTBR the receptor for heterotrimeric LTA/LTB [DB:UniProt].","molecular_requirements":"LT-beta acts as part of a complex with LT-alpha; the 60 and 80 kDa TNF receptors do not recognise the major cell surface LT-alpha-LT-beta complex [PMID:8171323]. LT-beta alone as a ligand is not shown. A structure includes chains of LTB and LTBR [DB:PDB 4MXW].","affinity_potency":[],"species_and_systems":"Human systems: PMA-activated II-23 T cell hybridoma [PMID:7995952]; species details of the 1994 study not in the abstract [PMID:8171323].","localisation_and_range":"LT-beta is a type II transmembrane protein, with surface complexes not secreted [PMID:8171323][PMID:7995952]; contact-dependent signalling.","caveats":"Both papers abstract-only; no affinity. One row was a different entity and one abstract_insufficient (not shown).","key_references":[{"PMID":"8171323","why":"Identifies a receptor specific for LT-beta"},{"PMID":"7995952","why":"LT-alpha1/beta2 recognised by LTBR"}],"covers":["LR001044","LR004457"]},"LR001062":{"pair":"MDK -> SDC3","headline":"Syndecan-3 from fetal rat bound midkine strongly; one abstract-only paper plus UniProt statements.","interaction_type":"direct binding","direction_and_effect":"Syndecan-3 isolated from 16-day rat fetus bound midkine strongly, and is considered involved in midkine interaction in later CNS development [PMID:9089390]. UniProt states midkine binds SDC3 or GPC2 and mediates neurite outgrowth and cell adhesion [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond binding of isolated syndecan-3.","affinity_potency":[],"species_and_systems":"Rat fetal tissue syndecan-3 [PMID:9089390]; curator fields list human, which the abstract does not support. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Not reported in our evidence; midkine flagged secreted [flag].","caveats":"One abstract-only paper; no affinity, no assay detail beyond 'bound'. The other UniProt-cited papers (PMID 12084985, 1768439) were not judged in our dossier.","key_references":[{"PMID":"9089390","why":"Isolated rat syndecan-3 binds midkine strongly"}],"covers":["LR001062","LR004475"]},"LR001071":{"pair":"MLN -> MLNR","headline":"Motilin is a well-supported agonist of its receptor MLNR, with binding, photoaffinity, mutagenesis and functional data.","interaction_type":"direct binding","direction_and_effect":"Motilin acts as a full agonist raising intracellular calcium, with antagonist controls GM-109 and [Phe3,Nle13]motilin blocking the response [PMID:11259768] [PMID:11461914]. GtoPdb lists full agonist action [DB:GtoPdb].","molecular_requirements":"Photoaffinity labelling maps contacts to the first and second extracellular loops and to Phe332 in the third loop [PMID:11461914] [PMID:15677347]. Receptor mutants lost motilin activity (Val179, Leu245, Arg246; Gly36, Pro103, Leu109, Phe332) while erythromycin responses stayed normal [PMID:11781320] [PMID:16531413]. Motilin(1-14) retains full potency; Ala at Phe1, Ile4 or Tyr7 costs most [PMID:12054506]. A PDB structure record exists [DB:PDB 8IBV].","affinity_potency":[{"value":"Ki 2.3 nM","assay":"binding on CHO cells overexpressing human motilin receptor","system":"human receptor, CHO cells","cite":"PMID:11461914"},{"value":"pKd 8.9","assay":"125I-[Nle13]porcine motilin binding (second site pKd 6.11)","system":"human TE671 cells, porcine ligand","cite":"PMID:11259768"}],"species_and_systems":"Mostly human receptor in CHO or COS cells; the TE671 study used porcine motilin on human cells [PMID:11259768]. Abstract-only reading throughout.","localisation_and_range":"Motilin is flagged secreted and non-transmembrane; MLNR is transmembrane [flag].","caveats":"All papers were read as abstracts; one further paper was judged abstract_insufficient. Mutagenesis and cross-linking used analogues in some studies [PMID:15677347].","key_references":[{"PMID":"11461914","why":"Photoaffinity labelling, Ki 2.3 nM"},{"PMID":"11781320","why":"Second extracellular loop mutagenesis"},{"PMID":"11259768","why":"Binding in TE671 cells"}],"covers":["LR001071"]},"LR001080":{"pair":"MSTN -> ACVR2B","headline":"Myostatin binds ACVR2B (ActRIIB) as its primary type II receptor, backed by three papers.","interaction_type":"direct binding","direction_and_effect":"Purified myostatin dimer binds ActRIIB [PMID:11459935]; myostatin binds ActRIIB first and then recruits ALK4 or ALK5 to phosphorylate Smad2/Smad3 [PMID:14517293]. In human granulosa cells GDF8 suppressed PTX3 via SMAD2/3 [PMID:25641196].","molecular_requirements":"Needs a type I partner, ALK4 or ALK5 [PMID:14517293]. Myostatin competes with BMP7 for ActRIIB [PMID:14517293].","affinity_potency":[],"species_and_systems":"Purified proteins [PMID:11459935]; cell-based assays [PMID:14517293]; human granulosa cells [PMID:25641196]; mouse pair ortholog-inferred. IntAct SPR and BioGRID records also listed [DB:IntAct][DB:BioGRID 297250].","localisation_and_range":"Myostatin is secreted [flag].","caveats":"All abstracts only; one further paper is pending.","key_references":[{"PMID":"11459935","why":"Binding of myostatin to ActRIIB"},{"PMID":"14517293","why":"ActRIIB then ALK4/ALK5 signalling"},{"PMID":"25641196","why":"ACVR2A/2B knockdown in granulosa cells"}],"covers":["LR001080","LR004492"]},"LR006201":{"pair":"NCAM1 -> CNTN2","headline":"High-affinity binding of N-CAM to TAG-1/axonin-1 (CNTN2) measured in a binding assay, read from abstract only.","interaction_type":"direct binding","direction_and_effect":"N-CAM is described as a high-affinity ligand of TAG-1/axonin-1; effect on signalling not reported in our evidence [PMID:8663515].","molecular_requirements":"Not reported in our evidence; Reactome lists an NCAM1-Contactin-2 plasma membrane complex [DB:Reactome R-HSA-375108].","affinity_potency":[{"value":"Kd approximately 1 nM","assay":"high-affinity binding assay","system":"N-CAM with TAG-1/axonin-1 (species not stated in dossier)","cite":"PMID:8663515"}],"species_and_systems":"Species of the assay proteins is not reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both partners are flagged transmembrane or receptor-capable [flag]; contact-mediated adhesion is plausible but not stated in the paper text we have.","caveats":"Abstract only. The abstract focuses on neurocan and phosphacan; the N-CAM Kd is quoted in the evidence sentence as a prior demonstration. Two other rows were abstract_insufficient.","key_references":[{"PMID":"8663515","why":"N-CAM bound by TAG-1/axonin-1 with Kd about 1 nM"}],"covers":["LR002976","LR006201"]},"LR004500":{"pair":"NCAM1 -> ROBO1","headline":"Abstract of a Robo3 paper says Robo3 binds Robo1 and NCAM; it does not describe NCAM-Robo1.","interaction_type":"functional only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms; mouse pair is ortholog-inferred [PMID:16226035].","localisation_and_range":"Not reported in our evidence.","caveats":"The cited sentence is about Robo3 binding Robo1 and NCAM, so NCAM-Robo1 is not itself shown [PMID:16226035]. Abstract only.","key_references":[{"PMID":"16226035","why":"Robo3 binds Robo1 and NCAM heterophilically"}],"covers":["LR001089","LR004500"]},"LR006210":{"pair":"NECTIN4 -> NECTIN1","headline":"Direct trans-interaction with 100 nM Kd shown in human nectins; selective for nectin1 among nectins.","interaction_type":"direct binding","direction_and_effect":"Soluble nectin4-Fc trans-interacts with nectin1-expressing cells but not with cells expressing nectin2, nectin3 or PVR/CD155; nectin1-Fc precipitated nectin4 and the proteins interacted in vitro [PMID:11544254]. Effect is adhesion; signalling direction not reported.","molecular_requirements":"The nectin1 V domain is the interaction region [PMID:11544254]; V-to-V contacts with C domains raising affinity, mapped to C-C'-C\"-D strands [PMID:12011057].","affinity_potency":[{"value":"KD 100 nM","assay":"nectin1/nectin4 trans-interaction","system":"recombinant human nectin ectodomains","cite":"PMID:12011057"}],"species_and_systems":"Human proteins; mouse pair is ortholog-projected [PMID:11544254] [PMID:12011057].","localisation_and_range":"Membrane-bound trans adhesion [DB:Reactome]; flags mark nectin4 and nectin1 as secreted as well [flag].","caveats":"Abstract-only reading. Weaker than nectin1/nectin3 (KD 1 nM) [PMID:12011057].","key_references":[{"PMID":"11544254","why":"Identifies nectin4 and its selective binding to nectin1"},{"PMID":"12011057","why":"KD 100 nM for nectin1/nectin4"}],"covers":["LR002985","LR006210"]},"LR001107":{"pair":"NLGN2 -> NRXN3","headline":"Only a general neuroligin-neurexin paper plus a BioGRID record; NRXN3 and NLGN2 not individually resolved.","interaction_type":"database-asserted only","direction_and_effect":"Neuroligins 2 and 3 were characterised for neurexin binding alongside neuroligin 1 [PMID:8576240]; effect on NRXN3 is not reported in our evidence.","molecular_requirements":"Tight binding needs beta-neurexins lacking a splice site 4 insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Rat binding assays (curator-listed) [PMID:8576240]; mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"The visible abstract does not resolve which neurexin paralogue binds NLGN2; the cited sentence is descriptive. Abstract only. No affinity.","key_references":[{"PMID":"8576240","why":"General neuroligin-neurexin binding"}],"covers":["LR001107","LR004518"]},"LR001116":{"pair":"NMU -> NMUR2","headline":"Strongly supported direct agonist-receptor pair: radioligand binding, calcium and signalling assays in recombinant human cells, and Reactome, BioGRID, GtoPdb and PDB records.","interaction_type":"direct binding","direction_and_effect":"NMU is an agonist of NMU2R; it raises intracellular Ca2+ and inositol phosphate and inhibits forskolin-stimulated cAMP in HEK-293 cells [PMID:15292653]. The receptor couples to Galpha(q/11) and Galpha(i) [PMID:15331768]. NMU elevates acidification, arachidonic acid metabolite release and Ca2+ in CHO cells expressing TGR-1 [PMID:10887190]. Radiolabeled NMU binds with high affinity to membranes of these cells [PMID:10887190].","molecular_requirements":"Single receptor chain is sufficient in recombinant cells; no co-receptor reported. Binding to the receptor is described as essentially irreversible, followed by internalisation [PMID:15331768].","affinity_potency":[{"value":"EC50 0.50 nM","assay":"intracellular Ca2+ release (stated in abstract for NmU isopeptides)","system":"human NmU1R/NmU2R in HEK-293 cells","cite":"PMID:15292653"},{"value":"EC50 1.50 nM","assay":"inositol phosphate formation","system":"human recombinant receptor in HEK-293 cells","cite":"PMID:15292653"},{"value":"IC50 0.80 nM","assay":"inhibition of forskolin-stimulated cAMP","system":"human NmU2R in HEK-293 cells","cite":"PMID:15292653"}],"species_and_systems":"Human recombinant receptors in HEK-293 cells [PMID:15292653][PMID:15331768]; TGR-1 in CHO cells from rat cDNA [PMID:10887190]; endogenous receptors in isolated rat smooth muscle cells [PMID:15331768]. The mouse pair is inferred from human by orthology.","localisation_and_range":"NMU is flagged secreted and the receptor transmembrane [flag]; the papers do not address range.","caveats":"Almost all papers were read as abstracts only. PMID:10899166 does not state species. PMID:10894543 names no specific binding assay or affinity.","key_references":[{"PMID":"10887190","why":"TGR-1 (NMUR2) activated by NMU with high-affinity radioligand binding in CHO cells"},{"PMID":"15292653","why":"Radioligand binding and signalling of both human receptors"},{"PMID":"15331768","why":"G protein coupling and near-irreversible binding"}],"covers":["LR001116","LR004527"]},"LR001125":{"pair":"NPFF -> NPFFR2","headline":"NPFF binds and activates NPFFR2 with sub-nanomolar to nanomolar affinity in recombinant cells; well supported by binding papers.","interaction_type":"direct binding","direction_and_effect":"NPFF is an agonist: cells expressing the receptor bind and respond in a concentration-dependent manner [PMID:10851242]; NPFF activated the receptor in several heterologous systems [PMID:11024015]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Receptor-only; no co-receptor requirement reported in our evidence. A short NPGPR isoform lacking exon 2 is described [PMID:12609745].","affinity_potency":[{"value":"Kd 0.37 nM","assay":"specific NPFF binding to cloned receptor","system":"human/rat NPFF2 receptor, heterologous expression","cite":"PMID:11024015"},{"value":"IC50 14.7 nM","assay":"[125I]NPFF displaced by NPFF","system":"cloned full-length human NPGPR","cite":"PMID:12609745"}],"species_and_systems":"Human cloned receptors in cells [PMID:10851242]; human/rat receptors [PMID:11024015]. Mouse pair is projected from human evidence. All papers read as abstracts only.","localisation_and_range":"NPFF is annotated secreted and NPFFR2 transmembrane [flag]; PMID:11024015 reports receptor mRNA and binding sites in spinal dorsal horn and thalamic nuclei.","caveats":"All four papers were read as abstracts only. The full-length NPGPR showed an IC50 about 100-fold weaker than for the shorter NPFF2 form [PMID:12609745]. NPFF is also reported to bind NPFF1 (Kd 1.13 nM) [PMID:11024015], so paralog cross-activity exists. FMRF-amide and related peptides weakly activate the receptor [PMID:10851242].","key_references":[{"PMID":"11024015","why":"Kd for NPFF at NPFF2 with activation in several systems"},{"PMID":"10851242","why":"Cloned human receptor binds and responds to NPFF"},{"PMID":"12609745","why":"Binding of NPFF to full-length NPGPR and isoform"}],"covers":["LR001125","LR004535"]},"LR001134":{"pair":"NPPC -> NPR3","headline":"CNP binds the NPR3 clearance receptor, shown by a crystal structure of the human complex.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of human NPR-C with CNP shows one CNP bound in the dimer interface, with a 20 angstrom closure of the membrane-proximal domains [PMID:11533490]. UniProt says it binds the clearance receptor [DB:UniProt]; PDB 1JDP [DB:PDB 1JDP].","molecular_requirements":"NPR-C functions as a dimer binding a single CNP [PMID:11533490]. The receptor lacks guanylyl cyclase activity per curator note.","affinity_potency":[],"species_and_systems":"Human NPR-C extracellular domain, structure at 2.0 angstroms (complex) [PMID:11533490]; human, bovine, rat preparations [PMID:1309330]. Mouse pair is projected.","localisation_and_range":"CNP annotated secreted [flag].","caveats":"Both papers abstract-only; PMID:1309330 gives a C-receptor affinity rank of ANP greater than CNP greater than BNP, so CNP is not the preferred ligand. Clearance receptor: binding not shown to signal.","key_references":[{"PMID":"11533490","why":"Structure of NPR-C with CNP"},{"PMID":"1309330","why":"Rank order of C-receptor binding"}],"covers":["LR001134","LR004544"]},"LR001143":{"pair":"NPY -> NPY4R","headline":"NPY binds NPY4R with nanomolar affinity but lower than PP, the preferred ligand; abstract-level cloning papers.","interaction_type":"direct binding","direction_and_effect":"NPY is an agonist of Y4/PP1 but a weaker one than PP. NPY pKi 8.68 against PP pKi 10.25 [PMID:7592911]; Ki 9.9 nM for NPY versus 13.8 pM for PP [PMID:7493937]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain; no co-receptor reported.","affinity_potency":[{"value":"pKi 8.68","assay":"125I-PYY displacement by NPY","system":"transiently expressed human Y4","cite":"PMID:7592911"},{"value":"Ki 9.9 nM","assay":"binding","system":"cloned human PP1 (Y4) in CHO cells","cite":"PMID:7493937"}],"species_and_systems":"Human receptor; human ligands [PMID:7592911][PMID:7493937]. Mouse pair is projected from human.","localisation_and_range":"NPY is flagged secreted, NPY4R transmembrane [flag].","caveats":"All papers read as abstracts only. Y4 is described as primarily a PP receptor [PMID:7493937], and the chimera paper calls PP highly selective for Y4 [PMID:15966750]. NPY is a lower-affinity, likely secondary ligand. One different_entity row was excluded.","key_references":[{"PMID":"7592911","why":"NPY pKi 8.68 at human Y4, compared with PP"},{"PMID":"7493937","why":"NPY Ki 9.9 nM at PP1/Y4 receptor"}],"covers":["LR001143","LR004552"]},"LR003006":{"pair":"NRG1 -> ITGB3","headline":"Single abstract-level report that NRG1 binds integrin beta3 (ITGB3); one paper, stored per subunit, not the dimer.","interaction_type":"direct binding","direction_and_effect":"NRG1 (isolated EGF-like domain or native multi-domain form) binds integrins; Lys-to-Glu mutants suppressed integrin binding and ErbB3 phosphorylation, so integrin binding appears to support NRG1-ErbB3 signalling [PMID:20682778]. UniProt states this binding is essential for NRG1-ERBB signalling [DB:UniProt].","molecular_requirements":"NRG1 binds the integrin heterodimers alphavbeta3 and alpha6beta4; the dossier stores them per subunit [PMID:20682778]. alpha6beta4 was functionally dominant for forming the integrin-NRG1-ErbB3 ternary complex [PMID:20682778]. A UniProt record says the ternary complex includes ERBB3 [DB:UniProt]. This row names only one chain; the evidence concerns the heterodimer.","affinity_potency":[{"value":"KD 136 nM (1.36 x 10(-7) m), to alphavbeta3","assay":"direct binding","system":"purified integrins","cite":"PMID:20682778"}],"species_and_systems":"Human ligand and human receptor, purified proteins; the mouse pair is projected from human evidence [PMID:20682778].","localisation_and_range":"NRG1 is flagged both secreted and transmembrane [flag]; range not addressed in the paper text we have.","caveats":"Only one paper, read as abstract only. The KD is for alphavbeta3, not for this individual chain. Chain-only row for a heterodimeric receptor; the integrin dimer should be the unit scored.","key_references":[{"PMID":"20682778","why":"Direct NRG1-integrin binding and integrin-NRG1-ErbB3 ternary complex"}],"covers":["LR003006","LR006230"]},"LR001152":{"pair":"NRG4 -> ERBB4","headline":"NRG4 is a selective ERBB4 ligand: it displaces NRG-1 from ErbB-4 and activates its signalling.","interaction_type":"direct binding","direction_and_effect":"NRG-4 displaces ErbB-4-bound NRG-1 and activates signalling downstream of this receptor; an EGF-like peptide drove growth of ErbB-4 cells only [PMID:10348342].","molecular_requirements":"ErbB-4 alone suffices; other ErbB proteins or their combinations did not respond [PMID:10348342].","affinity_potency":[],"species_and_systems":"Species not clearly reported in this row; ErbB receptors ectopically expressed in interleukin-dependent cells, synthetic peptide [PMID:10348342]. Mouse pair is projected.","localisation_and_range":"Pro-NRG-4 is a transmembrane protein with a short cytoplasmic domain [PMID:10348342]; flags mark secreted and transmembrane [flag]. mRNA in adult pancreas, weakly muscle [PMID:10348342].","caveats":"Single paper, abstract only; no affinity. GtoPdb has no action or affinity [DB:GtoPdb]. Reactome records are generic NRG ligand entries [DB:Reactome].","key_references":[{"PMID":"10348342","why":"NRG-4 specificity for ErbB-4 and displacement of NRG-1"}],"covers":["LR001152","LR004561"]},"LR003015":{"pair":"NRXN1 -> CBLN1","headline":"Indirect: Cbln1 bridges presynaptic neurexins and postsynaptic GluRdelta2; support rests on one abstract-read paper.","interaction_type":"functional only","direction_and_effect":"Cbln1 links the GluRdelta2 N-terminal domain to presynaptic neurexins to drive synapse formation; synaptogenic activity was abolished in Cbln1 knockout cultures and restored by recombinant Cbln1 [PMID:20537373]. Soluble NRXN1beta extracellular domain suppressed Cbln1 synaptogenic activity in culture and in vivo [PMID:20537373].","molecular_requirements":"A tripartite GluRdelta2-Cbln1-NRXN complex is described; knockdown of NRXNs in granule cells also impaired GluRdelta2 synaptogenic activity [PMID:20537373]. Whether NRXN1 binds Cbln1 directly is not shown in our abstract-only evidence.","affinity_potency":[],"species_and_systems":"Mouse cerebellar primary cultures and in vivo; curation lists human. Human pair is ortholog-inferred.","localisation_and_range":"CBLN1 is flagged secreted [flag]; NRXN1 is transmembrane presynaptic [flag]; the complex is trans-synaptic [PMID:20537373].","caveats":"Read as abstract only. The assay_class direct_binding is not clearly supported by the abstract, which reports functional bridging and competition rather than a binding measurement. CBLN1 is a bridging ligand, not a conventional receptor.","key_references":[{"PMID":"20537373","why":"Cbln1 bridges GluRdelta2 NTD and neurexins in cerebellar synapse formation"}],"covers":["LR003015","LR006239"]},"LR003024":{"pair":"NRXN1 -> NLGN3","headline":"Direct binding of NLGN3 and beta-neurexin supported, but the second paper's evidence concerns PTPdelta and competition.","interaction_type":"direct binding","direction_and_effect":"Neuroligins were tested against beta-neurexin-1 by SPR [PMID:17042500]. NLGN3 and neurexins form a canonical transsynaptic pair, and NLGN3 binds PTPdelta splice variants in competition with NRXN binding [PMID:33758193].","molecular_requirements":"Competition: PTPdelta splice variants compete with NRXNs for NLGN3; a NLGN3 mutation selectively impairing the NRXN interaction increased sociability in mice [PMID:33758193].","affinity_potency":[],"species_and_systems":"17042500: recombinant protein, unspecified species; 33758193 used mouse assays. Mouse pair is the non-inferred one in curation.","localisation_and_range":"Both transmembrane [flag].","caveats":"The NRXN1 identity is not stated in the 33758193 abstract (NRXNs generally). No NLGN3 affinity in our evidence. BioGRID lists reconstituted complex and affinity capture-western [DB:BioGRID].","key_references":[{"PMID":"17042500","why":"SPR of neuroligins with beta-neurexin-1"},{"PMID":"33758193","why":"NLGN3 canonical NRXN pair and competition with PTPdelta"}],"covers":["LR003024","LR006248"]},"LR001161":{"pair":"NTF4 -> NTRK2","headline":"NT-4 binds TrkB directly with subnanomolar affinity, with structural and database support.","interaction_type":"direct binding","direction_and_effect":"The second Ig-like domain of human TrkB is sufficient to bind BDNF and NT-4 with subnanomolar affinity by surface plasmon resonance [PMID:11855816]. NT-4/5 is a preferred TrkB ligand [PMID:7679912].","molecular_requirements":"TrkB Ig2 domain alone is sufficient [PMID:11855816].","affinity_potency":[{"value":"subnanomolar","assay":"surface plasmon resonance","system":"isolated human TrkB Ig2 domain","cite":"PMID:11855816"}],"species_and_systems":"Human TrkB domain (recombinant) [PMID:11855816]; neuronal cells expressing defined Trk receptors [PMID:7679912]. BioGRID co-crystal structure and PDB 1HCF are listed [DB:BioGRID][DB:PDB 1HCF].","localisation_and_range":"NT-4 flagged secreted, NTRK2 transmembrane [flag].","caveats":"Affinity is only qualitative; abstracts only; two papers pending, one review-only.","key_references":[{"PMID":"11855816","why":"SPR: TrkB Ig2 binds NT-4 subnanomolar"},{"PMID":"7679912","why":"NT-4/5 as preferred TrkB ligand"}],"covers":["LR001161"]},"LR003033":{"pair":"NTN1 -> APP","headline":"Netrin-1 binds APP in co-IP and cell-recruitment assays and modulates APP signalling; mainly one lab's work.","interaction_type":"direct binding","direction_and_effect":"APP binds netrin-1; netrin-1 binding triggers AICD-dependent gene transcription and suppresses Abeta production in brain slices from Alzheimer model transgenic mice [PMID:19148186]. During commissural axon guidance, APP is part of the DCC receptor complex mediating netrin-1 dependent guidance [PMID:22782894].","molecular_requirements":"APP interacts with DCC in the presence of netrin-1 [PMID:22782894]. Netrin-1 did not interact with p75NTR in cortex co-IP [PMID:19148186].","affinity_potency":[],"species_and_systems":"Co-IP in HEK293T cells, B103 cells and mouse E16.5 cortical neurons and developing cortex [PMID:19148186]. Human pair is ortholog-inferred; mouse pair is direct. IntAct lists an ELISA record [DB:IntAct].","localisation_and_range":"NTN1 secreted, APP transmembrane [flag].","caveats":"Abstracts only (one paper has excerpts of its results); the 2012 paper's evidence sentence is background to the earlier work [PMID:22782894].","key_references":[{"PMID":"19148186","why":"Netrin-1 binds APP; modulates Abeta and AICD"},{"PMID":"22782894","why":"APP in DCC complex for axon guidance"}],"covers":["LR003033","LR006257"]},"LR001170":{"pair":"NTN4 -> DCC","headline":"Netrin-4 binds DCC-transfected CHO cells through its N-terminal domain; single abstract-only study.","interaction_type":"direct binding","direction_and_effect":"AP4-tagged netrin-4 bound CHO cells transfected with DCC or UNC5H1, and only the N-terminal LNT domain of netrin-4 bound them [PMID:17174565].","molecular_requirements":"Netrin-4 also binds neurons through its N- and C-terminal domains, which suggests additional unidentified receptors [PMID:17174565].","affinity_potency":[],"species_and_systems":"COS7-produced AP4-netrin-4 fusion, CHO transfectants, cultured primary cortical neurons [PMID:17174565]. IntAct lists a solid phase assay and Reactome lists a NTN4:DCC,UNC5A complex [DB:IntAct][DB:Reactome]. Both species pairs are ortholog-inferred.","localisation_and_range":"Netrin-4 is secreted and DCC is transmembrane [flag].","caveats":"Abstract only, no affinity reported. The Reactome entry rests on the same paper.","key_references":[{"PMID":"17174565","why":"Netrin-4 binds DCC and UNC5H1 transfected cells via the LNT domain"}],"covers":["LR001170","LR004579"]},"LR003042":{"pair":"NTN4 -> UNC5B","headline":"Conflicting: netrin-4 does not bind Unc5B directly, but Unc5B silencing blocks netrin-4 function in endothelial cells.","interaction_type":"conflicting","direction_and_effect":"Netrin-4 bound neogenin but not Unc5B or Unc5C [PMID:18719102]. Silencing UNC5B abrogated NTN4-induced activities in endothelial progenitor cells, and UNC5B is called an NTN4 receptor [PMID:31914695].","molecular_requirements":"Netrin-4 increased the neogenin-Unc5B association in endothelial cells, suggesting Unc5B is recruited via neogenin [PMID:18719102].","affinity_potency":[],"species_and_systems":"Endothelial cells (2008 paper) and human endothelial progenitor cells with mouse hindlimb ischemia (2020 paper) [PMID:18719102][PMID:31914695].","localisation_and_range":"Netrin-4 is secreted and UNC5B is transmembrane [flag].","caveats":"The verified negative for direct binding is from an abstract [PMID:18719102]; the supporting paper shows only a functional knockdown effect, not binding [PMID:31914695]. Both papers were read as abstracts.","key_references":[{"PMID":"18719102","why":"Reports no direct Netrin-4-Unc5B binding; Unc5B recruited via neogenin"},{"PMID":"31914695","why":"UNC5B silencing blocks NTN4 effects in EPCs"}],"covers":["LR003042"]},"LR003051":{"pair":"PCDHB11 -> PCDHB11","headline":"Human PCDHB11 causes homophilic cell adhesion, weaker than other clustered protocadherins; abstract-level support in one paper.","interaction_type":"functional only","direction_and_effect":"Human PCDHB11 expressed in K562 cells formed clusters, smaller than those of murine PCDHGA3, and its adhesion exceeded negative controls [PMID:27068704].","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Human PCDHB11 in human K562 suspension cells (cell aggregation assay) [PMID:27068704].","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Only a cell-aggregation readout, with no direct binding measurement; the adhesion is relatively weak. A reverted ancestral-like form behaved similarly per the curator note. Curator read this paper as abstract only.","key_references":[{"PMID":"27068704","why":"homophilic adhesion test of human PCDHB11"}],"covers":["LR003051"]},"LR006300":{"pair":"PCDHGB2 -> PCDHGB2","headline":"Mouse gammaB2 shows strictly homophilic trans binding in aggregation assays; biophysics paper also supports it.","interaction_type":"direct binding","direction_and_effect":"Homophilic trans interaction with no heterophilic binding between different isoforms [PMID:20679223][PMID:35253643]. Strictly homophilic across seven gamma-Pcdh isoforms tested, including B2 [PMID:20679223]. No agonist/antagonist effect reported.","molecular_requirements":"Specificity is mediated by EC2 and EC3; gamma-Pcdhs also form cis multimers, and cis-tetramers are proposed as the unit of trans adhesion [PMID:20679223]. Interactions are only partially Ca(2+)-dependent [PMID:20679223].","affinity_potency":[],"species_and_systems":"Mouse proteins: K562 aggregation assays [PMID:20679223] and analytical ultracentrifugation of ectodomain fragments [PMID:35253643]. Human pair inferred by conservation.","localisation_and_range":"Membrane protein (not secreted per annotation flags) [flag]; contact-dependent between apposed membranes.","caveats":"The AUC KD range of 9-80 uM in the excerpt appears to describe cis dimerisation of EC3-6 fragments rather than trans binding, so no affinity is listed [PMID:35253643]. The PNAS paper was read as abstract only in the dossier summary but via browser full text by the curator, with an unverified quote [PMID:20679223].","key_references":[{"PMID":"35253643","why":"AUC biophysics: trans homophilic binding precise, no heterophilic interactions."},{"PMID":"20679223","why":"K562 aggregation: gamma-Pcdh trans interactions strictly homophilic."}],"covers":["LR003077","LR006300"]},"LR001206":{"pair":"PENK -> OPRD1","headline":"Weak support: the one verified paper is a biosensor tool paper whose cited sentence does not address PENK or OPRD1; GtoPdb lists an agonist.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists a full agonist for PENK at OPRD1 [DB:GtoPdb]. The paper's evidence sentence concerns kappaLight and dynorphin release, not this pair [PMID:39009835].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Biosensors built on human OPRK1, OPRD1 and OPRM1; mouse brain slices and in vivo photometry in mice [PMID:39009835].","localisation_and_range":"PENK is flagged secreted [flag]. Range not reported in our evidence.","caveats":"The paper was read as abstract plus excerpts; the excerpts only describe cloning. Direct PENK-OPRD1 evidence is not shown. GtoPdb lists pKi without a value in the dossier [DB:GtoPdb].","key_references":[{"PMID":"39009835","why":"Opioid receptor-based biosensors (indirect)"}],"covers":["LR001206","LR004615"]},"LR001215":{"pair":"PGF -> FLT1","headline":"PlGF binds FLT1 (VEGFR1): crystal structure, mutagenesis and binding papers, plus PDB 1RV6.","interaction_type":"direct binding","direction_and_effect":"PlGF binds FLT1 with high affinity but not Flk-1/KDR [PMID:7929268]; the curator labels it agonist. PlGF binds the same VEGFR1 interface as VEGF [PMID:14684734].","molecular_requirements":"VEGFR1 Ig-like domain 2 carries the binding determinants; Glu137, Lys171, His223 and Arg224 affect PlGF but not VEGF binding [PMID:9452434] [PMID:14684734].","affinity_potency":[],"species_and_systems":"Human proteins; crystal structure at 2.5 A [PMID:14684734] and cell and soluble-receptor binding [PMID:7929268]. Mouse pair is ortholog-inferred.","localisation_and_range":"PGF is flagged secreted [flag]; PlGF152 binds heparin and PlGF131 does not [PMID:7929268].","caveats":"All abstract only. PlGF alone showed little direct mitogenic activity but potentiated VEGF [PMID:7929268]. Structure 1RV6 [DB:PDB 1RV6]; BioGRID and IntAct agree [DB:BioGRID] [DB:IntAct].","key_references":[{"PMID":"14684734","why":"Crystal structure of PlGF bound to VEGFR1 domain 2"},{"PMID":"7929268","why":"PlGF binds Flt-1 but not KDR"},{"PMID":"9452434","why":"Alanine scanning of Flt-1 domains"}],"covers":["LR001215","LR004618"]},"LR007989":{"pair":"PI16 -> TNFRSF21","headline":"No verified paper; only IntAct in vitro records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct records a solid phase assay and surface plasmon resonance between O75509 and Q6UXB8 [DB:IntAct].","localisation_and_range":"PI16 is flagged secreted [flag].","caveats":"Both judged rows were abstract_insufficient. Support rests on IntAct only; system and affinity not reported in our evidence [DB:IntAct].","key_references":[],"covers":["LR007989"]},"LR003105":{"pair":"PLA2G2A -> ERBB2","headline":"Interaction of sPLA2-IIa with HER2 is reported as indirect (co-IP context); weak support for direct ligand-receptor status.","interaction_type":"functional only","direction_and_effect":"The paper states sPLA2-IIa binds EGFR and HER3 and only indirectly interacts with HER2 [PMID:28440478]. sPLA2-IIa activates EGFR-family receptors and HER/ERBB signalling in a feedback loop [PMID:28440478]. BioGRID lists Affinity Capture-Western for PLA2G2A-ERBB2 [DB:BioGRID 2524053].","molecular_requirements":"HER2 engagement is likely through EGFR/HER3 partners rather than direct binding, per the curator note [PMID:28440478].","affinity_potency":[],"species_and_systems":"Human lung and prostate cancer cell lines; nude mouse xenografts [PMID:28440478]. Mouse pair ortholog-inferred.","localisation_and_range":"Secreted ligand, from the flag on PLA2G2A [flag] and elevated tumour microenvironment levels [PMID:28440478].","caveats":"Abstract only; the direct receptors named are EGFR and HER3, not HER2, so this row is a co-receptor/indirect association [PMID:28440478].","key_references":[{"PMID":"28440478","why":"Only source; states indirect HER2 interaction"}],"covers":["LR003105","LR006326"]},"LR001224":{"pair":"PLAU -> LRP2","headline":"uPA:PAI-1 complexes bind LRP2 (gp330) with Kd about 0.8 nM and are endocytosed; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Affinity-purified gp330 bound PAI-1 complexed with uPA, calcium-dependently, inhibited by RAP and tPA-PAI-1 complexes [PMID:8344937]. In type II pneumocytes, endocytosis of uPA:PAI-1 complexes was demonstrated and RAP blocked internalisation and degradation [PMID:7673355]. Clearance receptor function, not signalling.","molecular_requirements":"The binding unit is the uPA:PAI-1 complex; anti-gp330 antibodies inhibited 30-50% and anti-LRP antibodies partially inhibited the rest, so gp330 acts with LRP [PMID:7673355].","affinity_potency":[{"value":"Kd about 0.8 nM","assay":"binding of uPA.PAI-1 complexes to affinity-purified gp330, 4 degrees C","system":"rabbit renal cortex gp330","cite":"PMID:8344937"}],"species_and_systems":"Rabbit renal cortex gp330 and rabbit proximal tubules [PMID:8344937]; immortalized rat type II pneumocytes [PMID:7673355]. No human experiment shown, though curated as human.","localisation_and_range":"LRP2 binding is at the apical part of proximal tubules [PMID:8344937]; uPA secreted per flag [flag].","caveats":"Abstract only; free uPA binding is not the tested species. Human and mouse pairs are ortholog-inferred.","key_references":[{"PMID":"8344937","why":"Kd about 0.8 nM for uPA.PAI-1 binding to gp330"},{"PMID":"7673355","why":"gp330-mediated endocytosis of uPA:PAI-1 in pneumocytes"}],"covers":["LR001224","LR004627"]},"LR003114":{"pair":"PLAUR -> ITGB1","headline":"Direct cell-based binding of soluble uPAR to beta1 (ITGB1) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Binding was to alpha4beta1, alpha6beta1 and alpha9beta1 [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (full text); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003114","LR006335"]},"LR001233":{"pair":"PLTP -> ABCA1","headline":"PLTP cross-links to ABCA1, competing with apoA-I, and promotes lipid efflux; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"PLTP and apoA-I were each covalently cross-linked to ABCA1 and blocked each other's cross-linking; both stabilised ABCA1 protein [PMID:14559902]. PLTP promoted cholesterol and phospholipid efflux, most with HDL present [PMID:14559902].","molecular_requirements":"Shared or overlapping ABCA1 binding site with apoA-I [PMID:14559902].","affinity_potency":[],"species_and_systems":"Human proteins; murine macrophages and ABCA1-transfected BHK cells [PMID:14559902].","localisation_and_range":"Ligand flagged secreted; ABCA1 membrane transporter [flag].","caveats":"Abstract only. PLTP acts as an intermediary transferring lipid to HDL. ABCA1 is a transporter, not a classical signalling receptor. One more row not shown.","key_references":[{"PMID":"14559902","why":"PLTP interacts with ABCA1 and enhances efflux"}],"covers":["LR001233","LR004636"]},"LR003123":{"pair":"PODXL2 -> SELP","headline":"Endoglycan (PODXL2) from B cells binds P-selectin in a sialylation-dependent way and supports rolling; a single paper.","interaction_type":"direct binding","direction_and_effect":"Immunopurified endoglycan from a B-cell line, a monocyte line and human tonsils bound P-selectin [PMID:18606703]. Introducing intact endoglycan into a B-cell line facilitated rolling on a P-selectin substrate [PMID:18606703].","molecular_requirements":"Binding was divalent cation-dependent and required sialylation; rolling depended on sialic acid and fucose [PMID:18606703]. Activated B cells increase endoglycan while PSGL-1 falls [PMID:18606703].","affinity_potency":[],"species_and_systems":"Human cell lines and tonsils [PMID:18606703]; mouse pair is ortholog-inferred.","localisation_and_range":"Endoglycan flagged transmembrane, not secreted [flag]; contact-dependent adhesion.","caveats":"One paper only, no affinity, no database records. The same paper is the sole support for the E-selectin pair.","key_references":[{"PMID":"18606703","why":"endoglycan binds P-selectin and supports B-cell rolling"}],"covers":["LR003123","LR006344"]},"LR001242":{"pair":"POMC -> MC4R","headline":"POMC-derived peptides bind and activate MC4R, shown in abstract-level binding studies; evidence relies on analogues and a mutant fusion protein.","interaction_type":"direct binding","direction_and_effect":"NDP-MSH, a synthetic alpha-MSH analogue, binds and activates human MC4R, with TM3 and TM6 residues needed for affinity [PMID:11101306]. A mutant beta-MSH/beta-endorphin fusion protein binds hMC4R with affinity similar to its natural ligands but activates it much less [PMID:12165561]. Rat MC4R responds to melanocortin agonists [PMID:10493100]. GtoPdb records agonist action [DB:GtoPdb].","molecular_requirements":"Receptor residues D122, D126, F261 and H264 contribute to NDP-MSH binding in hMC4R [PMID:11101306]. Other requirements not reported in our evidence.","affinity_potency":[{"value":"pKi 7.4-8.0","assay":"GtoPdb affinity range","system":"not specified","cite":"PMID:10493100"}],"species_and_systems":"Human MC4R [PMID:11101306][PMID:12165561]; rat MC4R [PMID:10493100]. Mouse pair is ortholog-inferred. All read as abstracts only.","localisation_and_range":"POMC flagged secreted, MC4R transmembrane [flag]; range not tested.","caveats":"No paper tests native full-length POMC or a single native peptide. NDP-MSH is a stabilised analogue [PMID:11101306]; the fusion protein from a disease mutation is a partial agonist-like variant, so binding and activation dissociate [PMID:12165561].","key_references":[{"PMID":"11101306","why":"hMC4R mutagenesis defining ligand-binding residues"},{"PMID":"12165561","why":"POMC variant fusion protein binds hMC4R but activates poorly"},{"PMID":"10493100","why":"Rat MC3R/MC4R pharmacology"}],"covers":["LR001242","LR004644"]},"LR011034":{"pair":"PORCN -> WNT4","headline":"UniProt notes WNT4 interacts with PORCN, by similarity; no verified evidence.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states WNT4 interacts with PORCN (by similarity) [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No papers shown; species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Database-only, inferred by similarity; one paper judged different_entity.","key_references":[],"covers":["LR011034"]},"LR001251":{"pair":"PPY -> NPY4R","headline":"Well supported direct agonist pair: PP binds Y4 with high affinity in several cloning and binding studies, plus GtoPdb and a PDB structure.","interaction_type":"direct binding","direction_and_effect":"PP is an agonist at Y4: it decreased cAMP and increased intracellular Ca2+ in Y4-transfected cells [PMID:7592911], is a full agonist in CHO cells [PMID:7493937], and was antisecretory in human and mouse colon mucosa, lost in Y4 knockout mouse tissue [PMID:16807358]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Y4 receptor alone was sufficient in transfected cells; no other subunit or co-receptor is reported in our evidence.","affinity_potency":[{"value":"Kd 2.8 nM","assay":"125I-human PP binding","system":"HEK293 cells stably expressing human receptor","cite":"PMID:8643460"},{"value":"Ki 13.8 pM","assay":"competition binding","system":"cloned human PP1 (Y4) receptor, CHO cells","cite":"PMID:7493937"},{"value":"pKi = 10.25","assay":"displacement of 125I-PYY","system":"transiently expressed human Y4","cite":"PMID:7592911"}],"species_and_systems":"Human PP and human Y4 in transfected HEK293, CHO and LMTK- cells; the colon study also used human and mouse tissue and mouse Y4 [PMID:16807358]. Mouse pair in the database is projected from human.","localisation_and_range":"PPY is flagged secreted and NPY4R transmembrane [flag], consistent with hormone-like paracrine or endocrine action.","caveats":"All four papers were read as abstracts only. PP also binds Y4 alongside PYY and NPY at lower affinity (pKi = 9.06 and 8.68) [PMID:7592911], so Y4 is not exclusive to PP. A structure of the pair exists [DB:PDB 7X9C].","key_references":[{"PMID":"8643460","why":"Human Y4 cloning, Kd 2.8 nM for PP"},{"PMID":"7493937","why":"Y4 cloning, Ki 13.8 pM, cAMP inhibition"},{"PMID":"16807358","why":"Y4 mediates PP responses in human and mouse colon"}],"covers":["LR001251","LR004652"]},"LR003132":{"pair":"PRLH -> NPFFR2","headline":"Weak support: a full-text RF-amide panel reports NPFF2R binding the peptide set at 0.1-10 nM, with no PrRP-specific value in our evidence.","interaction_type":"direct binding","direction_and_effect":"In a binding panel, NPFF2R bound the whole set of RF-amide peptides with affinity constants in the 0.1-10 nM range [PMID:23911743]; the curator marks this as agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human peptides and receptor, receptor-expressing cell membranes with [3H]-FFRF-NH2 [PMID:23911743]. Mouse pair is projected.","localisation_and_range":"PRLH is flagged secreted and NPFFR2 transmembrane [flag].","caveats":"Group statement only; the PRLH (PrRP) value is not given in our evidence, and the paper notes low selectivity among RF-amide peptides [PMID:23911743].","key_references":[{"PMID":"23911743","why":"RF-amide peptide binding profile at five receptors"}],"covers":["LR003132","LR006353"]},"LR001260":{"pair":"PROK2 -> PROKR2","headline":"Well supported agonist-receptor pair: PROK2 activates PROKR2; in vitro human data plus rat in vivo behavioural data; abstracts only.","interaction_type":"direct binding","direction_and_effect":"PK2 is a cognate ligand of PK-R2 (I5E), binding with high affinity and inducing calcium flux in CHO cells [PMID:12054613]. In rats, intracerebroventricular PK2 inhibited nocturnal locomotor activity, and PK2 positively fed back on its own transcription through PKR2 [PMID:12024206]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence. PK2beta is about 10-fold less potent than PK1 or PK2 at PKR2 [PMID:15772293].","affinity_potency":[{"value":"pIC50 6.0","assay":"intracellular Ca2+ response benchmark","system":"human PK2 in PKR2-expressing cells","cite":"PMID:15772293"}],"species_and_systems":"Human proteins in CHO cells [PMID:12054613][PMID:15772293]; rat in vivo experiments for the behavioural paper [PMID:12024206]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both PROK2 and the receptor are annotated secreted and transmembrane respectively [flag], so paracrine signalling onto membrane receptors.","caveats":"All abstract-only. The rat paper takes the PK2/PKR2 pairing as established and uses expression plus ICV PK2 without a receptor-selective antagonist or knockout, so it is weak for the pair itself [PMID:12024206]. GtoPdb pIC50 values for the pair are ranges without stated assay [DB:GtoPdb].","key_references":[{"PMID":"12054613","why":"Deorphanisation of PK-R2 by PK2."},{"PMID":"12024206","why":"Rat in vivo PK2 effect with PKR2 expression in SCN."},{"PMID":"15772293","why":"PK2 Ca2+ potency at PKR2, pIC50 6.0."}],"covers":["LR001260","LR004660"]},"LR011142":{"pair":"PRSS3 -> F2R","headline":"Mesotrypsin selectively activates PAR-1 in rat astrocytes per one abstract; enzyme-receptor relation.","interaction_type":"functional only","direction_and_effect":"Mesotrypsin selectively activated PAR-1, but not PAR-2, in rat astrocytes; the PAR-1 antagonist SCH79797 confirmed the selectivity [PMID:16903872].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat astrocytes; the pair is human-annotated [PMID:16903872].","localisation_and_range":"F2R is flagged transmembrane [flag]; the protease would act extracellularly.","caveats":"One abstract-only paper in rat; two other abstracts insufficient. Activation is presumably proteolytic but the abstract as quoted does not show cleavage.","key_references":[{"PMID":"16903872","why":"Mesotrypsin selective PAR-1 activation in rat astrocytes."}],"covers":["LR011142"]},"LR003141":{"pair":"PSAP -> M6PR","headline":"Prosaposin precursor is recognised by the mannose-6-phosphate receptor for lysosomal shuttling; supported by one abstract only.","interaction_type":"functional only","direction_and_effect":"The abstract states the SAP precursor can be recognised by the M-6-P receptor and shuttled from the secretory pathway to the lysosome [PMID:9707421]. This is an intracellular sorting route, not signalling.","molecular_requirements":"Not reported in our evidence beyond the receptor name.","affinity_potency":[],"species_and_systems":"Fibroblast uptake assays, human ligand and receptor per curator annotation; the M6PR statement is background in the abstract [PMID:9707421].","localisation_and_range":"Ligand carries a secreted flag [flag]; M6PR acts here on the secretory pathway to the lysosome, not as a cell-surface signalling receptor [PMID:9707421].","caveats":"The paper's own experiments concern LRP and the mannose receptor; M6PR is cited as prior knowledge, no new M6PR data. Abstract only. Evidence is a sorting receptor, not signalling.","key_references":[{"PMID":"9707421","why":"Describes M-6-P receptor, mannose receptor and LRP routes for SAP precursor uptake."}],"covers":["LR003141","LR006362"]},"LR003150":{"pair":"PTN -> MFRP","headline":"Surface plasmon resonance shows human PTN binds the MFRP ectodomain, from a receptor-deorphanisation screen.","interaction_type":"direct binding","direction_and_effect":"Human PTN binds the MFRP ectodomain by SPR, validating a CRISPRa screen hit [PMID:36178190]. Effect on signalling is not reported in our evidence.","molecular_requirements":"MFRP-ECD was the ligand-side partner in SPR; additional subunits not reported in our evidence [PMID:36178190].","affinity_potency":[],"species_and_systems":"Recombinant human ectodomains in SPR [PMID:36178190]; comparator MDK showed no binding to MFRP and ROR1 [PMID:36178190]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. Soluble ectodomain binding only.","caveats":"Full text read, but affinity values are not in our excerpts. The binding was in vitro with isolated ectodomains; cell-based function is not shown. Part of a large screen paper rather than a focused study.","key_references":[{"PMID":"36178190","why":"SPR binding of PTN to MFRP-ECD"}],"covers":["LR003150","LR006371"]},"LR007998":{"pair":"PVR -> KIR2DL5A","headline":"PVR binds KIR2DL5 in a large ELISA screen, confirmed by ECIA, SPR and cell staining; no other KIR bound.","interaction_type":"direct binding","direction_and_effect":"KIR2DL5-Fc bound PVR in the screen, confirmed by ECIA titration and SPR, and by flow cytometry of KIR2DL5- and PVR-transfected cells [PMID:32822567]. The paper notes both PVR and KIR2DL5 are ITIM-containing inhibitory receptors [PMID:32822567]. The record's inhibitory label is consistent with that but the paper shows no functional assay.","molecular_requirements":"PVR-Fc did not bind cells with KIR2DL4 or KIR2DL1 and was tested against 11 KIRs, so binding is specific to KIR2DL5 [PMID:32822567]. The record names KIR2DL5A; the paper says KIR2DL5, and the dossier does not say which KIR2DL5 gene was used.","affinity_potency":[],"species_and_systems":"Recombinant human extracellular domains, ELISA, SPR and transfected cells [PMID:32822567].","localisation_and_range":"Both membrane proteins, so contact-dependent; the soluble ectodomains were used in vitro.","caveats":"SPR used PVR analyte at 156-10,000 nM but no Kd is given in the excerpts. The paper says it validates a recently reported interaction (Husain et al., 2019).. IntAct lists SPR and solid-phase records [DB:IntAct]. Another row was abstract_insufficient.","key_references":[{"PMID":"32822567","why":"ELISA screen, SPR and cell staining show PVR-KIR2DL5 binding"}],"covers":["LR007998"]},"LR001305":{"pair":"RPS19 -> C5AR1","headline":"RPS19 cross-linked homodimer binds and activates C5aR1 in one abstract-only study; GtoPdb lists agonist.","interaction_type":"direct binding","direction_and_effect":"The RP S19 dimer activated the receptor by a two-step binding mechanism as with C5a; the second site triggered chemotaxis [PMID:11733378]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"The ligand is the cross-linked homodimer of S19, not the monomer. Receptor binding sites on S19 are a Lys41-His42-Lys43 basic cluster and a Leu131-Asp132-Arg133 moiety [PMID:11733378].","affinity_potency":[],"species_and_systems":"Human recombinant S19 mutants and synthetic peptides; monocyte C5a receptor [PMID:11733378].","localisation_and_range":"Ligand carries a secreted flag [flag]; paper concerns an extracellular dimer attracting monocytes.","caveats":"Abstract only; no affinity values reported (GtoPdb affinity units not given) [DB:GtoPdb]. One additional paper was review-only and one abstract-insufficient.","key_references":[{"PMID":"11733378","why":"Mapping of S19 dimer binding sites on C5a receptor"}],"covers":["LR001305","LR004702"]},"LR001314":{"pair":"RSPO2 -> LGR6","headline":"RSPO2 binds LGR6 by Fc-fusion binding assay (browser-read) and impaired mutant binding in human disease.","interaction_type":"direct binding","direction_and_effect":"RSPO2, RSPO3 and RSPO4 Fc fusions at about 1 \u00b5g ml-1 bound specifically to LGR4, LGR5 and LGR6 [PMID:21727895]. Human RSPO2 mutants show impaired binding to LGR4/5/6 [PMID:29769720]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"LGR4/5/6 binding is separate from RNF43/ZNRF3 binding; RSPO2 limb function was independent of LGR4/5/6 [PMID:29769720].","affinity_potency":[],"species_and_systems":"Binding assay species not stated [PMID:21727895]; human mutations [PMID:29769720]. Human pair is ortholog-inferred.","localisation_and_range":"RSPO2 secreted per flag [flag].","caveats":"The 21727895 Results sentence was browser-read and its spot-check is pending; the 29769720 paper is abstract only. One abstract-insufficient, one review-only and one different-entity row exist.","key_references":[{"PMID":"21727895","why":"Fc-fusion binding of RSPO2 to LGR4/5/6"},{"PMID":"29769720","why":"RSPO2 mutants lose LGR4/5/6 binding"}],"covers":["LR001314","LR004711"]},"LR001323":{"pair":"RSPO4 -> LGR6","headline":"RSPO4 binding to LGR6 rests on a family-level statement in one abstract and on database records.","interaction_type":"direct binding","direction_and_effect":"Each of the four R-spondins can bind Lgr4, -5 and -6 [PMID:21727895]; GtoPdb records RSPO4 as a full agonist at LGR6 [DB:GtoPdb].","molecular_requirements":"LGR4, -5 or -6 re-expression rescued RSPO1-mediated WNT3A enhancement [PMID:21727895]. Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse gut and HEK293 cells in the paper [PMID:21727895]; IntAct has a pull down record [DB:IntAct]. The mouse pair is ortholog-inferred.","localisation_and_range":"RSPO4 is flagged secreted and LGR6 transmembrane [flag].","caveats":"Abstract only; no RSPO4-specific experiment or affinity is described. One further paper was unresolvable and one abstract insufficient.","key_references":[{"PMID":"21727895","why":"R-spondins bind Lgr4, -5 and -6"}],"covers":["LR001323","LR004720"]},"LR003204":{"pair":"RTN4RL2 -> ADGRB3","headline":"RTN4RL2 binds BAI3 per a family-wide nanomolar-binding statement in one paper; the human pair is projected.","interaction_type":"direct binding","direction_and_effect":"A single TSR domain of BAIs binds all three RTN4-receptor isoforms with nanomolar affinity [PMID:34758294]. BAI3-expressing cells aggregated specifically with RTN4R-expressing cells [PMID:34758294]. Signalling effect not reported for this pair.","molecular_requirements":"The single TSR2 domain of BAI3 binds RTN4Rs [PMID:34758294]. Co-receptors not reported.","affinity_potency":[],"species_and_systems":"Recombinant ectodomains and HEK 293F cells [PMID:34758294]. The human pair is ortholog-inferred; a mouse pair is not.","localisation_and_range":"Trans-cellular adhesion, so contact-dependent [PMID:34758294]. RTN4RL2 carries a secreted flag [flag].","caveats":"Evidence for this pair is a general statement covering all family members, recorded from the abstract; the Kd values in the paper (1.9 nM, 30.0 nM) are for other pairs (BAI3-RTN4R and BAI1-RTN4RL2) and none is reported for RTN4RL2-BAI3.","key_references":[{"PMID":"34758294","why":"family-wide binding to BAI1 and BAI3"}],"covers":["LR003204","LR006424"]},"LR003213":{"pair":"S100A4 -> AGER","headline":"S100A4 binds RAGE in a chondrocyte pulldown and signals to MMP-13; RAGE dependence supported by soluble and dominant-negative RAGE.","interaction_type":"direct binding","direction_and_effect":"S100A4 stimulates chondrocytes to raise Pyk-2 and MAP kinase phosphorylation, activate NF-kappaB and increase MMP-13; this is blocked by soluble RAGE, AGE-BSA or dominant-negative RAGE [PMID:16948116].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human articular chondrocytes, with osteoarthritic cartilage [PMID:16948116]. An IntAct record lists an SPR interaction [DB:IntAct]. Mouse pair is projected.","localisation_and_range":"S100A4 is flagged secreted [flag]; acts on chondrocytes as an extracellular ligand [PMID:16948116].","caveats":"Abstract only; affinity not reported in our evidence. The IntAct record cites a different paper [DB:IntAct].","key_references":[{"PMID":"16948116","why":"Biotin-S100A4 pulldown and RAGE-dependent MMP-13 induction"}],"covers":["LR003213","LR006431"]},"LR003222":{"pair":"S100A7 -> AGER","headline":"S100A7 binds RAGE in a pull-down and RAGE knockdown reduces its pro-migratory effect in osteosarcoma cells.","interaction_type":"direct binding","direction_and_effect":"S100A7 promotes osteosarcoma cell migration and invasion; RAGE siRNA markedly suppressed this and the S100A7-enhanced matrix metalloproteinase activity [PMID:22783409].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In vitro pull-down with recombinant S100A7; osteosarcoma cells, species not stated in the abstract [PMID:22783409].","localisation_and_range":"S100A7 is flagged secreted [flag].","caveats":"Abstract only; no affinity. Binding rests on a pull-down.","key_references":[{"PMID":"22783409","why":"S100A7-RAGE pull-down and knockdown"}],"covers":["LR003222"]},"LR003231":{"pair":"S100A8 -> TLR2","headline":"S100A8 signals partly through TLR2, secondary to TLR4; functional evidence from full text.","interaction_type":"functional only","direction_and_effect":"TLR2-deficient macrophages had an attenuated TNF-alpha release to mMrp8 (p < 0.05), hMrp8 induced NF-kappaB activation in HEK cells expressing hTLR2 (p < 0.01), and an anti-TLR2 mAb attenuated hMrp8-stimulated TNF-alpha from human monocytes (p < 0.05) [PMID:26329314]. Agonist, with TLR2 contributory and TLR4 predominant [PMID:26329314].","molecular_requirements":"TLR4 is the predominant receptor; TLR2 contributes. TLR2 acts as a heterodimer with TLR1 or TLR6 in general, but that is background in the paper and not tested for Mrp8 [PMID:26329314].","affinity_potency":[],"species_and_systems":"Murine macrophages (wild type and TLR-deficient), human monocytes and HEK293 cells expressing hTLR2; mouse pair is not ortholog-inferred [PMID:26329314].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible.","caveats":"Binding to TLR2 is not shown; only functional dependence. LPS contamination was ruled out with heat-inactivation and polymyxin B [PMID:26329314]. Mrp8 pre-exposure also induces tolerance.","key_references":[{"PMID":"26329314","why":"TLR2 contributes to Mrp8-induced inflammation and tolerance, TLR4 predominant"}],"covers":["LR003231","LR006448"]},"LR003240":{"pair":"S100A9 -> MCAM","headline":"MCAM reported as an S100A8/A9 receptor in melanoma cells; abstract-only functional evidence.","interaction_type":"functional only","direction_and_effect":"MCAM and ALCAM function as S100A8/A9 receptors as RAGE does, inducing NF-kappaB activation and ROS formation in melanoma; MCAM activated NF-kappaB more prominently than ALCAM and RAGE [PMID:27151304].","molecular_requirements":"The ligand is the S100A8/A9 complex; S100A9 alone is not separated [PMID:27151304].","affinity_potency":[],"species_and_systems":"Human melanoma cells per the abstract; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand secreted [flag]; MCAM flagged as receptor but not transmembrane [flag].","caveats":"Abstract only; no binding data; no database support.","key_references":[{"PMID":"27151304","why":"MCAM as S100A8/A9 receptor in melanoma"}],"covers":["LR003240","LR006456"]},"LR001332":{"pair":"SAA1 -> SCARB1","headline":"SAA binds SCARB1 (SR-BI/CLA-1) with high affinity, but also inhibits SR-BI function; supported by two binding studies.","interaction_type":"direct binding","direction_and_effect":"125I-SAA, lipid-free or in reconstituted HDL, acted as a high-affinity ligand for SR-BI in CHO cells and bound HepG2 cells; SAA was internalized in an SR-BI-dependent manner [PMID:15561721]. Lipid-free SAA inhibited SR-BI-dependent HDL binding and selective cholesteryl ester uptake, and SAA on HDL decreased selective uptake by 30-50% [PMID:15561721]. In HeLa cells with CLA-1, SAA uptake rose more than 5-fold and SAA bound CLA-1 by cross-linking [PMID:15576377].","molecular_requirements":"Not reported in our evidence; both lipid-free and HDL-bound SAA bind [PMID:15561721].","affinity_potency":[],"species_and_systems":"Human SAA and receptor in CHO, HepG2 and HeLa cells; HDL from SAA-overexpressing mice was also used [PMID:15561721][PMID:15576377]. The mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand, membrane receptor; paracrine/endocrine uptake [flag].","caveats":"Both papers were read as abstracts only. High affinity is stated without a number in the dossier. The effect is mixed: uptake ligand plus inhibitor of HDL uptake. A third confirmed paper is not shown.","key_references":[{"PMID":"15561721","why":"125I-SAA binding to SR-BI and inhibition of HDL uptake"},{"PMID":"15576377","why":"CLA-1 mediates SAA uptake; cross-linking shows direct binding"}],"covers":["LR001332","LR004728"]},"LR005013":{"pair":"Sbpl -> Tlr5","headline":"PAUF associated with TLR5 in a co-immunoprecipitation panel; thin, binding-only evidence.","interaction_type":"direct binding","direction_and_effect":"In co-IP assays in HEK293T cells PAUF associated with TLR2, 5 and 6 but not with TLR3, 8, 9 or 10, suggesting binding to a subset of TLRs [PMID:20802527]. No signalling effect through TLR5 is reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293T co-IP; The paper calls the protein PAUF; curators mapped it to Sbpl, and the mouse pair is ortholog-inferred. [PMID:20802527]","localisation_and_range":"PAUF is secreted [flag].","caveats":"Single co-IP result (supplementary figure) from full text; co-IP shows association, not necessarily direct binding. The paper's text lists the positive TLRs inconsistently (2, 5, 6 versus 2, 4, 5, 6) [PMID:20802527].","key_references":[{"PMID":"20802527","why":"Co-IP panel of PAUF against TLR family members"}],"covers":["LR005013"]},"LR001341":{"pair":"SEMA3A -> NRP2","headline":"One mouse genetic paper (abstract only) reports SEMA3A signalling redundantly through NRP1 and, unconventionally, NRP2.","interaction_type":"functional only","direction_and_effect":"SEMA3A signals redundantly through NRP1 and unconventionally NRP2 in GnRH neuron system development; mice lacking signalling through both NRP1 and NRP2 recapitulate the anatomical features of a Kallmann-syndrome case. Effect is agonist [PMID:21059704].","molecular_requirements":"NRP2 is described as an unconventional receptor for SEMA3A; its usual ligand SEMA3F is dispensable here [PMID:21059704]. Co-receptor needs not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse genetics and in vitro models [PMID:21059704]. The human pair is projected from the mouse interaction (ortholog-inferred flag) [flag].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"Single paper, abstract only; genetic redundancy with NRP1 means NRP2 contribution is inferred, and no direct binding or affinity is reported in our evidence.","key_references":[{"PMID":"21059704","why":"SEMA3A signals through NRP1 and NRP2 in GnRH neuron migration"}],"covers":["LR001341","LR004737"]},"LR001350":{"pair":"SEMA3C -> PLXND1","headline":"SEMA3C signals through PlexinD1 (with NRP1) to inhibit pathological retinal angiogenesis; one paper read from abstract.","interaction_type":"functional only","direction_and_effect":"Sema3C signaled through the receptors Neuropilin-1 and PlexinD1, inhibited angiogenesis and abrogated VEGF-induced AKT, FAK and p38MAPK activation [PMID:26194913].","molecular_requirements":"PlexinD1 is reported together with Neuropilin-1; whether PlexinD1 alone suffices is not reported in our evidence. Full-text excerpts show the furin-cleaved Sema3Cp60 isoform lacked effect [PMID:26194913].","affinity_potency":[],"species_and_systems":"Mouse neonatal retina and oxygen-induced retinopathy model, HUVEC assays and xenografts in mice [PMID:26194913]. Human and mouse pairs are both listed; the mouse record is not ortholog-inferred.","localisation_and_range":"SEMA3C is annotated as secreted [flag], so signalling is expected to be paracrine or autocrine. PLXND1 is annotated transmembrane [flag].","caveats":"Receptor naming is from the abstract; no binding data in our evidence. Other judged rows (abstract_insufficient, review_only) are not shown.","key_references":[{"PMID":"26194913","why":"Sema3C signals via NRP1 and PlexinD1 in retinal angiogenesis"}],"covers":["LR001350","LR004746"]},"LR005301":{"pair":"SERPINF1 -> PLXDC1","headline":"PEDF binds the extracellular domain of PLXDC1 and PLXDC1 mediates cell-type-specific PEDF responses.","interaction_type":"direct binding","direction_and_effect":"PLXDC1 and PLXDC2 were identified as cell-surface receptors for PEDF; knockdown of either decreased PEDF response in RAW267.4 cells [PMID:25535841]. PEDF is reported to dissociate basal receptor homooligomers to activate them [PMID:25535841].","molecular_requirements":"Binding needs the extracellular domain: biotinylated PEDF bound HEK293 cells expressing PLXDC1, with the extracellular-domain deleted form tested as a control [PMID:25535841]. PLXDC1 and PLXDC2 have cell-type-specific roles [PMID:25535841].","affinity_potency":[],"species_and_systems":"Transfected HEK293 cells, and macrophage RAW267.4 and endothelial SVEC4-10 cells (mouse lines named in the excerpts) [PMID:25535841]; dossier labels species human. Mouse pair is ortholog-projected from human.","localisation_and_range":"PEDF is flagged secreted [flag]; PLXDC1 is a transmembrane cell-surface receptor in the paper [PMID:25535841].","caveats":"Single paper; no affinity reported; PLXDC1 and PLXDC2 are not separated in some functional experiments.","key_references":[{"PMID":"25535841","why":"Identifies PLXDC1 and PLXDC2 as PEDF receptors"}],"covers":["LR001971","LR005301"]},"LR003303":{"pair":"SHH -> GPC1","headline":"SHH engages GPC1 as a co-receptor in axon guidance; one abstract-level paper, no affinity.","interaction_type":"functional only","direction_and_effect":"GPC1 is required as a coreceptor for Shh-dependent induction of Hhip in commissural neurons; Shh binds GPC1 to induce its own receptor Hhip, which mediates repulsion of postcrossing axons [PMID:23931997].","molecular_requirements":"GPC1 is a coreceptor; it is not stated whether other subunits are needed [PMID:23931997].","affinity_potency":[],"species_and_systems":"Commissural neurons; species not given in the abstract. The pair in the database is ortholog-inferred in both human and mouse.","localisation_and_range":"GPC1 is flagged secreted [flag] (the paper calls it a heparan sulfate proteoglycan [PMID:23931997]); SHH is secreted [flag].","caveats":"Abstract-only. The experiments show GPC1 dependence of signalling; binding is stated in the abstract without an assay in the dossier. No database records.","key_references":[{"PMID":"23931997","why":"GPC1 as Shh coreceptor for Hhip induction"}],"covers":["LR003303","LR006517"]},"LR005310":{"pair":"SLAMF1 -> SLAMF1","headline":"Homophilic SLAMF1 interaction supported by Fc-binding, functional T-B assays and IntAct records; the paper-level evidence is mixed in strength.","interaction_type":"direct binding","direction_and_effect":"Slamf1-Fc associated with Slamf1-transfected cells but not Slamf8-transfected cells [PMID:25799045]. In human T-B coculture, an anti-SLAMF1 mAb reduced IL-21 and IL-17A producing T cells and Ig production, framed as homophilic interaction [PMID:30058241]. SLAM engagement potentiated PKC-theta and NF-kB1 signalling in a SAP-dependent way [PMID:15539155].","molecular_requirements":"SAP (SH2D1A) is needed for the T-cell signalling effects in PMID:15539155; the Fc-binding assay used single-chain transfectants [PMID:25799045].","affinity_potency":[],"species_and_systems":"Mouse Slamf1-Fc on HEK293 transfectants [PMID:25799045]; human T and B cells from healthy donors and SLE patients [PMID:30058241]; mouse and human T cells [PMID:15539155].","localisation_and_range":"Entity is flagged both secreted and receptor [flag]; binding is cell-surface and contact-dependent in the papers.","caveats":"PMID:15539155 and PMID:30058241 use antibody ligation, which does not itself show binding; the curator notes the homophilic binding in PMID:15539155 is background-cited. mAb effect in PMID:30058241 was labelled antagonist. IntAct records include surface plasmon resonance [DB:IntAct]. No affinity in our evidence.","key_references":[{"PMID":"25799045","why":"Slamf1-Fc binds Slamf1 transfectants, not Slamf8"},{"PMID":"30058241","why":"SLAMF1 homophilic engagement in T-B crosstalk"},{"PMID":"15539155","why":"SLAM engagement signalling via SAP"}],"covers":["LR001981","LR005310"]},"LR003312":{"pair":"SLIT2 -> LRP1","headline":"SLIT2 directly binds LRP1 in a chondrocyte ligandome study; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Direct LRP1 binding of SLIT2 was confirmed among ten ligands, and affinity correlated with endocytosis rate [PMID:36028175]. Annotated agonist; LRP1 acts as an endocytic receptor in this study [PMID:36028175].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Purified-protein binding assays and human chondrocytes, with LRP1-deficient fibroblasts and an Lrp1 conditional knockout mouse for the wider ligandome [PMID:36028175]. Mouse pair is ortholog-inferred.","localisation_and_range":"Soluble ligand taken up by cell-surface LRP1 [PMID:36028175]; SLIT2 flagged secreted [flag].","caveats":"Single paper read as abstract only; SLIT2-specific affinity not given. In vivo knockout data concern the ligand set as a whole, not SLIT2 alone.","key_references":[{"PMID":"36028175","why":"Top-down LRP1 ligandome; SLIT2 direct binding confirmed"}],"covers":["LR003312","LR006526"]},"LR003321":{"pair":"SLURP2 -> CHRNA7","headline":"SLURP-2 binds alpha7 nAChR in brain extracts and has biphasic effects on alpha7 currents; one paper plus an IntAct record.","interaction_type":"direct binding","direction_and_effect":"At human alpha7 nAChR, SLURP-2 enhances ACh-evoked currents at concentrations below 1 \u03bcM (priming) and inhibits at higher concentrations; it does not itself elicit current [PMID:27485575]. In keratinocytes, interaction with alpha7 inhibited proliferation [PMID:27485575].","molecular_requirements":"Alpha7 forms homopentamers, so a single subunit type is sufficient for the receptor [PMID:27485575]. Modelling suggests SLURP-2 occupies the orthosteric site vestibule, a computational result only [PMID:27485575].","affinity_potency":[{"value":"IC50 ~3 \u03bcM","assay":"inhibition of ACh-evoked current, alpha7 nAChR","system":"Xenopus oocytes, human receptor","cite":"PMID:27485575"}],"species_and_systems":"Recombinant human SLURP-2 (rSLURP-2); human receptors in Xenopus oocytes and CHO cells, affinity purification from cortical brain extracts, and human oral keratinocyte Het-1A cells [PMID:27485575]. Species of the brain extract is not reported in our evidence. IntAct lists an affinity chromatography record [DB:IntAct].","localisation_and_range":"SLURP2 is flagged as secreted [flag]; the receptor is flagged as a receptor [flag]. Range is not discussed in our evidence.","caveats":"Effect is concentration dependent (enhancement then inhibition), so activating or inhibitory labels depend on dose. The IntAct record cites a different PMID (26905431) with affinity chromatography and gives no detail [DB:IntAct]. Single primary paper.","key_references":[{"PMID":"27485575","why":"Recombinant SLURP-2 pharmacology and binding to acetylcholine receptors"}],"covers":["LR003321"]},"LR003330":{"pair":"SPARC -> VCAM1","headline":"SPARC is reported as a VCAM-1 counter-ligand needed for leukocyte transmigration; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"SPARC-VCAM-1 interaction induces actin rearrangement and intercellular gaps; leukocyte-derived SPARC binding to VCAM-1 was necessary for transmigration in vitro, and SPARC-null mice have abnormal leukocyte recruitment to inflamed peritoneum [PMID:17178915]. Agonist-like.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In vitro endothelial monolayers (human, per curator) and SPARC-null mice [PMID:17178915]. Mouse pair ortholog-inferred.","localisation_and_range":"SPARC secreted; VCAM1 is flagged both transmembrane and secreted [flag].","caveats":"Abstract only; the quoted evidence is a functional readout rather than a binding assay, and the abstract says 'binding' without detail here. No affinity. No database records.","key_references":[{"PMID":"17178915","why":"SPARC as VCAM-1 counter-ligand in transmigration"}],"covers":["LR003330","LR006537"]},"LR002007":{"pair":"SPON2 -> ITGA5","headline":"Mindin acts through alpha5-containing integrins: antibody blocking in DCs and an inhibitory effect in HCC; abstract-level only.","interaction_type":"functional only","direction_and_effect":"DC adhesion to mindin matrix was blocked by alpha5 antibodies [PMID:16917498]. SPON2-alpha5beta1 signalling inactivated RhoA, prevented F-actin assembly and inhibited HCC cell migration [PMID:29440144]. Effect: antagonist in HCC.","molecular_requirements":"alpha5 partners with beta1 in the HCC report [PMID:29440144].","affinity_potency":[],"species_and_systems":"Mouse DCs [PMID:16917498]; human HCC context [PMID:29440144].","localisation_and_range":"Mindin is an extracellular matrix protein [flag]; alpha5beta1 on the cell surface.","caveats":"Abstracts only; antibody blocking is indirect. Four papers judged confirmed, two shown. No affinity.","key_references":[{"PMID":"16917498","why":"DC adhesion to mindin blocked by anti-alpha5"},{"PMID":"29440144","why":"SPON2-alpha5beta1 inhibits HCC migration"}],"covers":["LR002007","LR005335"]},"LR001404":{"pair":"SPP1 -> CD44","headline":"Osteopontin is a protein ligand of CD44 with direct-binding and functional support in mouse and human systems; CD44 acts mainly in chemotaxis and migration.","interaction_type":"direct binding","direction_and_effect":"Osteopontin was found to be a protein ligand of CD44 and induces chemotaxis [PMID:8560266]. The C-terminal domain of osteopontin acting on CD44 induces macrophage chemotaxis [PMID:12377945]. A phosphorylation-independent Eta-1/CD44 interaction inhibited IL-10 expression [PMID:10657301]. Recombinant human SPP1 recruited LX2 fibroblasts and promoted FAP+ fibroblast formation, reversed by siCD44 [PMID:39095854].","molecular_requirements":"CD44 binding does not need osteopontin serine phosphorylation, unlike integrin engagement [PMID:12377945]. Osteopontin amino termini interact with CD44 in a complement-regulation setting [PMID:11825898]. Co-receptor needs: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse macrophages [PMID:12377945][PMID:10657301]; human cells and recombinant human SPP1 on LX2 stellate cells with HCC conditioned medium and single-cell data [PMID:39095854]; human binding study [PMID:8560266].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; CD44 is flagged both secreted and transmembrane [flag]. Reactome records a SPP1:CD44 plasma-membrane complex [DB:Reactome].","caveats":"Four of five papers were read as abstracts only. The HCC paper is largely single-cell expression with siRNA validation, so it is indirect for binding [PMID:39095854]. PMID:11825898 has CD44 as a surface anchor for Factor H recruitment rather than signalling, and its mapping localises the CD44 interaction to different regions than PMID:12377945 (amino vs C-terminal), which the dossier does not reconcile.","key_references":[{"PMID":"8560266","why":"Osteopontin identified as a protein ligand of CD44"},{"PMID":"12377945","why":"Domain mapping: C-terminal osteopontin acts via CD44 to drive macrophage chemotaxis"},{"PMID":"39095854","why":"siCD44 reverses rhSPP1 effects on fibroblasts"}],"covers":["LR001404","LR004799"]},"LR001413":{"pair":"SST -> SSTR4","headline":"Somatostatin binds and activates SSTR4 (human), supported by cryo-EM structure, radioligand binding and GtoPdb; endogenous peptide is a partial agonist in one assay.","interaction_type":"direct binding","direction_and_effect":"SST-14 is an agonist at SSTR4: Gi-coupled cryo-EM complex of SST-14 with SSTR4 at 2.9 \u00c5 [PMID:35739238]. In a [35S]GTPgammaS assay somatostatin-14 behaved as a partial agonist relative to J-2156, though it acted as a full agonist in a cAMP assay, attributed to receptor reserve [PMID:15333679]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"SSTR4 couples to Gi1 in the structure (scFv16 used for stabilisation) [PMID:35739238]. SST-14 is a cyclic tetradecapeptide with a C3-C14 disulfide; the F7-W8-K9-T10 pharmacophore sits in the receptor pocket [PMID:35739238]. High-affinity agonist binding to hSSTR4 was reduced by GTP and pertussis toxin [PMID:8100352]. A PDB structure is recorded [DB:PDB 7XMS].","affinity_potency":[{"value":"Ki 1.1 nM","assay":"inhibition of 125I-[Leu8,D-Trp22,Tyr25]SST-28 binding","system":"COS-7 membranes expressing hSSTR4","cite":"PMID:8100352"},{"value":"1.5 nM","assay":"binding","system":"SST-14 at SSTR4 (SSTR2 1.4 nM)","cite":"PMID:35739238"},{"value":"pKi 8.4-9.3","assay":"GtoPdb range","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor in recombinant systems (COS-7, HEK293F cells, CCL39 cells) [PMID:8100352][PMID:35739238][PMID:9650799]. The mouse entry is projected from human evidence.","localisation_and_range":"SST is flagged secreted and SSTR4 transmembrane, implying paracrine or endocrine signalling [flag].","caveats":"Several papers were read as abstracts only. Some binding studies used radiolabelled SST analogues rather than SST-14 [PMID:9650799][PMID:8100352]. One study found SSTR4 reacts poorly with synthetic analogues [PMID:7988476]. No in vivo evidence in our dossier.","key_references":[{"PMID":"35739238","why":"cryo-EM structure of SST-14 bound to SSTR4-Gi1"},{"PMID":"8100352","why":"cloning and radioligand binding of hSSTR4, Ki values"},{"PMID":"15333679","why":"SST-14 as partial agonist at SSTR4"}],"covers":["LR001413","LR004808"]},"LR001422":{"pair":"TAC4 -> TACR2","headline":"Hemokinin-1 (TAC4) is a full agonist at NK2 (TACR2) in tissue assays but binds human NK2 with much lower affinity; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"In isolated bioassays HEK-1 was a full agonist at tachykinin NK(1), NK(2) and NK(3) receptors [PMID:11786503]; GtoPdb lists a full agonist [DB:GtoPdb]. Its antagonism by nepadutant in rabbit pulmonary artery is reported [PMID:11786503].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 560 nM","assay":"[125I]-NKA displacement","system":"human NK2 receptor","cite":"PMID:11786503"}],"species_and_systems":"Human NK2 binding; rabbit pulmonary artery bioassay [PMID:11786503]. Mouse pair is ortholog-inferred.","localisation_and_range":"TAC4 flagged secreted [flag].","caveats":"Abstract only. Binding at human NK2 is markedly lower than at NK1, and HEK-1 was about 500 fold less potent than NKA in the rabbit pulmonary artery [PMID:11786503].","key_references":[{"PMID":"11786503","why":"HEK-1 full agonist at NK2 with weak binding"}],"covers":["LR001422","LR004817"]},"LR002016":{"pair":"TFF3 -> ACKR3","headline":"Functional and modelling evidence only that CXCR7 (ACKR3) contributes to TFF3-induced migration; no binding data.","interaction_type":"functional only","direction_and_effect":"TFF3 stimulated cell migration in a conjunctival epithelial cell line, completely suppressed by blocking CXCR4 and/or CXCR7 [PMID:26780310]. The effect is agonist-like for migration; proliferation was unaffected by blocking either receptor, and ERK1/2 activation was independent of CXCR7 [PMID:26780310].","molecular_requirements":"X-ray structure-based modelling predicted CXCR4 and CXCR7 dimers as possible binding partners [PMID:26780310]. Whether CXCR7 acts alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ocular surface tissues and a conjunctival epithelial cell line; mouse pair is ortholog-inferred [PMID:26780310].","localisation_and_range":"TFF3 is annotated secreted [flag].","caveats":"Abstract only. Blocking was of CXCR4 and/or CXCR7 together, so the CXCR7 contribution is not separated. Binding is computational prediction only.","key_references":[{"PMID":"26780310","why":"TFF3 migration blocked by CXCR4/CXCR7 inhibition"}],"covers":["LR002016","LR005344"]},"LR001431":{"pair":"TFPI -> SDC4","headline":"TFPI binds purified human ryudocan (SDC4) with Kd 0.74 nM, mediated by heparan sulfate chains rather than the core protein.","interaction_type":"direct binding","direction_and_effect":"TFPI exhibits significant ryudocan binding; the abstract suggests possible anticoagulation function via heparan-sulfate-binding effectors [PMID:8621465].","molecular_requirements":"Binding depends on the heparan sulfate chains: heparitinase and heparin/HS abolished it, chondroitin ABC lyase and chondroitin sulfate did not [PMID:8621465].","affinity_potency":[{"value":"Kd 0.74 nM","assay":"solid-phase binding, apparent dissociation constant","system":"purified human ryudocan from EAhy926 cells","cite":"PMID:8621465"}],"species_and_systems":"Purified human ryudocan in a solid-phase assay; the mouse pair is ortholog-inferred [PMID:8621465].","localisation_and_range":"TFPI is annotated secreted [flag]; syndecan is a membrane proteoglycan, though that is not in our evidence beyond the pair.","caveats":"Binding is to glycosaminoglycan chains, which other heparan sulfate proteoglycans also carry, so this is not core-protein-specific. Abstract only. One further paper was abstract-insufficient.","key_references":[{"PMID":"8621465","why":"Ryudocan binds TFPI via HS chains, Kd 0.74 nM"}],"covers":["LR001431","LR004826"]},"LR001440":{"pair":"TGFB1 -> ITGB6","headline":"Strong evidence: alphaVbeta6 binds the TGF-beta1 prodomain (structure and cell binding) and activates it.","interaction_type":"direct binding","direction_and_effect":"alphaVbeta6 binds with high affinity to a RGDLXXL/I motif in the prodomains of TGF-beta1 and TGF-beta3 [PMID:25383667]. TGF-beta1 LAP is a ligand for alphaVbeta6, and expressing cells induce local TGF-beta1 activation [PMID:10025398]. UniProt records ITGAV:ITGB6 interacting with TGFB1 [DB:UniProt].","molecular_requirements":"Needs the alphaV partner chain; the LXXL/I helix sits in a hydrophobic pocket of the beta6 subunit [PMID:25383667]. Ligand is the latent prodomain/LAP [PMID:10025398].","affinity_potency":[],"species_and_systems":"Crystal structures and peptide affinity [PMID:25383667]; cell-based work with species unspecified [PMID:10025398]; PDB structure [DB:PDB 5FFO].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Latent complex engaged at cell surface; activation is spatially restricted [PMID:10025398].","caveats":"Affinity values not given in the dossier. Ligand is latent TGF-beta; two further papers abstract-insufficient. PMID:10025398 read as abstract only.","key_references":[{"PMID":"25383667","why":"Crystal structure of alphaVbeta6 with TGF-beta prodomain"},{"PMID":"10025398","why":"TGF-beta1 LAP is a ligand for alphaVbeta6"}],"covers":["LR001440","LR004835"]},"LR003402":{"pair":"TIMP1 -> LRP1","headline":"TIMP-1 binds LRP1 directly (SPR) and engages it on macrophages; effect varies by context and some evidence is via MMP complexes.","interaction_type":"direct binding","direction_and_effect":"SPR showed that all TIMP family members bind LRP1 directly [PMID:32702237]. TIMP-1 alone binds LRP1, while in a glioblastoma model tumour-derived TIMP1 engaged LRP1 on macrophages, increased AKT Ser473 phosphorylation and shifted macrophages toward an immunosuppressive state [PMID:42874178]. The MMP-9/TIMP-1 complex is internalised by LRP, with the binding determinant on MMP-9 [PMID:11279011].","molecular_requirements":"Lysine residues on TIMP-1 are needed: alkylated TIMP-1 failed to bind LRP1 [PMID:32702237]. LRP1 may also take up TIMP-1 as part of MMP complexes [PMID:11279011].","affinity_potency":[{"value":"KD 23 nM to 33 nM","assay":"SPR equilibrium binding of TIMPs (TIMP-1 to TIMP-4) to LRP1","system":"purified proteins","cite":"PMID:32702237"}],"species_and_systems":"SPR with purified proteins [PMID:32702237]; mouse embryonic fibroblasts for the MMP-9/TIMP-1 work [PMID:11279011]; human glioblastoma specimens and murine glioma models [PMID:42874178].","localisation_and_range":"LRP1 is flagged as a receptor and TIMP1 as secreted [flag]; the macrophage action is paracrine [PMID:42874178].","caveats":"The older paper (read as abstract) concerns the MMP-9/TIMP-1 complex, not free TIMP-1 [PMID:11279011]. The glioblastoma paper is an abstract read and does not show direct binding [PMID:42874178]. Three further papers were abstract_insufficient and two were a different entity.","key_references":[{"PMID":"32702237","why":"SPR showing direct TIMP-1 binding to LRP1"},{"PMID":"42874178","why":"TIMP1-LRP1 signalling in macrophages"},{"PMID":"11279011","why":"LRP-mediated uptake of MMP-9/TIMP-1 complex"}],"covers":["LR003402","LR006603"]},"LR003411":{"pair":"TNC -> ITGB6","headline":"Integrin beta6 (with alphav) bound tenascin-C immobilised on beads in MCF-7 breast cancer cell lysates; abstract-level.","interaction_type":"direct binding","direction_and_effect":"Integrin subunits alphav, beta1 and beta6, but not alpha2, bound to TNC immobilized on agarose beads in a divalent cation-dependent manner [PMID:23958855]. TNC treatment increased beta6 protein and alphavbeta6 in focal adhesions [PMID:23958855].","molecular_requirements":"Beta6 pairs with alphav [PMID:23958855].","affinity_potency":[],"species_and_systems":"Human MCF-7 cells [PMID:23958855].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Abstract-level; the antibody result needed combined anti-beta1 and anti-alphavbeta6 [PMID:23958855]. UniProt record concerns fibronectin [DB:UniProt].","key_references":[{"PMID":"23958855","why":"TNC pulldown of alphav, beta1, beta6"}],"covers":["LR003411","LR006612"]},"LR002025":{"pair":"TNFSF12 -> CD163","headline":"CD163 is proposed as a scavenger receptor that takes up TWEAK; one abstract-level human paper.","interaction_type":"functional only","direction_and_effect":"CD163-expressing macrophages bind and internalise TWEAK protein added to the supernatant, consistent with a scavenger role [PMID:19473660]. Higher CD163 in atherosclerotic plaques was associated with lower TWEAK [PMID:19473660]. Effect: clearance, not signalling.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cultured human macrophages, human carotid plaques and plasma from human subjects [PMID:19473660]. The mouse pair is projected, with no mouse experiments shown.","localisation_and_range":"TWEAK is flagged secreted and transmembrane [flag]; CD163 has a receptor flag only [flag].","caveats":"CD163 is called a 'potential' scavenger receptor. Binding is shown in cells, and direct binding and affinity are not reported in our evidence. One paper, abstract only, no database records.","key_references":[{"PMID":"19473660","why":"CD163 binds and internalises TWEAK in macrophages"}],"covers":["LR002025","LR005353"]},"LR001503":{"pair":"TNFSF13 -> TNFRSF14","headline":"Contested: one abstract-only coprecipitation paper suggests APRIL binds HVEM; not corroborated elsewhere.","interaction_type":"conflicting","direction_and_effect":"Purified FLAG-tagged APRIL (TRDL-1alpha) coprecipitated Fas and HVEM in vitro, suggested as an alternate ligand [PMID:10706119]; the same protein caused Jurkat cell death [PMID:10706119].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in vitro and Jurkat cells; abstract only [PMID:10706119].","localisation_and_range":"APRIL flagged secreted, HVEM transmembrane [flag]; the paper reports TRDL-1 membrane association in COS-1 cells [PMID:10706119].","caveats":"Coprecipitation cannot exclude a bridging partner and the abstract hedges. Curator notes call it contested since APRIL's canonical receptors are TACI and BCMA. Only other support is a BioGRID record from the same paper [DB:BioGRID].","key_references":[{"PMID":"10706119","why":"Coprecipitation of HVEM by APRIL, hedged"}],"covers":["LR001503"]},"LR001512":{"pair":"TNFSF9 -> TNFRSF9","headline":"4-1BBL binds 4-1BB with high affinity in two abstract-read papers, plus structures and pathway records; costimulatory.","interaction_type":"direct binding","direction_and_effect":"Agonist: 4-1BB-L-transfected cells and anti-4-1BB antibody induced strong proliferation in mitogen-costimulated primary T cells, while ligation on T-cell clones enhanced activation-induced cell death after TCR/CD3 engagement [PMID:8088337]. GtoPdb lists the pair without type or action [DB:GtoPdb].","molecular_requirements":"Receptor 4-1BB alone; the intact murine protein was required for 4-1BBL binding [PMID:9045669]. Subunit stoichiometry not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human 4-1BB.Fc fusion protein with native and recombinant human 4-1BB-L [PMID:8088337]; murine m4-1BB/m4-1BBL binding, and human h4-1BB bound only h4-1BBL, in the second paper [PMID:9045669]. PDB structures exist with chains of both proteins [DB:PDB 6A3V].","localisation_and_range":"Both entity flags mark the ligand as secreted and transmembrane [flag]; the receptor as transmembrane [flag]. Papers do not describe the range directly.","caveats":"Both papers were read as abstracts only. Affinity is described as high by Scatchard analysis but no value is given [PMID:8088337]. Murine 4-1BB also binds laminin; 4-1BBL binding blocked laminin binding, and this was not conserved in human [PMID:9045669].","key_references":[{"PMID":"8088337","why":"Cloning of human 4-1BB-L; Scatchard high-affinity binding of hu4-1BB.Fc"},{"PMID":"9045669","why":"Murine 4-1BBL/4-1BB binding and laminin competition; human comparison"}],"covers":["LR001512","LR004902"]},"LR003420":{"pair":"TREM2 -> CSF1R","headline":"TREM2 and CSF1R co-immunoprecipitate in HEK293T cells; this is a receptor-receptor association, not a classical ligand-receptor pair.","interaction_type":"direct binding","direction_and_effect":"TREM2 interacted with CSF1R by co-immunoprecipitation, and they mutually modulate expression: CSF1R knockdown increased Trem2 mRNA and CSF1R was increased in Trem2-deficient microglia. TREM2 was not necessary for CSF1-mediated CSF1R and Akt phosphorylation [PMID:33841415].","molecular_requirements":"Full-length TREM2 bound the CSF1R carboxyl-terminal fragment (514-972 aa, with the transmembrane domain), not the amino-terminal fragment; CSF1R bound both TREM2 fragments [PMID:33841415].","affinity_potency":[],"species_and_systems":"HEK293T transfection for co-IP; mouse primary microglia and Trem2-/-;5XFAD mice for function [PMID:33841415].","localisation_and_range":"TREM2 is flagged secreted and receptor, CSF1R transmembrane [flag]; the paper describes transmembrane-domain interaction on the cell surface of microglia.","caveats":"Evidence is co-IP of overexpressed tagged proteins, not purified binding. TREM2 is itself a receptor, so direction is unclear; the curator-assigned agonist label is not shown by the paper's text, which says TREM2 is not needed for CSF1R signalling [PMID:33841415].","key_references":[{"PMID":"33841415","why":"Co-IP of TREM2 with CSF1R and fragment mapping"}],"covers":["LR003420","LR006621"]},"LR011700":{"pair":"TYR -> GPR143","headline":"Database-asserted only: IntAct reports co-immunoprecipitation of tyrosinase with GPR143; no curated papers.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct: anti-tag coimmunoprecipitation (PMID 27720922) [DB:IntAct].","localisation_and_range":"Entity flags give no localisation [flag].","caveats":"Three rows pending, none judged. Support is two IntAct records from one study [DB:IntAct].","key_references":[],"covers":["LR011700"]},"LR001521":{"pair":"UCN3 -> CRHR2","headline":"Urocortin 3 is a selective CRF2 receptor ligand per two abstract-level papers; GtoPdb lists a full agonist.","interaction_type":"direct binding","direction_and_effect":"Agonist: urocortin III is selective for type 2 CRF receptors [PMID:11416224]; stresscopin binding and activation of type 2 CRH receptor [PMID:11329063]; GtoPdb full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKd 7.9 to 8.0","assay":"GtoPdb curated affinity range","system":"not specified in dossier","cite":"PMID:15450949"}],"species_and_systems":"Urocortin III was cloned from human and mouse and tested on the human receptor [PMID:11416224]; the stresscopin study used human peptides and receptor [PMID:11329063]. Both human and mouse pairs are listed, neither ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]; expressed in brain and peripheral tissue by mRNA mapping [PMID:11416224].","caveats":"Both papers read as abstracts only. Mapping stresscopin in PMID:11329063 to UCN3 comes from the curator, since the abstract uses protein names. The PNAS evidence is functional_in_vitro and no binding constant is reported in the abstract.","key_references":[{"PMID":"11416224","why":"Identification of urocortin III as type 2-selective CRF ligand"},{"PMID":"11329063","why":"Stresscopin binding and activation of CRH receptor type 2"}],"covers":["LR001521","LR004911"]},"LR001530":{"pair":"VCAM1 -> ITGB1","headline":"VCAM-1 is a ligand for VLA-4 (alpha4beta1) in adhesion assays; five confirmed rows, all abstract-level, ITGB1 chain recorded alone.","interaction_type":"functional only","direction_and_effect":"VLA-4 on transfected K-562 cells gave specific adhesion to VCAM-1 that anti-VLA-4 antibodies completely inhibited [PMID:1689216]. Myeloma cell adhesion to VCAM-1 upregulated MIP-1alpha and MIP-1beta [PMID:19057841]. Anti-alpha4 integrin reduced monocyte adhesion to human saphenous vein [PMID:12097820].","molecular_requirements":"The receptor is alpha4beta1; the alpha4 subunit was transfected and blocked, so ITGB1 alone is not shown sufficient [PMID:1689216].","affinity_potency":[],"species_and_systems":"Human cell lines and primary cells; K-562 transfectants [PMID:1689216], myeloma/stromal cells [PMID:19057841], monocytes and saphenous vein [PMID:12097820]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-surface adhesion; VCAM1 flagged secreted and transmembrane [flag].","caveats":"All abstract only; functional evidence for the heterodimer, not ITGB1 itself. Species not stated in PMID 1689216 or 9235944. Reactome records alpha4beta1:VCAM1 [DB:Reactome].","key_references":[{"PMID":"1689216","why":"VLA-4 identified as VCAM-1 receptor"},{"PMID":"19057841","why":"VLA-4/VCAM-1 adhesion drives MIP-1 production in myeloma"},{"PMID":"12097820","why":"VCAM-1/alpha4 integrin in monocyte adhesion"}],"covers":["LR001530","LR004919"]},"LR002034":{"pair":"WNT10A -> FZD1","headline":"A glioblastoma abstract reports WNT10A-FZD1 co-IP and JNK pathway activation.","interaction_type":"direct binding","direction_and_effect":"Co-IP assays confirmed an interaction between WNT10A and FZD1, which activated the JNK/c-Jun/FOSB pathway and enhanced FOSB transcription [PMID:40099486].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Glioblastoma cells and orthotopic xenografts, abstract only; species not reported in our evidence [PMID:40099486]. The mouse pair is projected from human.","localisation_and_range":"GBM cells secreted WNT10A into the tumour microenvironment, acting on macrophages and astrocytes [PMID:40099486].","caveats":"Co-IP alone does not show direct binding; four other papers were abstract_insufficient.","key_references":[{"PMID":"40099486","why":"WNT10A-FZD1 co-IP in glioblastoma"}],"covers":["LR002034","LR005360"]},"LR011241":{"pair":"WNT10A -> FZD3:LRP5","headline":"Database-asserted only: an IntAct co-IP record, with no confirmed paper for WNT10A with FZD3:LRP5.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. IntAct EBI-54877040 records an association by anti-tag coimmunoprecipitation [DB:IntAct]; the record is not specific to this complex.","molecular_requirements":"Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the IntAct record are not reported in our evidence.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Judged papers: pending 3.","key_references":[],"covers":["LR011241"]},"LR002043":{"pair":"WNT2B -> FZD7","headline":"Co-IP and knockout data support Fzd7 as a Wnt2b receptor in intestinal stem cells.","interaction_type":"direct binding","direction_and_effect":"Fzd7 binds Wnt2b by co-immunoprecipitation of epitope-tagged proteins in HEK293T cells, extending an earlier Wnt3 finding [PMID:25892522]. Conditional Fzd7 deletion causes intestinal stem cell loss in vivo [PMID:25892522].","molecular_requirements":"Fzd7 alone was tested; closely related Fzds could not fully compensate for Fzd7 loss [PMID:25892522].","affinity_potency":[],"species_and_systems":"HEK293T co-IP and mouse intestine/organoid knockouts [PMID:25892522]; the curator fields list the species as human. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"Binding is shown by tagged co-IP only; the Wnt2b result is an extension in the full text and the abstract is brief. The paper says Fzd7 transmits the signal 'at least in part' [PMID:25892522].","key_references":[{"PMID":"25892522","why":"Fzd7 binds Wnt2b and is needed for stem cells"}],"covers":["LR002043","LR005369"]},"LR003501":{"pair":"WNT4 -> FZD8","headline":"WNT4 shows strong binding to the FZD8 CRD in purified-protein assays.","interaction_type":"direct binding","direction_and_effect":"WNT-4 showed strong binding to the FZD8 CRD [PMID:25605717].","molecular_requirements":"Binding was measured to the CRD-Fc fusion alone [PMID:25605717].","affinity_potency":[],"species_and_systems":"Purified mouse proteins, bio-layer interferometry (Octet) [PMID:25605717]. Mouse pair is direct; human ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"KD values are in a table not shown in our evidence. Browser-read, not spot-checked. Binding only; signalling not reported here.","key_references":[{"PMID":"25605717","why":"BLI of WNT-4 binding to FZD CRDs"}],"covers":["LR003501","LR006701"]},"LR001602":{"pair":"WNT5A -> FZD2","headline":"Wnt5a binds Fz2 and competes with Wnt3a in vitro and in cells, and Wnt5a-Fz2 signalling acts through Rac and calcium; well supported.","interaction_type":"direct binding","direction_and_effect":"Wnt5a activated Rac, requiring Frizzled2 and Ror1 or Ror2 [PMID:19910923]. Wnt5a also competed with Wnt3a for Fz2 binding, inhibiting the beta-catenin pathway [PMID:19910923]. Xwnt-5a enhanced rat Frizzled-2-driven intracellular calcium release via G-protein subunits [PMID:9389482].","molecular_requirements":"Fz2 and Ror1 or Ror2 were required for Rac activation [PMID:19910923]. The FZD2 CRD alone binds WNT-5A [PMID:25605717]. LRP involvement not reported for this pair in our evidence.","affinity_potency":[{"value":"KD = 22\u201326 nm","assay":"Bio-layer interferometry, WNT-5A binding to FZD CRD-Fc, reported jointly for the FZD1/2/4 CRDs","system":"mouse proteins, in vitro","cite":"PMID:25605717"}],"species_and_systems":"Species not specified for the binding paper [PMID:19910923]; mouse proteins for the BLI data [PMID:25605717]; rat Frizzled-2 with Xenopus Wnt-5a in the calcium study [PMID:9389482]. The dossier includes a mouse pair and a projected human pair.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Two of the three papers were read as abstract only. The affinity paper is a browser read with an unverifiable quote [PMID:25605717]. The 1997 study used rat and Xenopus reagents although tagged human [PMID:9389482]. Reactome and BioGRID records support binding [DB:Reactome][DB:BioGRID].","key_references":[{"PMID":"19910923","why":"Wnt5a binds Fz2, competes with Wnt3a, activates Rac"},{"PMID":"25605717","why":"BLI KD for WNT-5A with FZD CRDs"},{"PMID":"9389482","why":"Wnt-5a and Frizzled-2 trigger calcium release via G proteins"}],"covers":["LR001602","LR004991"]},"LR001611":{"pair":"WNT5A -> ROR2","headline":"Well supported: WNT5A binds the ROR2 CRD, with structural, binding and signalling data across several papers.","interaction_type":"direct binding","direction_and_effect":"Wnt5a binds the CRD of Ror2 in vitro [PMID:12839624]. Loss of ROR1/ROR2 decreased WNT5A signalling in MEFs and was rescued by wild-type ROR2 [PMID:38780011]. Curated stimulatory. Purified Wnt5a also inhibited Wnt3a canonical signalling via Ror2 [PMID:16602827].","molecular_requirements":"The ROR2 CRD is required and minimally sufficient; it lacks the hydrophobic pocket seen in other CRDs [PMID:38780011]. Wnt5a coprecipitated with Ror2 but not LRP6 [PMID:18606138]. ROR KO cells retained some WNT5A signalling, indicating additional receptors [PMID:38780011]. Frizzled involvement was suggested by antibody experiments [PMID:38780011].","affinity_potency":[],"species_and_systems":"Recombinant proteins, MEFs, Xenopus and mouse knockouts; WNT5A-SFRP2 complex bound ROR2-ECD in co-IP [PMID:39229119, preprint].","localisation_and_range":"Reactome lists a WNT5A:ROR2:VANGL2 plasma-membrane complex [DB:Reactome R-HSA-4551543]. ROR2 flagged transmembrane [flag].","caveats":"No affinity value reported. Several papers were abstract-only; PMID 39229119 is a bioRxiv preprint whose evidence sentence concerns WNT2B and only mentions WNT5A-SFRP2 as comparison.","key_references":[{"PMID":"12839624","why":"In vitro binding of Wnt5a to the Ror2 CRD"},{"PMID":"38780011","why":"ROR2 CRD structure and requirement for WNT5A signalling"},{"PMID":"18606138","why":"Wnt5a co-IP with Ror2 not LRP6"}],"covers":["LR001611","LR005000"]},"LR003510":{"pair":"WNT5A -> TMEM67","headline":"TMEM67 binds Wnt5a in vitro and is needed for ROR2 phosphorylation by Wnt5a; mouse evidence, one paper.","interaction_type":"direct binding","direction_and_effect":"Agonist-like: TMEM67 is essential for ROR2 phosphorylation on Wnt5a-conditioned medium stimulation, and Tmem67 mutant lung explants fail to respond to Wnt5a [PMID:26035863]. UniProt also records TMEM67 as interacting with WNT5A [DB:UniProt].","molecular_requirements":"The extracellular N-terminal domain (cysteine-rich domain) of TMEM67 binds Wnt5a; ROR2 acts as a co-receptor and interacts with TMEM67 [PMID:26035863].","affinity_potency":[],"species_and_systems":"Mouse knockout and mouse lung explants, in vitro binding assay [PMID:26035863]; pair is ortholog-inferred in both human and mouse.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only. Binding was seen at the ciliary transition zone context only for ROR2 [PMID:26035863].","caveats":"The binding is described as preferential, but the comparison proteins are not given in our evidence. No affinity reported. Curated from the abstract; excerpts available [PMID:26035863].","key_references":[{"PMID":"26035863","why":"TMEM67 binds Wnt5a and is needed for ROR2 phosphorylation and lung branching response"}],"covers":["LR003510","LR006710"]},"LR005004":{"pair":"WNT7A -> FZD9","headline":"WNT7A co-immunoprecipitates with FZD9 in lung cancer cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Wnt-7a was present in Fzd-9 immunoprecipitates, which the authors read as direct interaction; Wnt-7a/Fzd-9 stimulated JNK but not beta-catenin/TCF activity and suppressed anchorage-independent growth [PMID:15705594]. Curator labels the effect antagonist (tumour-suppressive signalling), but the dossier does not define it as receptor antagonism.","molecular_requirements":"Not reported in our evidence beyond Fzd-9 transfection conferring Wnt-7a sensitivity [PMID:15705594].","affinity_potency":[],"species_and_systems":"Human NSCLC cell lines and human proteins [PMID:15705594]. Human and mouse pairs in the dossier are ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only. Co-immunoprecipitation does not show a purified-protein interaction. Signalling is non-canonical (JNK), unlike canonical Wnt7a signalling noted by curators for other receptors [PMID:15705594].","key_references":[{"PMID":"15705594","why":"Co-IP and Fzd-9-dependent Wnt-7a response in NSCLC"}],"covers":["LR001615","LR005004"]},"LR002052":{"pair":"WNT7B -> FZD8","headline":"WNT7B induces canonical signalling via FZD8 (and FZD5) in a FZD-knockout reporter system; functional, not binding, evidence.","interaction_type":"functional only","direction_and_effect":"Wnt7b induced canonical Wnt signalling via FZD5 and FZD8 in rescue experiments [PMID:28733458].","molecular_requirements":"FZD8 alone sufficed in the rescue setup; no co-receptor requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor constructs in HEK293 reporter cells lacking multiple FZDs [PMID:28733458]. The mouse pair is projected from human evidence.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Single paper, a functional rescue map rather than a binding assay. FZD5 and FZD8 are described as highly similar and promiscuous, so paralog redundancy is likely [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Wnt-FZD functional interaction map in HEK293 knockout cells"}],"covers":["LR002052","LR005378"]},"LR011322":{"pair":"WNT9A -> FZD9:LRP5","headline":"WNT9A signalling through FZD9 with LRP5: functional evidence from one zebrafish/human-cell study, with LRP5 shown necessary for signalling.","interaction_type":"functional only","direction_and_effect":"The study reports that Wnt9a signals through Fzd9b, the co-receptor LRP5 or LRP6, and EGFR; the Wnt9a-Fzd9b complex was endocytosed and this was required for signalling [PMID:38626007].","molecular_requirements":"LRP5/6 double knockout HEK293 cells showed no Wnt9a-Fzd9b signalling, so LRP5/6 are required for signal transduction but not for endocytosis; AXIN also required for signalling; EGFR-dependent endocytosis is needed [PMID:38626007]. The study does not separate LRP5 from LRP6 (double knockout and 'LRP5/6').","affinity_potency":[],"species_and_systems":"Human cells (HEK293) with fluorescent Wnt9a and Fzd9b (zebrafish Fzd9b) fusion proteins; zebrafish used for development [PMID:38626007].","localisation_and_range":"WNT9A/WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor chains are membrane receptors [flag].","caveats":"Curator row is abstract_only although full-text excerpts were available. Study concerns zebrafish Fzd9b, not human FZD9 directly; no binding assay or affinity reported. LRP5 and LRP6 not distinguished.","key_references":[{"PMID":"38626007","why":"Wnt9a-Fzd9b endocytosis and LRP5/6 requirement"}],"covers":["LR011322"]},"LR002061":{"pair":"WNT9B -> FZD8","headline":"WNT9B binds mouse Fz8 CRD only weakly by biolayer interferometry and induces FZD8 signalling in a human reporter map.","interaction_type":"direct binding","direction_and_effect":"Wnt9b binds Fz8 CRD only very weakly compared with Wnt3a, Wnt5a and Wnt5b [PMID:20093360]; Wnt9b induced canonical signalling with FZD5 and FZD8 in a reporter assay [PMID:28733458].","molecular_requirements":"Wnt9b binds a different part of the LRP6 extracellular domain (E1E2) from Wnt3a; the Fz8 CRD was the soluble Frizzled fragment tested [PMID:20093360].","affinity_potency":[{"value":"KD 482 nM","assay":"biolayer interferometry (Octet), Wnt9b to Fz8 CRD-Fc","system":"purified mouse Fz8 CRD, purified Wnt9b","cite":"PMID:20093360"}],"species_and_systems":"Binding used purified mouse Fz8 CRD and Wnt (mouse) [PMID:20093360]; signalling in human HEK293 FZD panel [PMID:28733458].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Binding is very weak (482 nM) and uses a CRD fragment only; the Wnt5a and Wnt5b KD values (50 nM, 36 nM) in the same paper are tighter [PMID:20093360]. The full-text reporter result is functional only.","key_references":[{"PMID":"20093360","why":"Wnt9b KD 482 nM to Fz8 CRD by biolayer interferometry"},{"PMID":"28733458","why":"WNT9B signals via FZD8 in rescue reporter map"}],"covers":["LR002061","LR005387"]},"LR008100":{"pair":"WNT9B -> FZD8:LRP6","headline":"Database-asserted WNT9B to FZD8:LRP6 complex; no curator-verified paper supports the complex as a unit.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. UniProt subunit notes assert that FZD-family O14905 (WNT9B) interacts directly in the complex with LRP6 and that LRP6 (via beta-propeller regions 1 and 2) interacts with WNT9B [DB:UniProt].","molecular_requirements":"The complex is the FZD8 plus LRP6 pair; no experiment in our evidence tests the combination. Support is from UniProt notes about WNT9B and LRP6 only [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the UniProt records cite PMID 20093360 and PMID 11357136 but no dossier paper was verified for this complex [DB:UniProt].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Rests on database records alone; the notes do not name the Frizzled chain. Papers were judged only as review_only or abstract_insufficient. Treat as a projection from WNT9B-LRP6 evidence.","key_references":[],"covers":["LR008100"]},"LR001620":{"pair":"XCL1 -> XCR1","headline":"Well supported direct agonist pair: XCL1 binds XCR1 (Kd 10 nM) and activates it in human cell systems; mouse pair is also listed.","interaction_type":"direct binding","direction_and_effect":"XCL1 (SCM-1alpha) is an agonist of XCR1: it induced chemotaxis and calcium mobilisation in XCR1 (GPR5)-expressing L1.2 cells, with pertussis-toxin-sensitive migration indicating Galpha-type G protein coupling [PMID:9632725]. The monomeric XCL1 form binds and activates XCR1, while the dimer binds glycosaminoglycans and lacks XCR1 agonist activity [PMID:25497737]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"Single-chain receptor, no co-receptor reported. The monomeric (Ltn10) conformation is the active form; the dimer is not [PMID:25497737]. Reactome describes an XCR1:XCL1,XCL2 complex [DB:Reactome]. A PDB structure with one chain of each partner exists [DB:PDB 9AST].","affinity_potency":[{"value":"Kd 10 nM","assay":"specific binding to receptor-expressing cells","system":"L1.2 cells expressing GPR5/XCR1, human SCM-1alpha","cite":"PMID:9632725"},{"value":"pEC50 7.3","assay":"functional activation by monomeric XCL1 (curator-recorded)","system":"human ligand and receptor","cite":"PMID:25497737"}],"species_and_systems":"Human ligand and receptor, recombinant, in murine L1.2 cells [PMID:9632725] and XCR1-transfected HEK 293 cells [PMID:25497737]. One further paper used mouse T cells in vitro and in vivo, but only correlated migration with XCR1 mRNA [PMID:11446740].","localisation_and_range":"XCL1 is flagged secreted and XCR1 transmembrane [flag]; this implies paracrine chemokine signalling. The dimeric form binds extracellular-matrix GAGs [PMID:25497737].","caveats":"The binding result was read from the abstract only [PMID:9632725]. The mouse study is correlative, not direct binding [PMID:11446740]. XCL2 shares the receptor, so XCL1 and XCL2 are not distinguishable by XCR1 expression alone [PMID:25497737].","key_references":[{"PMID":"9632725","why":"Identified XCR1 as the receptor; Kd 10 nM"},{"PMID":"25497737","why":"Monomer activates XCR1; dimer binds GAGs"},{"PMID":"11446740","why":"Mouse T-cell migration correlated with XCR1 mRNA"}],"covers":["LR001620","LR005009"]},"LR000702":{"pair":"GDF6 -> BMPR1A","headline":"Functional and binding evidence from papers using ALK3/BMPR-IA naming; GDF6 acts as an agonist, though one study found only weak BMPR-IA binding.","interaction_type":"functional only","direction_and_effect":"Overexpressing ALK3 or ALK6 in COS7 cells conferred GDF6 signalling, and ALK3 shRNA suppressed Smad signalling induced by GDF6 and two other ligands, consistent with an agonist [PMID:16049014]. CDMP-2 (GDF6) bound BMPR-IB and BMPR-II with affinity and BMPR-IA only weakly [PMID:9525338].","molecular_requirements":"Both type I receptors ALK3 and ALK6 conferred GDF6 signalling [PMID:16049014]. CDMP-2 signalling through BMPR-IB needed BMPR-II [PMID:9525338]. A third paper tested BMP13 (named GDF6's alias in PMID:16049014) and reported binding of ALK3, ALK6 and type II receptors [PMID:21702718].","affinity_potency":[],"species_and_systems":"Human recombinant ligand and receptors in all three papers; cells were COS7 and MC3T3 [PMID:16049014] and primary chondrocytes plus osteogenic cell lines [PMID:9525338]. Binding was by Octet or surface plasmon resonance [PMID:21702718].","localisation_and_range":"GDF6 is flagged secreted and BMPR1A transmembrane [flag], so paracrine signalling is implied by the flags.","caveats":"All three papers were read as abstracts (two have full-text excerpts). The CDMP-2 binding result is weak for BMPR-IA [PMID:9525338]. The BioGRID record in the dossier is for GDF6 - BMPR1B, not BMPR1A [DB:BioGRID]. Receptor names (ALK3, BMPR-IA) are mapped to BMPR1A by the curators. The mouse pair is projected from human evidence.","key_references":[{"PMID":"16049014","why":"ALK3 overexpression and knockdown set GDF6 signalling"},{"PMID":"9525338","why":"CDMP-2 (GDF6) receptor binding, BMPR-IA weak"},{"PMID":"21702718","why":"BMP13 binding to type I and II receptors"}],"covers":["LR000702","LR004186"]}};